/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20160726-8","meetingId":"h28-cm07","date":"2016年7月26日","dateIso":"2016-07-26","committee":"建設委員会","time":"午後 １時００分～午後 ２時３４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２８年８月都営住宅入居者募集","agenda":"平成２８年８月都営住宅入居者募集","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今回は都で１,５９４戸ということで、この間、私どものところにも、住宅相談、また都営住宅に入りたいという要望は絶えないわけです。８番の休日相談窓口が開かれているというところですけれども、ここには大体どれぐらいの方がご相談にいらっしゃっているのかを伺いたいと思います。","respondent":"今井住宅課長","answer":"とても幅が広いものですが、１０件以下です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"こうした公営住宅に入りたいという方が増えているというところで、少し関連してなのですけれども、先日の本会議の一般質問のところで、品川駅南の開発にかかわって、北品川の都営住宅も範囲に入っているわけなのですが、そこについての質問をされたときに、区長が、東京都について、この計画に我関せずではなく当事者として関与してほしいということで。","respondent":"東野まちづくり立体化担当課長","answer":"そこの中に都営住宅を含んでいることになりますので、当事者として、その再開発の勉強会等に参画いただきたいということで、現在も都に働きかけをしています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"どのように動くかということを見定めて、東京都に対して強く働きかけていきたいとも言っているのですけれども、要は、あそこの都営住宅を開発でなくしていくということなのでしょうか。地域の皆様から不安の声も大変たくさん出ているところなのですが、これを区も積極的に進めていくということで進んでいるのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"意見","question":"やはり公営住宅に入りたいという方が増えているもとで、オリンピックを口実に、またそういった開発が進む中で、都営住宅がなくなっていくということに各地で声も上がっています。裁判にもなろうという状況に、もうあるところもあるということです。ぜひ安心して住み続けられる公営住宅を増やしていくことこそ必要だと思いますので、それだけ主張して終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-004"},{"speaker":"塚本委員","kind":"意見","question":"８番の休日相談窓口なのですけれども、先ほどの質疑で１０名以下という相談実績ということですが、どういうことを目的とした相談窓口になっているのかお知らせください。","respondent":"今井住宅課長","answer":"あくまでも都営住宅のことですので、その住宅の内容ではなくて、どちらかというとなかなか読みづらいこのようなパンフレットの内容を詳しくご説明しながら、書き方をご案内する形になっております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"塚本委員","kind":"確認","question":"相談窓口期間に関して言えば２日間だけなので、その辺のところでのご案内というのは、こちらにしていけばいいということでよろしいのか、確認します。","respondent":"今井住宅課長","answer":"そういう意味では、実際にはそれぞれ入居者募集について、土日は開けしていますが、その点を含めまして、通常の窓口でも対応を幅広く行っている状況です。","voiceIndex":15,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"これは都営住宅なので、東京都全体の申込みという形になると思うのですが、状況によってかなり変わってくるかと思いますが、品川区在住の方が入れる確率は、どういう実態があるのでしょうか。","respondent":"今井住宅課長","answer":"前回の応募状況につきましては、事務事業概要のほうにも都全体で載せさせていただいているところですが、東京都から示されていますのが、前回、２月の応募状況につきましては、平均倍率が都全体で７.８倍ということで、品川区については。","voiceIndex":17,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"品川区在住だけれども、ほかのところでもいいという方ももちろんいらっしゃると思うのですが、実際、品川区の方々が都営住宅にどのぐらい入られたかというのはわからないのでしょうか。","respondent":"今井住宅課長","answer":"申し訳ございませんが、この応募倍率は、今ございましたとおり、品川区の中で空きが出ている戸数に対しての応募状況でございまして、どこの区の住宅に申し込んでも構わないことになっておりますので、そういう区民の申込みのデータとしては公表されておりません。","voiceIndex":19,"id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"熊本地震は今までにないようなタイプの地震というのを受けて、熊本地震の新たな特徴というところから、首都直下地震の防災対策について見ていかなければいけない点、留意しなければいけない点とか新たな課題、そういうところをどのように今、区の防災課としては見ていらっしゃるのか、何かあればお聞きしたいと思います。","respondent":"古巻防災課長","answer":"具体的に、２回も大きな地震、もしくは大きめな地震がかなりの回数起きているという状況については、なかなか過去に例のないところですので、こういうことに関する、主にハード系の対策になるかと思っているのですけれども、国のほうでも今、分析を進めているところですので。","voiceIndex":25,"id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"それはもちろん品川区だけではなくて、最初は国のレベルからということで、国の対応を見てというお話もあったと思うのですけれども、そういった国の対応を得て、そしてまた、それを地方自治体に、この検証のステップ、進め方はどういうふうな見通しになるのかお聞きします。","respondent":"古巻防災課長","answer":"防災課といたしましては、来年度に向けて地域防災計画の改定を計画しています。今年度、そういった来年度の計画の修正に向けまして、事前の調査ということで、委託で調査、それから来年度の改定の方向性を定めるという形で事業を進める予定になっております。","voiceIndex":27,"id":"exchange-010"},{"speaker":"塚本委員","kind":"質問","question":"もうちょっと詳しく聞くのですけれども、そういう初動対応レポートということで、いわゆる国の動きがあってということですが、今すぐ思い出せないのですけれども、例えばこの前の感震ブレーカーをもっと進めるべきだとか、防災の方針を出したりとか、そういう国の会議体があったと思うのですけれども、そこがやはり中心となって、熊本地震を受けた対応、また。","respondent":"古巻防災課長","answer":"今回の初動対応に関するレポートは、特別な検証チームが構成されて、そちらの検証チームによる検証結果、レポートということで報告が出ておりますので、この検証チームがある程度、初動対応に関して検証を進めていくという流れになると考えているところです。","voiceIndex":31,"id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問","question":"３の2)の避難所の運営のことについてお伺いしたいのですけれども、各学校に学校避難所マニュアルがあると思うのですが、これは実際、発災をしてから避難所として機能するということだと思うのです。もう一つ、(3)のボランティアの中の1)支援内容のところの医療の中に、医師と看護師は入っているのですが、その中に薬剤師も含まれるのではないかと思うのですけれども、その３点をお聞きします。","respondent":"古巻防災課長","answer":"１度つくってしまったものについての改定については、適宜、状況に応じた変更を加えていくという形で、防災課が主体になりまして、働きかけをしていきたいと考えております。","voiceIndex":33,"id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"実際、本当に発災したときに、マニュアルというのは新しくしていかなければいけないと私は思っているので、その辺は強く防災課から、もう一回、仕切り直しをしていただきたいと考えています。薬剤師についても、品川区医師会、荏原医師会との連携をとっていただいて、ボランティアの薬剤師についても防災課でもう一回、協議をしていただければと思います。","respondent":"古巻防災課長","answer":"避難所運営に関しまして、委員からご指摘いただいた点、十分に防災課としても認識をさせていただきまして、今後てこ入れと申しますか、教育委員会とも連携をとりながら進めてまいりたいと考えておりますので、よろしくお願いします。","voiceIndex":35,"id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"やはり物資の運送等が困難になる状況が発生し得ると考えられると思うのですけれども、耐震性がしっかりしているマンションとか戸建ての人で、避難所に入るまでもないけれども、ただ物資が不足している人の対応というのはどうお考えなのかということがまず１点。それから海上輸送なのですけれども、運河から目黒川を利用するということもお考えなのかということが３点目の質問です。","respondent":"古巻防災課長、和田河川下水道課長","answer":"１点目の、避難所に入るまでもない方への支援等の対応ですけれども、基本的にマンション等につきましては、在宅での避難をメインに対策を考えておりますので、自助という点できちんと対策をとっていただくというところが。詳しくは、次回の委員会の所管事務調査で、舟運の災害対策活用についてということでご説明差し上げます。","voiceIndex":37,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"避難所、物流、ボランティアという３点を今日はご説明いただいたのですが、今回の熊本地震では報道等でも、避難所の駐車場等で生活する、また車の中で生活するということで、すごく避難先というのがクローズアップされたという感じは受けるのです。木造住宅の耐震化というのを品川区は目標を持って進めてきていたと思うのですが、そこは今、どこら辺まで来ているのかを伺いたいと思います。","respondent":"鈴木建築課長","answer":"木造住宅の耐震化率ですが、概算になりますけれども、今年の１月現在、約７２％です。","voiceIndex":40,"id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"それに対応していくには、地域防災計画が改定されるということですけれども、本当に細かく多彩に考えていかないと、この間の阪神・淡路大震災、東日本大震災、熊本地震の教訓をさらに細かく入れていける状況になると思うので、今、出された数で、そしてこれだけの耐震化率で、避難所は対応していけるのかということがいつも不安なのですが、そこら辺はどのように考えられているのでしょうか。","respondent":"古巻防災課長、鈴木建築課長","answer":"避難所の整備に関しましては、地域防災計画が想定しております、東京都の被害想定に基づいた避難者数に対してきちんと対応できるような整備を行っていると考えているところです。建物の耐震性の観点からいきますと、やはり１軒でも多く、区としても建替え耐震化を図っていただくというところで、地震に強い建物にしていただいて、在宅避難で対応いただくというのが基本だと思います。","voiceIndex":42,"id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"住民とすると、地震が来ると避難というのがまだ広くあると思うのですけれども、自宅が残っている方は在宅避難という区としての呼びかけというのはどれぐらいやられているのか。今、耐震化のところでも情報伝達が大事だということだったのですが、耐震化率の目標があったかと思うのですが、今、７２％というのはどういうところまでなのかを教えていただきたいと思います。","respondent":"古巻防災課長、鈴木建築課長","answer":"先ほど建築課長から答弁がありましたとおり、在宅で避難されている方への情報提供といったところについても、きちんと対応を考えていきたいと考えております。耐震化率の目標ですが、平成３２年度までに９５％という目標を定めてあります。","voiceIndex":45,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"でも、火災が起きたときに、どういう流れになるのですか。それから補完避難所、二次避難所というのが書いてありますけれども、誰がどういう判断をするのですか。誰がどう判断をして、この人はこの避難所へ行ってくださいというのを言うのですか。まだまだ整備が必要だと思います。ではどうするのですか。調達物資とありますが、品川区に来るという命令系統は、誰がどういうふうにしてくるのでしょうか。","respondent":"寺嶋木密整備推進課長、古巻防災課長、鈴木建築課長","answer":"そこの地区の災害を他のエリアに広げないという取組みをしているところが、火災シミュレーション等も踏まえた対応となっておりまして。それから主体に関しましては、基本的には、避難所の運営につきましては、発災時には避難所運営会議といった形で主体を担うという計画になってありますので。応急危険度判定につきましては、区に現在登録していただいている方は１００名程度いるのですけれども、当然ながら。","voiceIndex":48,"id":"exchange-018"},{"speaker":"西本委員","kind":"提案","question":"建物の応急危険度判定についても、そういうルートができているのであれば非常に安心ではありますが、国から都から区という３段構えになると、要望がどれだけスムーズにいくのかというところは不安ではあります。私、委員長に提案をしたいのですが、これは所管事務調査という形になるので、今回の第２回定例会で例を出させてもらいましたけれども、避難所シミュレーションのゲームみたいなものがあるのです。","respondent":"曽田災害対策担当部長","answer":"全く空輸がないというわけではありませんけれども、今、中央公園で準備をしておりますのは、災害当初の発災時の自衛隊の移動だとか、あるいは患者を救急病院に搬送するためのヘリの運用ということで、何分、中型ヘリ、小型ヘリぐらいの広さしかありませんので。","voiceIndex":52,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"今の空輸についてですが、私はこれは全体の話になっていると思うのです。規模とかはありますから、その規模が大きい部分という形での、今日の説明なのだろうと思うのですけれども、品川区がせっかくすばらしいことをやっているので、もう初めからそういうことを視野に入れてやっていただきたいという要望をします、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"基本的なところなのですけれども、避難所に入られる方というのは、早い者勝ちになってしまうのですか。西本委員が先ほどおっしゃいましたけれども、避難所に帰宅困難者等も含めると、あっという間に避難所が埋まってしまう可能性もあるので、そこら辺りの振り分けというか解決方法というのはどうお考えなのかということが２点目。３点目は、二次避難所と福祉避難所のこの振り分け方もどうされるのか。","respondent":"古巻防災課長","answer":"要支援者の支援計画というのは、個別計画の策定の推進も今年度モデルケースとして進めてまいりますので、そういった中でも、実際に要支援の方がどういった形で避難をするのかというところも具体的に、もう少し個別の計画の中で対応を考えていきたいと思っているところです。","voiceIndex":55,"id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"ある程度、客観的に要支援者とかの証明があって、それを避難所運営している方が見て判断するという理解でいいのでしょうか。","respondent":"古巻防災課長、松代防災まちづくり部長","answer":"もしくは、その方が直接判断できなくても、個別の計画運用の中で、どういった形の避難をしていくのかというところがわかるように整備をしていきたいと考えております。しかし、誰が行っても対応できるようなものをまずマニュアルでつくるというのをこれまでずっと進めてきて、避難所連絡会議を通して、一定のマニュアル的なものを用意しました。","voiceIndex":57,"id":"exchange-022"},{"speaker":"西本委員","kind":"提案","question":"先ほどもご提案をさせていただきました。これはぜひ、所管事務調査という形の位置付けで、取り上げていただければと思っています。資料をお持ちします。連絡先もお持ちします。それをぜひ検討していただきたいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"提案","question":"今後も今みたいな形で、取り上げていきたい内容というのは聞いていただけるのですか。ちょっと今は具体的なものがないのですけれども、今後もこういった形で、こちらから提案ということは。","respondent":"若林委員長","answer":"適宜、いただいても結構ですけれども、何せ回数が、行政視察も含めて、何回とれるかということもあるので、これだけでも議論百出するようなことを想定していますので、その時々に正副で調整させていただきたいと思います。今後について、何かご意見はありますか。","voiceIndex":62,"id":"exchange-024"},{"speaker":"塚本委員","kind":"意見","question":"この後、行政視察についてやられると思うのですけれども、今あるこの案を見ていくと、結構、防災対策系のことが出ていますので、所管事務調査を次にやる時期は、おそらくこの行政視察の後ぐらいになるかと思うので、行政視察の内容をうまく活かす、うまく連携した形がいいかと思っているところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-025"}]},{"id":"topic-02","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"例えばこういうものを見てください、それに対して、見ることによって何かを期待するという部分もあるかと思うのですけれども、そこら辺はどうなのですか。これからになると思うのですけれども、それに対して、私たちの調査項目と合わせてリンクできれば一番いいのでしょうし、何かこちらサイドでも支援みたいな形で、ただ行って、ああ、そうだの、こうだのだけではちょっと申し訳ないと思っているのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ぜひ、今言った形で、最終的には正副にお任せいたします。今これを見ていて、この前長崎市も雨で、土砂でやられていました。家が二軒ぐらい、すごい状況もあったです。横浜あたりも結構あるのだけれども、あの崩れ方はすごいと思います。熊本市とか久留米市とか、久留米市というと、どちらかというと福祉関係のところが多いかと思ったのだけれども、その辺のところはお任せします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4178#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":25978,"voices":71}},{"id":"h28-20160726-9","meetingId":"h28-cm07","date":"2016年7月26日","dateIso":"2016-07-26","committee":"文教委員会","time":"午後 １時００分～午後 ３時１０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"「居住実態が把握できない児童」に関する調査","agenda":"「居住実態が把握できない児童」に関する調査","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"これは件というふうにあるのですけれども、お子さんはお一人なのでしょうか、それともご家族で１件とカウントされているのか。結構長く品川区内に居住されていたかどうかなども、書類上わかるのでしょうか。","respondent":"高山子ども育成課長","answer":"このカウントの仕方なのですが、１児童について１件というカウントの仕方です。１世帯でも複数いる場合は２件でカウントさせていただいているところです。","voiceIndex":7,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"そもそものことなのですけれども、居住実態が把握できない児童の調査というのは、実態が把握できずに虐待などで亡くなってしまう児童が出ないための調査ということでいいのか確認させていただきたいと思います。","respondent":"高山子ども育成課長","answer":"そもそもこちらの調査の目的ですが、そういったネグレクトも含めた児童虐待につながるような状態で児童が放置されていないかということを確認する趣旨で、当初よりこの調査が始まったところです。","voiceIndex":10,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"わかりました。昨年は４件、今回は８件ということで、こういった事態がどうして起きるのか、普通に生活している中でどうしてこういったことが起きると考えているのか見解を伺いたいと思います。","respondent":"高山子ども育成課長","answer":"残る１件に対する認識という点なのですが、必ずしもネグレクトを含めた虐待かどうかという点については、やはり正直暮らしぶりの現状を確認できれば、それで特段問題がないケースというのもありますので。","voiceIndex":12,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"すみません、ちょっと行ったり来たりしてしまいますが、目的のところに書いてある安全の確認が必要と判断した児童というのがあるのですけれども、これはどういう判断で安全の確認が必要だということになるのか、ご説明いただきたいと思います。","respondent":"高山子ども育成課長","answer":"児童が親御さんのもとで安全に暮らしているかというところの判断ということなのだと思うのですが、それについては訪問させていただいて、実際に親御さんのお話をする中で、お子さんの成長なども見する中で。","voiceIndex":14,"id":"exchange-004"},{"speaker":"のだて委員","kind":"確認","question":"それとあと、先ほどもありました定期健診等をやる中で、安全確認ができたところは必要ないというところで、確認ができないところについて調べていくという考え方でいいのでしょうか。品川区の中でそういった必要と判断する基準みたいなものはあるのでしょうか。","respondent":"高山子ども育成課長","answer":"先ほど申しました保健センターのケース、すくすく赤ちゃん訪問事業でありますとか、あるいは１歳６カ月健診などに加えまして、例えば学齢期になっても就学が確認できないということも一つそういう居住実態が把握できていない児童ということになってまいりますので。","voiceIndex":16,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"その作業というのは、どのくらいかかって行われているのか、これで大体子どもたちの問題というか、明らかになっていくのかどうかというところをお伺いします。","respondent":"高山子ども育成課長","answer":"毎月、今回は６月１日ですが、７月１日、８月１日ということで、それぞれの時点において居住実態が把握できない児童というのは、やはり入れかわりといいますか、確認できたものと新たに確認を要するものといった形で移っていきますので。","voiceIndex":18,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"残る１件ということで、先ほども事件性がないことを祈るというご発言がありましたけれども、その後のフォローというのは追っかけていくということで、対策会議でその後新たに対策をとったとか、フォローのところで何か事件性とかにかかわったような、まだ平成２６年からですから、そんなにたっていないのですけれども、あったらご紹介していただきたいと思います。","respondent":"高山子ども育成課長","answer":"当該児童と接触して、先ほども申しましたように、子どもの安全が確認できたということであれば、これはいわゆる事件としては終了という形になりますので、その後もやはりケアが必要、フォローが必要ということであれば、継続的に訪問したりとかという形で。","voiceIndex":20,"id":"exchange-007"}]},{"id":"topic-02","title":"平成２８年４月認可保育園等の入園状況（指数）","agenda":"平成２８年４月認可保育園等の入園状況（指数）","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"資料の確認なのですが、別表(2)の３番のところで、ひとり親に準ずる世帯とあるのですけれども、準ずるというのは、どういう場合をいうのか、ご説明いただければと思います。９番のところで、認可外保育施設等に預けている場合、月額２万円以上が３点、２万円未満が１点とありますけれども、月額２万円未満の施設はどういったところがあるのか、ご説明いただければと思います。","respondent":"竹田保育課長","answer":"それから２０番ですが、３カ月に満たない場合ということで、例えば１２月にお申し込みいただくときは、９月、１０月、１１月の３カ月を基本的にはお出しいただくのですけれども、３カ月に満たない場合と既にずっとご勤務いただいて３カ月お出しできる方の場合に。","voiceIndex":26,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"９番のところで、２万円以下の施設は少数だということでしたけれども、何施設あるのか伺いたいと思います。先ほどご説明のところで、この資料をホームページで公開していくということでしたけれども、やはり選考に当たっての資料ということであれば、窓口でお知らせするとか、もう少し積極的に知らせていく必要もあるのかなと思うのですが、ホームページ以外の周知の方法をご検討であればお聞かせください。","respondent":"竹田保育課長","answer":"お電話等でもお問い合わせに応じておりまして、より深くご理解いただけるように努めているところです。それから、指数ですが、先ほど申し上げたとおり本日ご説明した後、近日中にホームページに公開してお知らせしていくものです。","voiceIndex":28,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"窓口でも必要な方にはということでしたけれども、そういった資料があるということはわからないと思うので、ぜひご説明して、要るかどうかを聞いていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"その確認と、それからホームページに載せるときに、そこのところは丁寧に書いておかないと、まさか４０の人だけが入れるという読み方をする人はいないとは思いますが、読む方はこういうことを日々取り扱っている方ではないので、ちょっと丁寧に添えていただいて、この保育園だったら４０ぐらいないと入りにくいのだなとか。","respondent":"竹田保育課長","answer":"ホームページに掲載するときは、丁寧な説明に努めたいと考えております。","voiceIndex":31,"id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、１次の結果をホームページで公表して、また最終的に４月段階でどの指数の方が入るのかというのは、また公表するということなのですか。それとも、１次のものを目安として公表して終わりということなのか、そこを教えてください。","respondent":"竹田保育課長","answer":"全体の入園数から見ますと、１次の部分で大半が占められておりますので、２次あるいは辞退等の補充部分はごくわずかですので、そちらのほうの公表は考えておりませんので、この１次をもって選んでいただくように考えております。","voiceIndex":33,"id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"ただ、それはどういう性格の数字で、どういう内容が入っていて、その後一部ではあるけれども、それ以下の人が入るという実態もある。何かそこら辺のこともできるだけ詳しく情報としてお伝えいただければと思いますが、いかがでしょうか。","respondent":"竹田保育課長","answer":"誤解のないようにできだけ丁寧にご説明はしたいと考えておりますが、画面の分量の制約と、それとあまりたくさんになると逆に読んでいただけないというような側面もありますので、適切な分量で説明させていただいて、それでご理解いただけないところについては。","voiceIndex":35,"id":"exchange-013"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひ、この部分を解消していただいて、できるだけ定員で動かしていくとか、いろいろなやり方があると思いますので、事業の前倒しをするというのは今ある施設を、不要なと言ったら申しわけないのですけれども、前倒しで施設を占有してしまうというのは非常にもったいないことですので、ぜひ０歳が一番入りやすいという状況というのを解消するような努力をしていただきたいと思うのですが。","respondent":"竹田保育課長","answer":"それを補う制度として、入園予約制度というのを設けておりまして、全体から言うと少ない数になるのですが、そちらの制度を使って育休を１年なら１年間フルにとっていただくようにご案内しています。","voiceIndex":37,"id":"exchange-014"},{"speaker":"あべ委員","kind":"質問・要望","question":"制度があることは重々承知しております。最後の質問です。１枚目に戻ります。一旦その職を離れても、またすぐ再就職ができる状況なのかどうかということと、その立場を離れるともうそのポスト、その企業には絶対戻れないということを考えると、どちらが逸失利益が大きいのかという視点もぜひ入れていただきたいのです。その辺については、保育課としてはどのように受けとめていらっしゃいますでしょうか。","respondent":"竹田保育課長","answer":"ただ、毎年社会状況も変わっていきますので毎年見直しを行っているところです。１人でも多くの方にご理解いただけるような制度となるように今後も十分検討して見直しを行っていきたいと考えております。","voiceIndex":39,"id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"であれば、先ほど公表するに当たって、ホームページ、それから窓口ということをおっしゃっていただきました。保育園の保護者会等でもぜひとも言っていただきたいですし、あらゆるところで、品川区はこのように公表していますのでと、入りやすいところもこれを参考にできますということで、ぜひご案内を進めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今まではほんとうにお問い合わせで知りたいという人だけにお知らせをしていて、それが誰でも見られるというところにおいては、ほんとうに慎重にわかりやすく公表していただきたいと思うのが１点ですけれども、あと、基本的なところなのですが、この指数について数字のところが基準になるものがあるのかどうか、基本指数とあと調整のところで、例えば厚生労働省とか東京都とか、何か基本的なものがあるのか。","respondent":"竹田保育課長","answer":"こちらの指数については、各自治体の判断で決めているものですので、自治体によって違うという現状です。長年いろいろなご意見を伺いながらいろいろな変遷を経てつくってきたものですので、また今後も見直し等も含めて検討していきたいと考えております。","voiceIndex":46,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっと幾つか事例でお聞きしたいのですが、ひとり親家庭で結構入れなかったという人もいるのですが、基本的なところで、ひとり親家庭のところ、例えば就労のところ、月２０日以上で、日中８時間以上の２０点の方だと、ひとり親家庭だとあと何が加点されるのか、ちょっとその辺の具体的なことを知りたい。体の痛みに耐えながら就労しているのだけれども、フルでは働けないので短時間就労になってしまう。","respondent":"竹田保育課長","answer":"お体のぐあいが悪くて長時間勤務できないという方につきましては、短時間保育室という制度を設けておりますので、そちらのほうで対応させていただきたいと考えております。","voiceIndex":48,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっとそこの確認をさせていただきたいのと、あと、就学のところは、実際的に預かってもらっていた子どもがだめになったというケースがあるのですかね。何か学校に行き続けられないというのが１件あったのですけれども、ちょっとそこを聞かせていただきたいのと、あと難病で短時間しか就労できないという方は短時間保育室の対応で、これは入園できるのでしょうか。","respondent":"竹田保育課長","answer":"勤務時間の短い方については、当然短時間保育室等をご説明しております。一方で、説明を尽くすがゆえに窓口でのお一人当たりの対応時間が長くなっているというのが現状です。","voiceIndex":50,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"一つ、障害児童のところなのですけれども、調整指数の７と８のところなのですが、障害児の受入れ状況というのは、特別支援保育審査会で審査にかかるわけですけれども、実態的にはどうなっているのか、特に特別支援教育を進めていく意味では、集団で生活できる子はほんとうに積極的に保育園で受け入れていくべきと思っていますが、実態はどうなっているか教えてください。","respondent":"竹田保育課長","answer":"その際の考え方としては、まず集団保育が可能かどうかということと、それから集団保育することによって、そのお子さんにプラスになるのかどうかといった観点を十分審査しまして、可否のほうを判断するところです。","voiceIndex":52,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"障害児の受入れ状況というのは、人数的にはどんな様子なのか、ちょっと教えていただきたいのが質問の１点です。ぜひいろいろな事情、保護者の方がわかるように丁寧に説明をしていただきたいということ、あと改善策のところなのですけれども、すごくご苦労はよくわかります。それを区民に伝えていく、やはりそういう姿勢を持っていただきたいと思います。いかがでしょうか。","respondent":"竹田保育課長、大澤待機児童対策担当課長","answer":"特別審査会を実施する前に、入園申請の段階で一定の支援が必要だということを保護者の方からお申し出があった場合には、医師同席のもと面接を行いまして、十分調査して審査会に臨んでいるところです。認可保育園の開設ですが、前回の委員会において４園ご紹介させていただきましたが、そのほかにも今複数の園につきまして協議調整を進めているところですので、今後とも全力で開設に向け努力してまいりたいと思います。","voiceIndex":54,"id":"exchange-021"},{"speaker":"沢田副委員長","kind":"確認","question":"指数が同一の場合、区内在住年数の長いものと４番にあるようなのですけれども、これはそもそも誰の区内在住年数なのか。本人、お子さんが区内在住なのか、保護者なのか、その辺の確認をさせてください。","respondent":"竹田保育課長","answer":"保護者の方の在住年数としています。","voiceIndex":58,"id":"exchange-022"},{"speaker":"沢田副委員長","kind":"質問","question":"やはり、いろいろなことを研究されて、こういう形でつくられていると思うのですけれども、区内に在住されて、ずっとお住まいだった方たちとかのお話を聞いていると、どうしても同一指数のときはこういうふうに優先順位で決めていくということになっていますが、もう少しどうにかこれを配慮してもらえないかという話をよく聞くのですけれども、いろいろなお考えで決められていることだと思うのですが。","respondent":"竹田保育課長","answer":"委員のご指摘を踏まえて、今後より検討して見直しを進めていきたいと考えております。","voiceIndex":60,"id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"確認","question":"それからあと、ほかの委員からもお話があったのですけれども、昨年と比べてのラインがどういうふうに変わったか、あるいは変わっていないか、先ほども０歳から１歳はなかなかというところがこれを見ると余計にわかってくるのですけれども、それに対する区民の方々やいろいろな声がかなり出てくると思うのですけれども、先ほども幾つか決意を述べられたと思うのですけれども。","respondent":"竹田保育課長","answer":"こちらの数字が一人歩きしないように十分説明を尽くしてご理解いただくように努めてまいりたいと考えております。","voiceIndex":62,"id":"exchange-024"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そこはよろしくお願いします。最後に確認なのですが、これは同じ、例えば一本橋の０歳で４０だけれども、Ｄ１４までということは、１５の方が仮にいたとすると入っていないと、同じ４０で入っていないということでよろしいのですか。それで、これを見た方がお問い合わせになったときに、私は４０でＤ１４なのだけれども、入れなかった。","respondent":"竹田保育課長","answer":"こちらはあくまでも１次選考時の数字だけということを十分ご説明して、誤解のないようにしたいと思います。１次選考の段階ではＤ１４までです。","voiceIndex":64,"id":"exchange-025"},{"speaker":"鈴木（博）委員","kind":"確認","question":"先ほど説明があったのかもしれないのですけれども、確認したいのですが、定員割れというのはどういう意味なのですか。","respondent":"竹田保育課長","answer":"こちらはまだ定員に余裕がありますが、お申し込みがなかったですので、仮にお申し込みがあれば、入れる状況ですです。","voiceIndex":68,"id":"exchange-026"},{"speaker":"あべ委員","kind":"確認","question":"この表を見させていただいて、３歳が意外に高い指数になっているということを改めて認識させていただきました。認識は確認したのですけれども、保育課としてはこの３歳の入りにくさというのをいかに考えていらっしゃるのか、あるいは今後どのように考えていかれるのか。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"３歳につきましては４０点前後で各園ともありますので、今逼迫した状況にあるというふうには考えてございません。６と９がおかしいではないかと言われれば、そういうこともありますし、上の子が保育園に入っているのだったら、一緒に連れていったほうが楽だからちょっと加点したのだという実務上のこともありますし。","voiceIndex":70,"id":"exchange-027"},{"speaker":"あべ委員","kind":"質問","question":"３歳にこだわったのは、１歳、２歳とは違って、先ほども申しましたように、地域型保育事業で０歳、１歳、２歳の後の受け皿という意味があるからなので、そこはもしかすると、ちょっと伝わっていなかったかもしれません。それで伺いました。どうぞよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-028"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"先ほどご説明がちょっとありましたけれども、校区教育協働委員会のメンバーということで、関係機関職員というのがあるのですけれども、例えばどういった方になるのか教えていただきたいと思います。学校地域コーディネーターが区の非常勤になるということですけれども、勤務日数というのは、１週間で言うとどのくらいになるのでしょうか。","respondent":"熊谷指導課長","answer":"コーディネーターの具体的な仕事なのですけれども、１番は１枚目に書きましたが、やはり学校と地域を結ぶというところで、校区教育協働委員会と学校支援地域本部の両方に入ることで、学校教育協働委員会が求めているどのような支援が必要か。","voiceIndex":78,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、今のところ、コーディネーターの方の主な仕事というのは、校区教育協働委員会の求めるボランティアを紹介するということでいいのか、ちょっと確認させていただきたいと思います。","respondent":"熊谷指導課長","answer":"例えば、図書館ボランティアは図書館ボランティア、それから学校の木々の伐採であったりとか、校庭の整備をしたりとか、そういったこともそれぞれやってきたのですけれども、組織的にということで。","voiceIndex":80,"id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"コミュニティ・スクールの目的のところで、教員の異動に影響を受けず、継続的な教育活動を展開するとありますけれども、この教員というのは一人ひとりの教師の方ということなのか、それとも校長とか副校長という指導する方が異動してしまうということなのか、そこの確認をさせていただきたいと思います。","respondent":"熊谷指導課長","answer":"同じように教員の異動というのは、それぞれの教員で特性があろうかと思いますので、そういった異動で、人ではなくて、その先生がやってきている教育活動、それを継続して引き継いでいけるようにということで、この目的のところで挙げてあります。","voiceIndex":82,"id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"校区教育協働委員会の役割の中で、学校運営の基本方針を承認するとあるのですけれども、先ほどの説明だと、品川での校長先生が運営方針を作成して、それを承認するという形になるのかと思いますけれども、やはり承認されなければ、この方針が実施されないというところで、現場の教員の方がやりたいことがちょっと違う方向に行ってしまう可能性がないのかなと危惧してしまうのですが。","respondent":"熊谷指導課長","answer":"１点目と２点目と重なるところがあると思うのですけれども、これまでももちろん校長の異動に関して経営方針をもとに次の校長につないでいくということはあったのですけれども、ただ、校長経営方針、これを見ていただきたいのですけれども。","voiceIndex":84,"id":"exchange-032"},{"speaker":"新妻委員","kind":"質問・要望","question":"何点かお聞きいたします。学校地域コーディネーターの権限といいますか、どこまでこの地域のコーディネーターがやっていくのかというところを教えていただきたいのですが、例えば今お話がありましたミシンの指導の補助とか、こういうのをやりたいという声があったときに、お願いをするまで、人の選別とか、そこまでも地域コーディネーターがやっていくのかどうか、そこら辺も教えていただきたいと思います。","respondent":"熊谷指導課長","answer":"校区教育協働委員会にも、町会の代表の方が入っていらっしゃいますので、そういったところで具体的な説明をしながら進めていくことも重要だと考えています。","voiceIndex":86,"id":"exchange-033"},{"speaker":"新妻委員","kind":"質問・要望","question":"今後また平成２９年度、平成３０年度においては全校に拡大されてまいりますので、それぞれ地域とのやりとりをしっかり細かくやっていただいて、それぞれがいい方向で進んでいけるようにやっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-034"},{"speaker":"あべ委員","kind":"質問・要望","question":"何点かお伺いしたいと思います。ほんとうにコーディネーター次第だと思っているのですが、だから、どういう人と一口では言えないと思うのですけれども、まずコーディネーターをどういう方にするかということは、ちょっと時間をかけたほうがいいので、ぜひ責任者をそれぞれ探し出していただきたいと、これは要望になりますけれども、コーディネーターをぜひ大切にしていただければと思います。","respondent":"熊谷指導課長","answer":"大原小学校が日本女子大、それから八潮学園が慶応義塾大学、日野学園が清泉女子大、荏原平塚学園が明治学院の現在大学生であり、卒業生、一番現場に近い方たちが入ってきていて、そういう方が入ると、若い、フレッシュな感覚も取り入れられるかと思いますので。","voiceIndex":89,"id":"exchange-035"},{"speaker":"あべ委員","kind":"質問・要望","question":"コーディネーターの相談窓口というのは非常にいいことだと思いますし、卒業生の大学生の方々、ただ、現場で使うだけではなくて、その人たちそれぞれが同級生や先輩、後輩のネットワークを持っていらっしゃるでしょうから、ぜひ存分に活用していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"少しずつコミュニティ・スクールの中身がわかってきたのですけれども、やはり言葉が固いので、みんなが、あ、そうかとわかるような表記を少し考えてほしいと思ったのと、今日２枚目を見ると、この図から見ると、関係が以前よりもよくわかってきたかなと思います。教職員の方々の意見がどこを通して、どう反映されているのかというところもぜひ充実をさせていただきたいと思います。","respondent":"熊谷指導課長","answer":"それにつきましては、さまざまだったのですけれども、校区外部評価委員会との違い、ここでは評価だけではなくて、もっと主体的に学校への基本方針も承認するなど、かかわっていくのですよというようなお話であったり。","voiceIndex":92,"id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味で、やはりこの役割を引き上げていくという意味では、私はとりあえず非常勤という形ですけれども、もっと主体的な仕事ができるところにしていく必要があるのではないかと考えていますが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"それから２点目なのですが、コーディネーターの主体性、役割を引き上げていくということでは、まだ始まったばかりで、さまざま悩まれている部分もあるかと思いますので、１枚目にも実は書かせていただいたのですけれども、一番下の右端なのですが。","voiceIndex":94,"id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほども卒業生がメンバーに参加していらっしゃるというのを伺いましたけれども、やはり若い方々、在校生ももちろんそうなのですが、若い方々が参加して、また出やすい体制づくり、参加しやすい体制づくりをしていただいて、より学校に近い年齢の人たちがいっぱい加わりながら、いろいろな年齢の人、あと２枚目のところにあるように、一言に地域と書いても、これだけいろいろなたくさんのことがあって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-039"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"コミュニティ・スクール、しっかり地域と学校の連携をこれから進めていっていただきたいと思うのですけれども、スケジュールのところで、今年は１５校でモデル校をやっていくということで、来年は３１校で、再来年は４６校ということなのですけれども、コミュニティ・スクールはモデル実施というのはわかるのですけれども、これから全部の学校で進めていくというふうに考えると。","respondent":"熊谷指導課長","answer":"実際に来年から始めようと、準備は整っていて、来年やりたいと思っていらっしゃる学校もあれば、反対にもう少しうちのコミュニティ・スクールの方向性を考えたいということで、ゆっくり時間をかけて保護者や地域に説明していきたいという学校もあります。","voiceIndex":97,"id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"確認","question":"これも地区委員の方は町会と重なるところもありますけれども、別の形で比較的若い方がいらっしゃったりして、人材のいろいろなネットワークをご存じなので、その地域、地区委員会で説明会に出られたということは大変いいことだと聞いているのですが、１３地区全部でやられているのか一つ確認したいのですが。","respondent":"熊谷指導課長、品川庶務課長","answer":"１３地区の町会長会議でまずお話をしています。その前に、区政協力委員会で説明をしています。その後で、町会長会議で具体的に説明を１３地区させていただいています。地区委員会につきましては、一部説明等を行っているところもあるのですが、全地区につきましては、また検討して進めていきたいと考えています。","voiceIndex":99,"id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ただ、コミュニティ・スクールがあるのですよ、今度何かお手伝いしてくださいと言われても、「それって、何」から始まってしまうので、ぜひネットワークをたくさんお持ちの地区委員会の方の定例会みたいなのに教育委員会の方が来て、そこの地区委員では説明していただけたみたいなのですけれども、大変ありがたいので、それを１３地区に広げていかれると。","respondent":"熊谷指導課長","answer":"２点目の卒業生を一番よく知っているのは在校中の子どもたちの様子をわかっている教員であるということですので、そういったこともやはり大事にして、さらに学校支援地域本部のグループに卒業生を、また応援してもらえるように教員の情報共有を大事にしていきたいと思っています。","voiceIndex":102,"id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"意見","question":"そのような形で学校のほうからぜひ働きかけて、コーディネーターだけの人脈だと限られてしまうので、できるだけ多くのそういった広がりが持てるといいかなというふうに思っています。ぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２点、すみません。学校地域コーディネーターはどんな方がされているのか、先ほどＰＴＡ関係をとおっしゃっておられたのですが、１５校の中身は実際にどうなのか教えていただきたいのが一つです。","respondent":"熊谷指導課長","answer":"それから２点目なのですけれども、区費の教職員の配置に関するということなのですけれども、意見なのですが、これは例えば誰々さんが欲しいとか、誰々先生がどうこうということではなくて、校区教育協働委員会の中で、うちは例えば理数教育の充実をしていきたい。","voiceIndex":105,"id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"１５校はＰＴＡの会長がほとんどということで、きちんと聞いていなくてごめんなさい。わかりました。区費教職員の配置ということは、ご説明があったのですけれども、こういった意見を聞いていくということは、区費の固有の教員をこういった意見を聞いて充実させていく、新たに採用していくというところまで考えていることなのかどうか教えてください。","respondent":"熊谷指導課長","answer":"区の固有教員だけではなくて、区の講師ですとか、指導助手ですとか、そういったことがありますので、やはり充実させていくというのは、なぜそういった先生が必要なのかということをしっかりここで練って、そして承認を得て出していくということになりますので。","voiceIndex":107,"id":"exchange-045"},{"speaker":"のだて委員","kind":"確認","question":"確認なのですが、コーディネーターの任期というのはあるのでしょうか。","respondent":"熊谷指導課長","answer":"コーディネーターの任用期間なのですけれども、非常勤職員ですので１年間を単位として任用します。ただ、教育委員会教育長が特に必要と認める場合は、また再度更新することは可能です。","voiceIndex":109,"id":"exchange-046"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、基本的には１年交代と考えればよろしいのでしょうか。","respondent":"熊谷指導課長","answer":"基本原則として１年を任期としていますが、先ほどお話ししたように更新していくことは可能です。","voiceIndex":111,"id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ですから、そういうところをぜひ配慮していただきたいということと、あとは今まで学校でやっていたのは、言葉はすごく悪いですけれども、下請けというか、そういう形でやっているのではないのだということを学校全体がこういう中で感じていただけるような体制づくりという点についてお願いしたいのですが、そこのところを最後にお願いします。","respondent":"熊谷指導課長","answer":"ほんとうに仲間として一緒にやっていくということが重要でありますので、いわゆるアウェー感というのがないように配慮していく必要があると思いますし、また下請けというのではなくて、一緒に考えていくということで、教職員にも、校長。","voiceIndex":113,"id":"exchange-048"},{"speaker":"あくつ委員長","kind":"質問・要望","question":"それとあと、先ほどから質疑を聞いていてだんだんわかってきたのですけれども、若い方を校区教育協働委員会の中に入れるとか、学校の中で、例えば独自に理科教育を進めたいとか、地域独自の考え方を学校教育に反映していくのは非常に画期的だと思いますし、教育長も教育フォーラムのときに一つこの教育ルネッサンスでコミュニティ・スクールを非常に大きく取り上げられていたのですが。","respondent":"熊谷指導課長、中島教育長","answer":"１点目のほうをお答えしたいと思うのですけれども、国のコミュニティ・スクールなのですが、こちらは学校運営協議会を設置します。品川の場合には、これまで品川区がやってきた学校としての外部評価を母体とし、そして昔ながらの地域とのかかわりの中で、たくさんの地域の方々が学校に寄せていただいたボランティア、それを組織化するというような。","voiceIndex":115,"id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4890#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":38626,"voices":122}},{"id":"h28-20160726-5","meetingId":"h28-cm07","date":"2016年7月26日","dateIso":"2016-07-26","committee":"総務委員会","time":"午後 １時００分～午後 ２時２０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"わ！しながわ魅力発信事業","agenda":"わ！しながわ魅力発信事業","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そことのかかわりをどういうふうにしていったらいいのかをちょっと一つ知りたいのと、あちらとの関係で、こちらのほうの事業もこれからずっと継続していくことが大前提だと思うのですけれども、１年間の支援なのか、全体的なこの事業、魅力発信事業というそこのところの中身を教えていただきたいと思います。","respondent":"中島企画部副参事","answer":"こちらの支援につきましては、基本的には１年間の、３月末までの支援ということで、品川区の魅力の発信をしている事業を支援してまいります。その後につきましては、各事業者が個別に継続していただくことを期待しているものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"区民のいろいろな活動を、品川区に住んでいて品川区民を対象にした活動で、品川区の区民のためにとか発展のためにと、どこでも別に品川区の魅力を発信するしないに限らず、そういうコンセプトを持っていると思うのですけれども、あえてそこを取り上げていくということの意味、どういう願いがあってこういうふうな記述を意識的にお出しになって、この事業の特徴をつけたかというそのあたり。","respondent":"中島企画部副参事","answer":"区民の方々の取り組みが魅力につながらないということではございませんで、今回こちらのほうで募集しているものにつきましては、品川区の伝統が息づく暮らしと都心の魅力が共存するという魅力を、区外にも含めて力強く発信をしていく。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"品川の魅力はいろいろな多方面にあって当然だし、私自身も認めているし、住みやすいまち、八潮も含めてそういうふうに思っているのですけれども、あえて品川区だけの魅力ということでもないわけですから、いろいろな立場の人たちが、あ、そうだよね、こういう事業は大賛成だよねとなりきれないのではないかなと、ちょっとそういう心配を感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"最初に助成の費用の額なのですけれども、この表だと４番が助成対象経費が１４０万円で助成額が７８万円というのと、７番の２７万５,０００円に対して１５万２,０００円を助成するというのは、この助成対象経費の２分の１以内というのと外れるような気がするのですけれども、その辺の考え方を教えていただきたいのと、ちょっと聞き漏らしたのかもしれませんけれども。","respondent":"中島企画部副参事","answer":"ですのでそういう広告とかメディアのプレスリリースとかを活用することを予定している事業につきましては、２分の１以上の助成を予定しています。次のナンバー７のLunchTripの事業につきましては、こちらは会場型のイベントを予定しております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。広告・メディアに関する経費のところを少し読み間違えておりましたので、それはわかりました。もう一つあったのですが、１番の「知って、学んで、品川区」はプログラム提供ということだったと思うのですけれども、どういう方たちがプログラムを活用すると想定してのものなのか、もう少し内容を教えていただければと思います。","respondent":"中島企画部副参事","answer":"品川区のホームページでもこのプログラムに入れるようにいたしますし、地域のポータルサイト等にもバナーで入れるようになるということですので、それを見た外部の区外の方からもアクセスしていただきまして、品川区の魅力をより深く知っていただきたいと考えています。","voiceIndex":12,"id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"これに限らず、やはり助成金を出す以上、効果測定というのをぜひ、去年もそれをやったからその反省を踏まえて広報経費、メディア活用にかかる経費を増やしたということで、それは一つのやり方かなと思いますけれども、本当にちゃんと魅力発信につながるようなものになっているかは、ぜひ今後も検討していただいて、もし継続することであれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"つる副委員長","kind":"質問","question":"これをちょっと教えていただいて、魅力を発信するということの取り組みの支援に対する発信力、品川区自身が広報しながわとかにいろいろ載せていたと思うのですけれども、その部分の取り組みについての、今現段階での評価というか、それはどうなのか教えてください。","respondent":"中島企画部副参事","answer":"恐らく、理由としましては、イベントよりも魅力発信を期待するというところで少し皆さんのほうでちょっと検討するところがあったのかなと思いますが、今回提出した事業につきましては、昨年度以上にいいものが出ていると考えております。","voiceIndex":15,"id":"exchange-007"},{"speaker":"つる副委員長","kind":"質問・要望","question":"先ほど、ほかの委員からも確認がありましたけれども、その先、それぞれ７事業やっていただいて、本当にどういうふうな品川区全体としての魅力発信につながったのかという検証、これは当然必要になると思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-008"},{"speaker":"須貝委員","kind":"意見","question":"そうすると、それぞれ力としては、発信する力というのは、予算は別ですけれども、７分の１の力がそれぞれ小刻みに出ていくのですが、逆に一本化して太い発信、１つの柱を集中して今年はこれを、来年はこれをというほうがもっと発信力というのは私はあると思うのですが、その辺についてちょっとお考えを聞かせてください。","respondent":"中島企画部副参事","answer":"今回、７事業がございまして、確かにそれぞれの事業がそれぞれの発信をしてまいります。そこを区の方でホームページでありますとか広報しながわでまず一つの形でお示しいたします。今回、「わ！","voiceIndex":18,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとすみません、答弁のほうであれなのですが。こうやって幾つも、７つ今回出すと、申し訳ありませんが、花火で言えば小さいのを打ち上げるならでかいのを一発ぼーんと上げて品川区はこうだというほうが、より発信事業の効果があるのではないかと思うのですが、その辺についてどのようにお考えですかということなのですけれども。","respondent":"中島企画部副参事","answer":"品川区もその事業認定の機会を捉まえまして、参加者の方に対してしっかりとＰＲをしてまいりたいと思います。","voiceIndex":20,"id":"exchange-010"},{"speaker":"大倉委員","kind":"質問・要望","question":"先ほどからも、検証とか効果というのが非常に大事でしっかりとその後事業の後追いをしていってほしいというお話はまさにそのとおりだと思いますのでやっていっていただきたいのですが、その中で審査基準の中に事業の継続性というところがあるのですが、これはどこが、シティプロモーションとの関係性とか情報発信力とか実行性、地域性というどこが……、全体的に大事だと思うのですが。","respondent":"中島企画部副参事","answer":"旧東海道のウエブサイトも引き続き更新をして情報発信に努めています。そういう意味で、今年度も引き続き継続をされている事業もありますので、少しでもやはり継続をしていただくということに重点をおいて、事業を後押ししてまいりたいと考えています。","voiceIndex":22,"id":"exchange-011"},{"speaker":"大倉委員","kind":"質問","question":"例えば、これを毎年継続していく中で、今回はこれで助成が一回終わるとなると、そのほかの部分は何かやはりやっている主体のところが努力して、費用を捻出してやっていっているということになるのですか。例えば、さっき言った新しい事業になったときにもう一回受けられるとか、発展した場合にもう一回受けられるとかという仕組みだったりはするのでしょうか。","respondent":"中島企画部副参事","answer":"このような形で、基本は１年の助成という形で考えていますが、場合によってはそういう継続ということもあり得ると思いますので、このような形で展開していきたいと思います。","voiceIndex":24,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"今のご質疑を聞いていて、今までの事業で継続はどのくらいしているのかとか、継続している事業があるのかみたいなご質問の中で、例えば２番のしろへびのところで去年と今年は団体の性格というか、全然違う団体ではないかなと思って聞いていたのですけれども、そうすると継続というふうにはならないと思ったのですが、その辺がどうなのか正確に知りたいので教えていただきたいと。継続できるように支援をする。","respondent":"中島企画部副参事","answer":"今年度採択した７事業のうち、ナンバー２の事業とナンバー７の事業は申請者が同じで昨年からの継続です。そのほかの５つにつきましては、新規の案件という形になっております。","voiceIndex":26,"id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"わかりました。の５つはこれから５年でも１０年でも継続していけるようによく頑張っていただきたいと思っているのですけれども。それは団体の自主性のところですから別にどうこう言うつもりは全然ないのですけれども、先ほどの説明では、品川では蛇窪のあたりの蛇に関する歴史だとか民話も含めてそういうのがあれば掘り起こしていただければと思ったりしているのですが。","respondent":"中島企画部副参事","answer":"三大聖地というのは、申請者の方がおっしゃっていることなのですけれども、その方がいわく、山口県の岩国市に天然記念物のしろへびがいまして、それを岩国市の協力を得て品川区まで運んで展示をするとかということを考えていらっしゃいます。","voiceIndex":28,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"そのかわり基準を厳しくするというか、区も入ってこうでなくてはというものがあるではないですか。そこまで踏み込んでチェックをされたり、ポスターだって、ポスターが張ってあって、「え、このポスターでは」とかあるではないですか。そういうところの審査というのか、ここへ継続していくほうも含めて、そこら辺はどうお考えになってこの事業を選定しているのかなというところをお聞きしたい。","respondent":"中島企画部副参事","answer":"金額が全額補助ということですが、今回あくまで委託事業ということではなく助成金の活動の支援ですので、現段階ではこのような形の支援を考えているところです。","voiceIndex":31,"id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"「わ！しながわ」に皆さんがいろいろなものをつけてください。私はそういう意味では、幾ら民間だといっても、発想は民間からもらったって３分の２ではなくて、そういうものを使って、３年、５年と使ってそれをいろいろなことをイベントで使ってくれるなら、そういうものについてはお金は出しますよというぐらいのほうが事業も広がっていくと思うのだけれどもな。ぜひそうしていただきたい。お考えを。","respondent":"中島企画部副参事","answer":"こちらの事業につきましては、昨年度のシティプロモーション認定事業も含めて２年目ですので、今回効果検証も含めてさまざまな検討をして助成のありようにつきましても今後の検討とさせていただければと思います。","voiceIndex":33,"id":"exchange-016"}]},{"id":"topic-02","title":"しながわ区民公園中央広場改修工事請負契約","agenda":"しながわ区民公園中央広場改修工事請負契約","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"すみません、ちょっと１点だけ教えてください。これは予定価格というのが入っていないのだけれども、予定価格というのはなかったと思えばいいのでしょうか。","respondent":"立川経理課長","answer":"こちらは指名競争入札で行いました。それで予定価格というのを公表していないです。通常は制限付き一般競争入札で行いますので予定額は公表しておるところです。","voiceIndex":39,"id":"exchange-017"}]},{"id":"topic-03","title":"伊藤小学校便所及び校庭改修その他工事請負契約","agenda":"伊藤小学校便所及び校庭改修その他工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"すみません、基本的なことで。工事内容なのですけれども、トイレの改修のところで、東側１、３、４階というのは、１、３、４階にあるトイレの改修で、床と壁と天井を改修したというかやり替えたと読めばよろしいのでしょうか。教えてください。","respondent":"立川経理課長","answer":"トイレは１階から４階まであるのですけれども、２階の部分につきましてはもう既に改修が終わっているということで、今回の工事におきましては、１階と３階と４階のトイレを改修するというものです。","voiceIndex":46,"id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"トイレそのものががらっと変わるというよりも、その中の床とか壁とか天井とかをということでよろしいのですか。","respondent":"立川経理課長","answer":"いわゆる便器だけとかいうわけではなくて、委員ご指摘のとおり、床、天井等全てきれいにしていくというものです。","voiceIndex":48,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"今、たまたまトイレの話が出たのですが、今お子さんが本当に洋式になれ過ぎてしまって和式を使えないということなので、だんだん変わっていくのだと思いますが、改善できるところはしていってほしいと思います。１点だけお聞きしたいのですが、人工芝にしますよね。そして、今後品川区全体の校庭に関してはどのような方向性があるのか、持っていくのか、その辺についてもちょっと聞かせてください。","respondent":"立川経理課長","answer":"いわゆる学校施設全体の人工芝生化については、基本的には方向性というのは所管のほうから聞いておりませんけれども、適宜検討しつつ進めていくようなところまでは聞いておるところです。","voiceIndex":52,"id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"先ほどの質問で改めてなのですけれども、和式中心から洋式便器の改修は、今回は入ってないけれども、入っているのでしたか。便所の改修で洋式にするか、床・壁・天井でしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"あ、本当。ごめんなさい。だけれども、ここ、便所改修で東側１、３、４階、床・壁・天井。ここに便器の改修も入っているということで理解すればいいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-022"},{"speaker":"南委員","kind":"意見","question":"わかりました。それが１つです。それから、２つ目は、８ページの資料、これは配置図の平面図のところの１階で、便所改修で２階は天井のみと括弧書きで書いてあるのですけれども、２階は天井部分を改修すると読むのかなと思っているのですけれども、最初のところには２階は外されているからどちらが正しいのかなと、ちょっとその辺、お願いします。","respondent":"立川経理課長、小林施設整備課長","answer":"２番目の質問からお答えいたします。委員ご指摘のとおり、８ページの２階は天井のみということで、既に便器等の改修は終わっているですので、８ページの記載のほうがより正確な表記です。今のにちょっと補足で、２階の天井のみという工事は、３階の陶器、便器関係を直すときは配管がスラブの下に入っておりますので、必然的に２階の天井を壊して作業をしないといけないということで。","voiceIndex":56,"id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"先ほどの経理課長のご答弁では、庶務課に伝えておくというお話なのですけれども、やはり総務委員会であっても契約に関することで非常に子どもたちの環境に関する、かなり要求度の強い部分だと思いますので、やはりそういうこともあわせて便器の洋式・和式の状況がどうなっているかを教えていただきたいと。そういうことも含めて準備をしていただきたいということをお願いしておきたいと思います。","respondent":"立川経理課長","answer":"資料の表現につきましては、今後とも工夫をしてまいりたいと思います。いわゆる全体計画につきましては、やはり所管からの回答がふさわしいと思われますので、この委員会におきましては契約に関する内容につきましてを中心にご報告させていただきたいと思います。","voiceIndex":59,"id":"exchange-024"}]},{"id":"topic-04","title":"旗台小学校外壁その他改修工事請負契約","agenda":"旗台小学校外壁その他改修工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"すみません、同じ質問になってしまうのですけれども。１１ページの工事内容のトイレの改修がまた床・壁・天井となっているのですけれども、こちらには便器の改修というのは入っているのでしょうか。どうなのか教えてください。","respondent":"立川経理課長、小林施設整備課長","answer":"床・壁・天井も含めまして、便器につきましても改修するものです。当然、床と壁と天井、床のものを全部はがせば、当然その上に乗っかっている衛生器具の便器関係も全て取るということなのですけれども、今回は建築工事の概要を書いているので、そこら辺をちょっと省いているというか、書いてないです。","voiceIndex":68,"id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"建築案件だから省いてしまったという説明なのですけれども、でも取り替えることは取り替えて、かなり強い要望だということがありますので、やはりきちんと正確にわかるように記載していただきたいと思っています。ですから、改善をという話であったのでそういうふうに受け止めていきたいと思っていますけれども、その辺はできるだけわかりやすいようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-026"}]},{"id":"topic-05","title":"八潮団地内区道歩道拡幅整備工事（第３工区）請負契約","agenda":"八潮団地内区道歩道拡幅整備工事（第３工区）請負契約","exchanges":[{"speaker":"南委員","kind":"確認","question":"八潮に住んでいる者として、歩道が拡幅されるのは本当にうれしいと思っていますし、非常に使い勝手というか、安心して通行できます。改めてこのことは申し上げておきたいと思います。それで、私、聞きそびれてしまったのかもしれないですけれども、改めて確認したいのですが、前の予定では４年計画だったのですが、５年になった理由というのが何かを確認したいと思います。","respondent":"立川経理課長","answer":"こちらにつきましては、本年２月の建設委員会のほうでも報告をいたした内容ですが、先行して東京都の水道局によって本管の耐震化工事を実施しているわけなのですが、当初の見込みより耐震化工事に時間を要したということで、平成２９年度の完成が見込めなくなりましたので。","voiceIndex":76,"id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１社入札なら本当は不調ということに基準はなっているのだけれども、こういう時世だからまあしょうがないという、不調にならなくてよかったねというところもあったりしてやっているというところがあるのだけれども、区としてもこういう不調にならなくてということがいいと、よかったなと思っているのか、今こういう１社入札は本当はいいことではないともともと言われているわけだから。","respondent":"立川経理課長、小林施設整備課長","answer":"もう一点、いわゆる予定価格と実際の入札がかなり１００％近い数字、最近の工事の傾向です。質の問題についてというご質問だったので私のほうからお答えしたいと思いますけれども、図面、それと特記仕様書、あと仕様書というのがあるのですけれども。","voiceIndex":78,"id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません、私の言葉の使い方が悪かったのかもしれないのですが、参加というか申し込みが３社。そういう形の中で、今おっしゃったように見積もりがどうなんというのは、あれだと詳細見積もりをとれとかいろいろな形の話で、こういう参加が１社はやめろと。そこら辺はぜひ、もちろん気をつけてやっていらっしゃると思うけれども、ぜひ気をつけていただきたいなとここで言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2052#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":24040,"voices":95}},{"id":"h28-20160727-14","meetingId":"h28-cm07","date":"2016年7月27日","dateIso":"2016-07-27","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ６時００分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２８年請願第８号 住民の理解が得られない中、平成２９年度予算概算要求に新ルート費用を入れないよう品川区として政府に求める請願","agenda":"平成２８年請願第８号 住民の理解が得られない中、平成２９年度予算概算要求に新ルート費用を入れないよう品川区として政府に求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"採択することを呼びかけたいと思います。それが１点です。それとこの請願の中に、この区の広報なども引用されていまして、４２年前の区の判断はどうして変わったのでしょうかというふうに書いておりますけれども、確かにそうだなと思うのです。改めて、どうして４２年前の区の判断が変わったのか、区の見解もあわせてお聞かせいただきたいと思います。","respondent":"中村都市計画課長","answer":"４０年前の状況から今の状況と、どうしてこれが変わったのかですけれども、これも国のほうに、やはりその辺は過去の経緯もあるということで申し入れをいたしましたが、現在この航空機の性能が非常によくなって、騒音や安全等に関する影響において、法に基づき。","voiceIndex":6,"id":"exchange-001"},{"speaker":"安藤委員","kind":"確認","question":"そこを１点確認させてください。それと、今なぜ判断が変わったのかといろいろご説明いただきましたけれども、国の話ですと、技術進歩に伴って仕切り直しをしたいのだと。ですから今の騒音が小さくなったという区の認識は適切ではないと思いますし、これは変えていただく必要があると思うのですけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"引き続き区民の皆様の意見を国に伝えるとともに、区としましても必要な対応をとっていき、丁寧な説明もしていただくことを申し入れをしていきたいと考えております。","voiceIndex":8,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"であるならば、どうして変わったのかというのをもう一度、そこは説明をしていただきたいと思います。品川区民にとっては、やはり何もないと思うのです。区は、前回品川区に絞って経済効果を計測するのは難しいというようなご説明でしたけれども、やはり一般区民、地域住民、品川区民にとっては、この何か効果があるのですかという。その効果とは改めてご説明いただきたいと思います。","respondent":"中村都市計画課長","answer":"ですので区といたしましては、やはりこの検討の過程におきましては、区民に対して影響が、デメリットが極力少なくなるような、そしてメリットが大きくなるような、そういった方策を国に考えていただきたいということで、申し入れを行っているところです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"もう一度そこは説明していただきたいです。区が主催して国に出席をしてもらう、それで説明をしてもらうという教室型説明会の開催を改めて提案したいのですが、区も繰り返し教室型の説明会というものを要望しているという説明なのですけれども、いつもそこまでは聞くのですが、結局それは国、これから羽田にも行く、国にも聞くわけですが、どのような返事だったのですか。そこをちょっとお伺いします。","respondent":"中村都市計画課長","answer":"この教室型の要望につきましては、これはもう会うたびごとに、お願いをしたいという形で申し入れをしておりますけれども、国といたしましてもさまざまな周知の方法がある中で、やはり直接区民の皆様と１対１で対応が可能な、このオープンハウス型を今まで採用してきたです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"メリットのところですが、前回の国の出したものが唯一のものということですけれども、そこには品川区がどのような効果なのかというのは書いていないわけですから、品川区にとってのメリットというのは、いまだ区も把握できていないということなのか、それでいいのでしょうかというのをちょっと１点お伺いします。この国の対応をどう考えているのでしょうか。","respondent":"中村都市計画課長、三ツ橋環境課長","answer":"このメリットですけれども、今この経済効果というところがあると思いますが、あとは直接、やはり羽田空港に外国からの来訪者が多くなるというところにつきましては、区といたしましてもさまざまな施策でその観光客を取り込むとか。しかしながら、オープンハウス型の説明会だけとは国も考えていないと思いますので、今後のフォローアップの中で、今環境に配慮した方策が夏に出されるとなっておりますけれども。","voiceIndex":14,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとその説明会についても、フォローアップでは遅いわけですよ、やはり。遅いといっては、やはり決定、具体的に国が出すという前に、どのような影響があるのかということを区民の人に知ってもらうということは最低限のことですので、ちょっと説明会ですね。これは強く強く、それをやれということで国と闘っていただきたいのですけれども、そこについてはちょっともう一度ご答弁をいただきたいと思います。","respondent":"三ツ橋環境課長","answer":"しかしながら、国が国の責任において説明会をするに当たっては、今のところはオープンハウス型というものが出されております。","voiceIndex":17,"id":"exchange-006"},{"speaker":"あべ委員","kind":"質問・要望","question":"すみません。例えば教室型の説明会もそうですし、環境測定もそうですし、申し入れがことごとく、区長が強く言っても申し入れが実現していない、スルーされているままこれだけの年数がたってしまったということは、これは考えていただきたいと言われたのですから、考えてみた結果受けとめられませんというお返事でいいのではないですか。申し入れが何も通っていないのですもの。いかがでしょう。","respondent":"中村都市計画課長","answer":"そのような中で、教室型でなくてもこのオープンハウス型をもって説明会を行ったということも、またこれ事実でございまして、これは区が考える教室型に比べて、区の考えとして不十分かもしれませんけれども、ただ一定の理解は。","voiceIndex":20,"id":"exchange-007"},{"speaker":"あべ委員","kind":"質問・要望","question":"区長が強く求めて申し入れている内容、これは議会からも出ていますよね。教室型の。それから環境測定についても、一般質問でも出ていますし、その他落下物の危険性に対する説明ということも求めていますし、さまざまな問題、テーマで国に対して求めているわけです。なぜでしょうかね。であれば、もうそこで交渉事というのは終わりではないですか。もうこの夏ですから。いかがですか。","respondent":"中村都市計画課長","answer":"この説明会の方法ですね。","voiceIndex":22,"id":"exchange-008"},{"speaker":"あべ委員","kind":"提案","question":"議論を矮小化するのはぜひやめていただきたいのですけれども、問題は教室型をする、しないという、それだけのことではなくて、要は区が提案している申し入れに対して、国交省がほとんど応えていないことに対してどう区として出て、どう捉えるのかと。それをどう評価するのかという問題なので、教室型をやったら、ではどうこうということでは、議論の中心はなかったと思うのです。とりあえずそれについて。","respondent":"中村都市計画課長","answer":"全くそのとおりだと思います。ただ、国といたしましてこの夏に出す方策、これを出すと言っておりますので、この方策を出したとしても、それをもって案がとれるということではないですので、まずはその方策を注視してまいりたいと考えております。","voiceIndex":24,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"実際にはこれ、概算要求は国の中での査定に入っていくわけですけれども、概算要求がなされれば。むしろこれは政府の方針として、住民をさておき、このルート変更して増便という考え方自体を本丸に改めていただかなければ、国交省として右、左と決めることができないマターなのではないかなと私は感じているのですけれども、区としてはどうお考えでしょうか。","respondent":"中村都市計画課長","answer":"ただ、これに対して区といたしましても、やはりまずは地域の皆様方の理解が十分でないというようなことも認識をしておりますので、そういったものを丁寧な説明も要望していくと同時に、こういった施設整備につきましても、やはりまずは地域の皆様の意見をいろいろ踏まえて。","voiceIndex":26,"id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"５０年前と比べては、それは騒音は減ったでしょう。そういう意味では、議会としても勉強しなければいけない部分はたくさんあると思うのですけれども、区としても直接国交省と交渉なり、話し合いをする立場のメンバーとして大変だとは思いますけれども、ぜひそれは同じテーブルで議論ができる、プロ相手ですけれども、議論ができるぐらいのものになっていただきたいと、これ最後は要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"},{"speaker":"筒井委員","kind":"質問・要望","question":"今回、この概算要求をしないという要望をすべきだと考えますけれども、品川区としてはどうお考えなのか、お答えをお願いします。","respondent":"中村都市計画課長","answer":"こういったところにつきましては、やはり慎重に進めていただきたい、またやるに当たっては十分慎重に判断をしていただきたいということで、国に対して申し入れを行ってまいります。","voiceIndex":30,"id":"exchange-012"},{"speaker":"筒井委員","kind":"質問・要望","question":"平時からでも必要なものも含まれるから、それはいいんだというように、国の側もそうやってある意味、言ってしまえばごまかして説明や反論をしてくることも予想されますので、新ルートのための整備が含まれる以上、全体として概算要求は否定すべきだと。全体としてこれは認められないということをぜひとも品川区としても主張していただきたいと考えておりますけれども、その点どうお考えでしょうか。","respondent":"中村都市計画課長","answer":"今後ハードの整備だとか、あるいはまだまだこの夏に出されるとされている方策以降も、国に対してはさまざま対応していただきたいことがありますので、引き続き委員のご指摘も踏まえ、真摯に取り組んでまいりたいと考えております。","voiceIndex":32,"id":"exchange-013"},{"speaker":"筒井委員","kind":"質問・要望","question":"やはり品川区としては、今までの環境方策、教室型の説明会が開かれていない等々も含め、要望を国が取り入れていただけなかったということを踏まえて、この段階でもうしっかりと区の姿勢を強く国に対して示すべきだと思いますので、その点ぜひともお願いを申し上げます。これは要望で終わります。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-014"},{"speaker":"沢田委員","kind":"質問・要望","question":"だから、それに対してやはり議会としても、区としても、今までしっかり要望してきたことがあるので、この品川区全体というよりも、どちらかというとその航路の下にいる方たちに対するある程度の、品川区もそれなりに広いですから、品川区全体に対してというよりも、その航路の近く、近辺の人たちのメリットをしっかりと示していけるように、それを国に対してしっかりと要望をしていただきたいと思います。","respondent":"中村都市計画課長","answer":"落下物につきましても、これはいろいろと現在まで調査等の状況が進んでおり、原因についてはやはり車輪の出し入れではなくて、給水口の結露から来るというような調査なども大分されているというところで、いろいろな面で改善はされているというようなことです。","voiceIndex":36,"id":"exchange-015"},{"speaker":"のだて委員","kind":"質問","question":"２４日付の新聞で、国と地元自治体が近く合意することがわかったと。新ルートの運用時間を限定し、空港周辺で騒音対策を実施することで地元の理解を得て、大幅増便を実現に向けて動き出したと報道されているのですけれども、品川区は騒音対策の実施を条件に新ルートに合意するという考えなのか伺いたいと思います。","respondent":"中村都市計画課長","answer":"それをわかった上で、国のほうへは確認をしましたところ、この新聞記事につきましては、取材のないまま記事が書かれたです。今現在はそれぞれ自治体と協議中だというふうにコメントをしておりました。","voiceIndex":39,"id":"exchange-016"},{"speaker":"のだて委員","kind":"確認","question":"つまりこの計画を進めてほしくないということですので、これまで説明会をやられてきましたけれども、区としても不十分だと言っておりましたし、先ほども住民の理解が得られていないという認識だということで、やはり住民の理解を得られていない中で今進められようとしているというところで、品川区としてやはり反対していくべきだと思うのですが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"この方策が出て以降も、地域の皆様に対する周知、あるいは理解を深めていただくための丁寧な説明、これは引き続きお願いをしていくべきものと考えております。","voiceIndex":41,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"しかし、その中でも住民の理解を得られていないというところで、やはり計画段階の中で、やはり一番影響を受ける品川区がこの計画、ルート変更をしてほしいと。このままでは進めさせるわけには行かないということで、しっかりと態度を明らかにしていく必要があると思いますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"現状の中で、この飛行ルートはあくまで案であるということと、また、つい先日経済波及効果についてやっと公表されたばかりだというところで、これから今後の環境に配慮した方策、これが出されるという、現時点においてはまだ賛成、あるいは反対、そういった態度ではなくて。","voiceIndex":43,"id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"計画案の今だからこそ、やはり立場を明らかにして住民の住環境を壊すこの計画、命も脅かすこの計画をとめるために立場を明らかにしていくべきだと思いますが、ぜひそういう、また立場を改めてほしいと言っても多分同じ答弁になってしまうと思いますので、ぜひこの住民の環境を守るために、しっかりした立場に立っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-019"},{"speaker":"あべ委員","kind":"質問・要望","question":"もう一つ、ぜひやっていただきたいことがあるのですけれども、先ほどからメリット、デメリットの話が出ておりますが、これぜひきちんと整理していただきたいなと思っています。なので、羽田空港があるということ自体を否定することは、私はできないと思いますし、あくまでも新ルートに対しての意見ということになると思うので、そこら辺は一応正確に地図をつくっておかなければいけないかなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-020"},{"speaker":"あべ委員","kind":"質問・要望","question":"質問ではなく、こうしたことも、こうした視点というのも持って、全体を理解しつつ反対すべきところはきちんと反対をするということ。もう一ついいですか、ごめんなさい。これも意見なのです。ぜひ考えていただきたいのですけれども、前のオリンピックのころに品川区の目黒川の上に首都高をつくるという案がありました。長い目で歴史を見て、品川区の価値の維持ということを考えていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-021"},{"speaker":"渡部委員","kind":"質問・要望","question":"１時間にわたってさまざまな議論を伺わせていただきましたし、私どもの委員のほうから質問もさせていただきました。今までも、今回この行財政改革特別委員会でさまざまな請願等が上がっております。従来の請願もそのようにしていますが、私どもとしましては、今回上がってきました請願につきましても継続審査ということで進めていただきたいということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-022"},{"speaker":"若林委員","kind":"意見","question":"前期、今期、今期ももう２回目の、いわゆる羽田空港機能強化に反対をする視点からの請願が出されてきまして、今日のものは初めて審査をいたしましたけれども、これまでもずっと言い続けておりますように、今のこの国土交通省、国、それから品川区、また議会の意見書も出ている、また区民の大きな声もまだまだあるという中で、真摯な交渉事が今まさに行われているという認識で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-023"},{"speaker":"安藤委員","kind":"提案","question":"私たちは結論を出すべきだと。それで採択をすべきだと思います。この夏までに重大な国からの提案、決定がされると。方向性が出されるという目の前の段階で、今回内容は来年度の概算要求に新ルートのための予算を要求しないようにと。これはぜひ採択をして、議会の意思を示したいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-024"},{"speaker":"あべ委員","kind":"質問・要望","question":"この今回の請願は新ルートに、要は概算要求という形をとっておりますけれども、新ルートへの変更をやめてほしいという趣旨であると受けとめております。ここには政府に求めるとありますが、当面の相手は国交省、概算要求するのも国交省ですから、国交省に対して、ぜひ話し合いに臨んでいただきたいと思います。それをつけ加えて、今回は他と同様の扱い、継続でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"我が会派としては、この概算要求は８月と、もう間近に迫ってきていますので、結論を出すということにいたします。そしてこの請願内容には賛成するということにします。理由は先ほど述べたように、環境方策を出していない、教室型説明会も開かれていない、品川区のメリットも示していない等々、あと区長や区議会からの要望に対して真摯に対応を示していないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6012#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":21065,"voices":62}},{"id":"h28-20160728-18","meetingId":"h28-cm07","date":"2016年7月28日","dateIso":"2016-07-28","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ３時０５分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"１番の大井中央海浜公園についてということで、1)から3)まであるのですけれども、1)のところの各施設の老朽化への対応というのが、これ、どの程度、どういうふうになっているのか全然わからないので、そういう、今のレベルの状況を調査することも含めて、こういうふうに求めるという、そういう理解でいいのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":3,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"当然、あそこの会場になるホッケー場等々については、新しく観客席も設定されていくわけですから、そういう点で、今の老朽の度合いに備えて補強していくということも含めて観客席を増やす、あるいは必要な施設を増やすということになっていくのだろうと思うのですけれども、ぜひそういう点でも、きちんとした対応をしていけることがいいし、後利用についても非常に安心・安全でいけるかなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これは出ていないので、そのことをぜひ入れていただきたいのが１つと。それから、ほかの会派も指摘されているようですけれども、熱中症対策。８月に開催されますよね。これは、ですから、競技場の中の周辺整備に含めていくべきと思いますので。直接関係はないかもしれないけれども、海外からお客さんが来るということですから、いろいろな想定できないことが起こる可能性もあるわけで。とりあえず以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先日、都庁へ行ったときも要望したのですけれども、クラブハウスも相当老朽化しているのと、あそこの駐車場の問題も、後で十分な対応ができるのかどうか、非常に気になっているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"いながわ委員","kind":"提案","question":"追加というか、２番とか、１番もそうですけれども、大井ふ頭中央海浜公園というのですかね。そこが、私たちもそれを提案すればよかったのですけれども、ちょっと追記になると思うのですが。もっと踏み込むのであれば、そこのさまざま、今、バーベキュー場があるのですかね。その利用の部分に関しても含めて、品川区に寄与できる１つの公園をつくっていただきたいなと。これを提案した方。お願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"意見","question":"３番の、ロンドンオリンピックのバリアフリーに学ぶのところで、今ちょっとご意見あったのですけれども。それでボランティアについた若者たちなども、すごくそれを発展させて、社会全体がバリアフリーの理解を広げたということで評価をされていたので、全般的なところになってくるのかなというふうに思いますので、そういうことなのですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私どもの会派からは、２番を出しています。先ほどからの繰り返しになるところもあるので、皆様からの質疑の繰り返しになるところもあるのですけれども、ドッグランについては老朽化が進んでいる。失礼しました。失礼しました。今後については検討しているということで、先日も都庁で伺いましたけれども、ここについては要望する必要があるのではないかなと考えております。とりあえず以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"提案","question":"この間、東京都に行ったときに提案させていただきましたけれども、品川の冠をつけられないでしょうかということ。大井ふ頭中央海浜公園の前に、品川大井ふ頭中央海浜公園であったり。それは、いろいろなアイデアでできると思うのですよ。なので、そのことの、競技場の名前の上に、できれば品川とつけていただきたいということの要望をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"いろいろな外国の方が見える、かつてないオリンピック開催中ですので、お互いさまのところはありますけれども、しかし、５,６００人ぐらいの方が住んでいる住宅地ということもあって、やはりその辺の環境は、そんなに悪くならないように、何とか配慮、工夫が必要なのではないかと思いますので、その点も合わせて、周辺整備ということに限って申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"},{"speaker":"いながわ委員","kind":"質問・要望","question":"先ほど、伊藤委員がご発言された、東京都に行ったときもずっとご質問をされていた、冠をつけるという話なのですけれども。ぜひ、先ほども申し上げたように、やはり、都立公園というのですか、それを区民の身近に感じさせるというのも大切なことだと思いますので、ぜひそれは、潮風公園のほうも、都立品川潮風公園とか、そういう形にできるように、行政もやっていただきたいなと思います。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"補足的な意見になってしまうのですけれども。５番の、駅のバリアフリーを一層促してくださいというのを、ネットから出しました。そういうことも含めて、ぜひ、各鉄道会社に、協力してほしいということを強く要望してほしいなという意味で書きましたので。は皆さんと同じ意見ですけれども、競技場周辺整備の駅ももちろんですが、それに限らず、検討、考えていただきたいなというふうに思います。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-011"},{"speaker":"藤原委員","kind":"提案","question":"今、委員長から、そういう形で進めていきたいというお話を頂戴しまして、提案した私としては、ありがたいと思います。やはり、体験してみて初めてというのはあると思いますので、ぜひ進めていっていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"もう発言したのですけれども、この１０番の会場までの交通というところを、さっきの私の発言と、ここのところで言えばよかったのかなとも思ったのです。周辺の環境整備というところで、だぶっておりますけれども。そういう、会場までの交通アクセス、そういう意味も含めて捉えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それをぜひ入れていただいて検討をお願いしたいと思います。それから、大井町から直接会場に行くことも可能でしょうから、やはりいろいろなルートを検討した上で、ここから先は推測なのだけれども、おそらく期間中は、国や東京都が新たなルートを、期間を限定したルートをつくると思うのですよ。例えば、試しに水上バスを走らせたりとか、いろいろなことをやる可能性があるわけではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど、もしかしたら期間中は、そこを、品川区には限定的にというような話もありましたけれども、地元の事業者さんとか、地元の要望からすると、今後のまた観光施策という点からも、これは恒常的に利用可能なのかどうかというところを早期にやはり見極める必要があるのかなというところで、品川区から、かなりこの意見は出していることを、今までの質疑の中でも聞いてはいるのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"アクセス、例えばさっきバスというお話がありましたけれども、当然、品川の中に来てくれるお客さんをおろすためにも、やはり起点となるのは大井町に持ってきてもらって、人が、観光客がいっぱい来てもらうようにしてもらいたいなというのが１点。その辺を調整しながら、区内の交通網についても検討して行っていただきたいということもお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-016"},{"speaker":"いながわ委員","kind":"提案","question":"７、８なのですけれども。何となく、舟運について、私もずっと質問などで取り上げてきましたけれども、先走りというのですかね。羽田も含めて、不定期航路というのですかね。利活用の前に、どういうところがどういう船を出しているのか。私たち、電気ボートにこの間、乗りましたけれども、あれはどういう位置づけなのか。提案というか、考え方だけ、ちょっと申し上げておこうかなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-017"},{"speaker":"南委員","kind":"確認","question":"確か、去年の委員会の資料提供だったと思うのですけれども。選手の移動のための専用道路みたいなのが提示された記憶があるのですけれども。ここに、１１番に、選手の移動の際の道路の使い方などという、こういうことが入っているので、とりわけ、ちょっとその辺、どうなるのかなというのを教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"選手ですとかＶＩＰですとか、そういった関係者につきましての専用のルートは、当然、組織委員会のほうで設置する予定になっております。","voiceIndex":44,"id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"そうすると、当然、大井ふ頭中央海浜公園が、会場になるわけですから、そこへのルートも当然、検討の中に入っているということでいいのですよね。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"今の南委員のご質問への補足みたいになるのですが。もしそういうような使い方があるのだったら、なるべく早く出してほしいということは、強く要望していただきたいなというふうに思います。もちろん、決めるのは品川区ではないので、難しいところはあるかと思いますが、影響するのは品川の区民なので、そのことをぜひ強く要望しておきたいと思います。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-020"},{"speaker":"つる委員","kind":"提案","question":"先ほど、舟運については、８月に集中審議ということで、委員長のほうからありましたので、舟運に関連してということなのですが、これも、これまでいろいろな場所で、いろいろな形で提案を含めて申し上げてきましたが、舟運整備、活用、利活用する、また舟運そのもののルートが確立されていくという中で、特に品川の陸地側というところになると思うのですが、護岸というのか、そこのいたずら書きですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-021"},{"speaker":"高橋（伸）委員","kind":"質問","question":"先ほどは失礼しました。気運醸成の１５番なのですけれども。これ、エンブレムとロゴの使用が簡易にできるようにされたいということなのですけれども、この使用については、どういうふうに今後、区商連との話もあると思うのですけれども。一番は商店街だと思うのですけれども。ちょっとその辺のフラッグとかエンブレムの使用がどういうふうに今後展開をしていくのかをお聞きしたいと考えています。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"以前、皆様にご案内いたしました、リオの前までにアクション＆レガシープランというものができるですが、先ごろ、組織委員会のほうで、今まさにホームページでアップされているのですけれども、その中にも書いてありますが、今のエンブレム以外に。","voiceIndex":52,"id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そのエンブレムのことで伺いたいのですが。そもそも、何でこんなにハードルが高いのかというところ。そこの考え方を教えていただきたいのと。そもそも、そんなに、組織委員会としては、これを行き渡らせるような考え方がなくて、先ほどおっしゃったような、公認であるとか、そういったような、独自のエンブレムを展開するようにという、そういう打ち出しになっているのか、そこについて教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そういったことについては、組織委員会、国、東京都も十分把握しているので、そういった検討をする中で、ロンドンのときもそうだったのですけれども、正式なエンブレム以外に、やはりもう２段階つくっておりますので、そちらを参考に、今まさに検討しているという状況です。","voiceIndex":57,"id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問・要望","question":"例えば、１年前、２年前、３年前となるかもしれませんけれども、それぞれの時期でカウントダウンのイベントを行って、品川区内でこの競技が開催されますというようなイベント企画をしていくのはいかがでしょうか。それから、その他全般としては、せっかく外国から選手が来られるわけですから、その来られた選手の方々と、できれば品川区の子供たちが交流する場をつくっていただきたい。済みません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問","question":"中津江村でしたっけ。カメルーンの選手が来て。いろいろ。村としての。先ほど、八潮団地の名前が出ましたから、例えば、いろいろな考え方の中で、１つとしては、会場周辺に八潮学園があるわけですから、その八潮学園の子供たちと、グラウンドホッケーの選手との交流、すごくいいアイデアだと思うのですよ。非常に距離も近いし。そんなこともぜひ、その他、全般で企画してみてはいかがでしょうか。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-025"},{"speaker":"いながわ委員","kind":"提案","question":"先に質問します。ここは、その発信については、１６番の情報発信ですね。これだけ議員が提案したことを全部やるとしたら、本当に全庁挙げてなので、人員体制の確保と、オリンピック・パラリンピック準備課とほかの部署がしっかりと連携をとれるような体制づくりをしっかりやっていただきたいなという思いがありますので、それも含んで１９番ということで、お願いしたいなと思います。終わりです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"そういうところで、いろいろなランクがあるのかなとちょっと思ったりしたので、ちょっとその辺のことを教えていただきたいなと思っているのです。その辺のことがどうなっているのか、今の日本の２０２０年のオリ・パラをやるのに、どういうふうな仕組みで財政が構築されていくのか、そのあたりをちょっと知りたいのです。多分、エンブレムのことも関係あるのかなって、ちょっと気がしたので、質問しました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そういった財政的な仕組みにつきましては、ちょっと区としては把握してございません。","voiceIndex":66,"id":"exchange-027"},{"speaker":"藤原委員","kind":"質問・要望","question":"１９番で、まさに今、いながわ委員も言ってくれたのですけれども。今、確か、オリンピック・パラリンピック準備課の人数が課長を含めて４人ですよね。予算は、５倍ぐらいに上がったと思うのですけれども、率直に、今の時点で、人数的には足りているというふうに感じているのでしょうか。それとも、違う意見があったら教えていただきたいのですけれども。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"状況といたしましては、現在の限られた人数の中で、精一杯、最大の効果を挙げるべく、努力しているです。これ以上のことは言えません。","voiceIndex":69,"id":"exchange-028"},{"speaker":"藤原委員","kind":"提案","question":"済みません。１９番、うちが挙げたもので、こういう質問になってしまったのですけれども。いわゆる、最後のまとめのときとかにも出るわけですから、これ、ぜひ、委員会で、体制をもっと確保していくべきなのではないかみたいな文書が上がってくれることを主観的に願って、これからよろしく、委員長、お願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-029"},{"speaker":"あくつ委員","kind":"提案","question":"あるのですかね。ある。あるようですけれども、それと、そこをクリックすれば、ボランティアに、どういうふうにつながるのか。自分がやりたいのが、どういうふうにやればいいのかが分かるのか、そんなような状況になっているのですかね。そこのところの確認をします。これはちょっと提案なのですけれども。もし何かご存じのことがあれば、先ほどの情報発信と含めて、教えていただきたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"委員がごらんになられたそのパネルが、どういう形で残っているかというのは、ちょっとこちらもわからないのですが、最終的にお金がどういう形になるかは、こちらは今、はっきりしたことは申し上げられませんが、先ほどご紹介いたしました。","voiceIndex":74,"id":"exchange-030"},{"speaker":"あくつ委員","kind":"質問","question":"済みません。もう短く終わりますけれども。先ほど、前半の部分ですけれども、済みません。失礼いたしました。五輪のバナーがあるというところなのですが。ですから、そこのところを、今、東京都からの情報を待たれるというお話でしたけれども、そういうものを、今、では何ができるのだろうと思ったときに、クリックしてみればいいのではないかなと思ったのですが、そういう形を。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"委員ご指摘のとおり、おもてなしボランティアは、まさにオリンピックを契機として始まった養成講座ですので、早速、リンクをいたします。","voiceIndex":76,"id":"exchange-031"},{"speaker":"伊藤委員","kind":"提案","question":"１点だけで。先ほど、カウントダウンイベントの提案をさせていただきましたけれども。ちょうど今年が区政の７０周年ですよね。だから、それで品川区もさまざまな冠をつけた行事を計画しているのだから、ちょうどいいではないですか。７０周年と、オリンピックの事前、カウントダウンイベント等も含めて、企画してみてはどうでしょうかという提案でありますので。そういうことで、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-032"},{"speaker":"つる委員","kind":"質問・要望","question":"先ほど、あくつ委員のほうからも確認していただきましたが、１６番で情報発信のほうで、既にあるというところも含めてなのですが。３８万の区民の方々１人１人が、世界から集まってくる方、またスポーツを通じてさまざまな発信とかいうことをやっていただいている人に、かかわっていく機会をきちんとつくっていくということの先導役が、オリンピック・パラリンピック準備課の役割であるかなと思うのですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"意見","question":"つる委員の話を聞いていて思い出したのですけれども。気運醸成の中で、区として何でやらなかったのかと思った１件が、女子ホッケーのさくらジャパンの発表を、選手発表をきゅりあんでやりましたよね。あれ、ちょっとどこまで伝わっていたのかというのが、我々、わからなかった。ぜひ、何か今後のチャンスがあったら、その辺は忘れないように、周知してもらいたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"意見","question":"わかりました。その辺、時間がなかったというのは、十分わかりましたけれども。議会で出なくても、また逆に、もっと広げてできるのだったら、例えば、区民の方がもし参加していいのだったら、それこそ区のホームページに、こういうのがありますよというのを出せば、少しでも興味のある方は、何かしらそれに触れ合えるなという気もいたしましたので。ぜひ、今後、うまく利用してください。","respondent":"渡辺委員長","answer":"なければ１回ここまでで区切らせていただいて。大項目の、オリンピック・パラリンピック推進に関することを、１回ここで区切らせていただきます。続けて、大項目の、障害者スポーツの推進、また、文化プログラムの推進は、次回８月が舟運を予定しています。","voiceIndex":86,"id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして京急に要望書も何度も提出を、地域の方がされています。もう２年前ぐらいからずっと、地域の皆さん、この地元の地域の皆さんの強い要望ですので、お願いしたいと思います。済みません。２０年たっていますので、改めて、こういったオリンピック・パラリンピック、障害者スポーツの推進というところでは、こういった研究し直すということもしていただきたいなというふうに思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問・要望","question":"組織委員会等で認定をする文化プログラムと、あとは、文化庁、国がやっているところの文化力プロジェクト、また、それには入らないけれども、芸術文化活動とか、あとは品川区としての区民芸術祭の位置づけと、これを確認する必要というのはあると思いますので。何をやればいいのかというところですね。文化プログラムに対して。国のほうからもですかね。この２点、要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-037"},{"speaker":"伊藤委員","kind":"意見","question":"文化プログラムを勉強していく大きな観点として、５０番、５１番に書かれているのですけれども、やはり、品川区内の今ある有形・無形文化のデータベースの構築が、どうしても必要だと思うのですよ。そういう方々を縦横に、やはり把握していくのが、品川区であり東京都であると思うから、そこをまずベースとして、そこからさらに派生していく仕組みをつくっていくべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-038"},{"speaker":"南委員","kind":"提案","question":"ここの担当、オリンピック・パラリンピック準備課としては、そこまでなかなか、しかも４人体制の中では、かなり厳しいことになると思いますので、品川区に、文化スポーツの担当部が設置されているわけだし、区内、区との関係では、非常に良好な関係の文化振興事業団もあるわけですから、そういうところと協働して、しっかりと精査をして、１つの体系というか、そういう関係を、あるいは品川区民の状況を。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど、いろいろな五輪の精神というところでご紹介がありましたけれども、基本的に、国のほうからも、五輪教育の内容というのは出ておりまして、品川区も、もう全ての学校がですかね、五輪教育の指定校になっているというところで。ですから、ここのところの教育、文化プログラムというところの教育を、どのように品川区の児童生徒に教えていくのか。それは教えるべきだというふうに思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-040"},{"speaker":"いながわ委員","kind":"提案","question":"済みません。それだけではいけなくて、もっと幅広くなどという提案が、委員からあったのかななどと思うのですけれども。なかなかそこまで把握はできないかもしれないですけれども、でも、極力、本当に地域のそういう団体に属していない人たちも一緒になって参加できるような体制を整えていただきたいという思いで、この５０、５１を提案させていただきましたので、ぜひよろしくお願いいたします。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-041"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ご意見出て、ここにも書いてあるとおり、本当に必要な部分だと思っています。当然、これ、区の中でやっていく部分と、実際、８月５日から視察に行かれたときに、現地での、どういう文化プログラムをされるかというのは、やはり行かれる方、職員の方、議員も派遣されますけれども、その辺、次の委員会でぜひ教えてもらいたいなと思います。","respondent":"渡辺委員長","answer":"かなり、いただきまして。次回に、それをまとめたものをまた引き続きお示ししたいと思います。それと、皆さんにお願いなのですが、この、今、Ａ３の資料、これは多分、１年通して大事になる。皆さんから項目が出ることで議論が深まるというのはよくわかりましたので、大事に。","voiceIndex":99,"id":"exchange-042"}]},{"id":"topic-02","title":"リオデジャネイロオリンピックの視察","agenda":"リオデジャネイロオリンピックの視察","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"本当に、今、拝見をした限りでは、かなりのハードスケジュールのように思えます。お伺いしたいのが、今朝もまた報道番組でやっていましたが、非常に現地の治安が悪いというような報道をやっていましたが、現状での品川区としての認識。ちょっとまず、意見を述べる前に、それを教えていただきたいと思います。現状で結構です。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"この間、間に入った専門の業者ですとか、旅行会社とも、いろいろ話を伺う中では、やはり油断はできないという状況はあります。","voiceIndex":107,"id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それで、伺いたいのは、現地に行かないとわからないというところで、もちろん、競技場に行けば競技の模様というのは見られると思うのですが、先ほどから何度も申し上げているように、文化プログラムの件は、先ほど、リオ市が主催のもの、全体で認定しているものではなくて、リオ市が定めているものというようなことがあったのですけれども。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-044"},{"speaker":"吉田委員","kind":"質問・要望","question":"ヒアリングと、それから調査と、インタビュー、ヒアリングとは別にインタビューというのと、それから、観察調査というのがあるのですけれども、それぞれどういうような内容でお考えなのか。それで、各派からの要望がすごくたくさん出ているのですけれども、どこにどういうようなことを聞いていくとか、それぞれのヒアリングの内容の項目が、もし現時点でピックアップされたものがあれば、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-045"},{"speaker":"南委員","kind":"質問・要望","question":"この大きなＡ４判の行動予定表は、先ほどの説明だと、４日間とも全ての観戦以外のところで、例えば１日目で言うと、夕方の時間のボランティアグループとのヒアリング、あるいは２日目で言うと、夕方のロンドン市関係者とのヒアリング等々、こういうところは、ただ見るだけではなくて、ヒアリング、会話をしていろいろ調査するわけですけれども、そことは会える約束がもうとれているという理解でいいのですか。","respondent":"小川オリンピック・パラリンピック準備課長、渡辺委員長","answer":"具体的なヒアリングの内容ですが、それぞれ、相手によって、やはり目的ですとか、こちらが狙っている視点は全て異なるので、そちらについては、こちらのほうできちんと整理をして、資料としては。正副で調整の結果、どれ１つでもおかしなものはなく、非常にチェックポイントとして的確なご意見を賜りましたので、当委員会と皆さんで了承いただいた上で、調査団に、こちらの調査項目を託すということにしたいと思いますが。","voiceIndex":118,"id":"exchange-046"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと、さっき言わないでごめんなさい。ほかの出場選手の要望や意見の聴取というのは、なかなかちょっと難しいのではないかなと思っていたのですけれども。これは、実現性があるのかどうかと。どういう思いを持ってこういうふうになったのかというあたりを、ちょっと説明していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問・要望","question":"おっしゃるとおりです。なかなか、非常に難しいかと思います。ただ、もしそこまでできれば、一番、調査団として、非常に大きな成果になるのではないかというところで、ここに、次回の開催国として、開催地としての要望とか、意見の聴取というところで書かせていただきましたけれども。決して、無理をしてということではありませんので、できればという思いで入れさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-048"}]},{"id":"topic-03","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"前回の委員会で、リオ視察の仕様書を提供していただきたいというお話をさせていただいて、答弁としては、出された資料、金額だとか、等々書いてある、それと同じだということで、でも出すことはやぶさかではないというようなご答弁をいただいたので、改めてその後に、私、仕様書をお願いしたいと申し上げたのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-049"},{"speaker":"南委員","kind":"質問","question":"正副の議題で諮っていただいたのはわからなかったのですけれども、私は、前回の委員会で、２回お願いして。そのときに、最終的な答弁もなかったので、お願いを２回したということで、出していただけるというふうに思っていたのですね。正副のところでそういう話になったら、それはそれで私にも教えていただきたかったし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"ええ。ぜひ、ちょっと、飛ばされて結論を出すというのは、ちょっといささか、私の思いと違うので。やはり訂正もしていただきたいし、ぜひ求めていただきたいというふうに思っています。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"私が求めたのは、仕様書、つまりこの契約をするに当たって、区側の考え方を盛り込んだもの、これが仕様書です。返ってきて出された資料は、その１つ１つに対して、具体的な金額だとか、そういうものが書いてあるものであって、仕様書とは違うのですよ。だから、仕様書を出していただきたいとお願いしたのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"だから、全然問題ない資料なわけですよ。やはり、区がどういう思いで、この予算を組みそして業者に委託という形で出したのか、それをやはり、この委員会では、いろいろ議論になったところなので、ぜひ資料として提供するべきものだと。ぜひ、出していただいても全然差し支えないものだということなので、全然、諮る必要もないと思うので、ぜひ要望を受け止めてください。お願いいたします。","respondent":"渡辺委員長","answer":"この件に限らず、普段の各委員会でも、資料要求という位置づけであれば、正副で検討という形になるので。ちょっとその手続き論で、ご確認だけはさせてください。","voiceIndex":137,"id":"exchange-053"},{"speaker":"吉田委員","kind":"質問・要望","question":"ネットとしては、そういう資料があるのであれば、別に出して差し支えないものであれば、出していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"区民・都民のすごい関心があるところの、そういう資料を、みんながしっかり確認して、そしてことの判断、善悪をしっかり判断するということは、そういう姿勢は、議員として求められていることですから。書いてあることと同じだからといって、きちんと自分たちで確認をした上で不要だというのだったらともかく、確認もできない中身で、状況の中で不要だというのは、私はそういう意見には、理解できません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-055"},{"speaker":"南委員","kind":"質問・要望","question":"主張ではありません。それは私たちの理由です。出していただきたい理由です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6498#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":44454,"voices":152}},{"id":"h28-20160729-10","meetingId":"h28-cm07","date":"2016年7月29日","dateIso":"2016-07-29","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"リオデジャネイロオリンピックの視察","agenda":"リオデジャネイロオリンピックの視察","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１,５００万円分の税金といったら、一体何人で何年分の税金額になるのでしょうか。その他オリンピックによる価格の高騰や、苦しい区民生活の実態、現地での深刻な治安問題、また、品川区民の理解が得られない問題などを踏まえて、高額な視察というのはやめるべきだと思いますので、議員派遣の議決を取り消す決議や、区議会が参加しないこと、そして、区に実施の中止を求めることを強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-001"}]},{"id":"topic-02","title":"その他の(1)議長会等の報告","agenda":"その他の(1)議長会等の報告","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"初めてというか、議会費の要望は、通常とちょっと違う形になったのか。ごめんなさい、何でもないです。","respondent":"大沢議長","answer":"いつもどおりです。","voiceIndex":23,"id":"exchange-002"},{"speaker":"中塚委員","kind":"意見","question":"１点すみません。内容については、行革委員会との調整や、やはりこういう重大な問題なので、全会一致を大事にしたいと思うので、正副を中心に調整ができないかと思ってはいるのですけれども、ひとつご検討いただけたらと思います。","respondent":"鈴木（真）委員長","answer":"今お話にありました行革委員会との問題があります。次回の議運が開かれるときの前に行革委員会もありますので、その辺、行革委員会の対応も十分踏まえなければいけないことがあると思いますので、ここで結論を出すわけにはいかないと思います。","voiceIndex":30,"id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5192#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":9135,"voices":33}},{"id":"h28-20160822-6","meetingId":"h28-cm08","date":"2016年8月22日","dateIso":"2016-08-22","committee":"区民委員会","time":"午後 １時００分～午後 ３時５３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)平成２８年度協働事業提案制度および地域振興基金を活用した区民活動助成制度の審査結果","agenda":"はじめに、(1)平成２８年度協働事業提案制度および地域振興基金を活用した区民活動助成制度の審査結果","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"この選定された、例えば４ページにある「Ｅｎｊｏｙ！５ページの不選定で、空き家対策サポート事業というのは、団体がやられているというのは承知しているのですけれど、今、品川区の取組みで、その仕組みをつくっているのも承知しているのですが、逆に品川区がつくったその仕組みで、本当に賄えるのですかというところですよね。これでばさっと切って、終わりなのかどうなのかという。","respondent":"河内協働・国際担当課長","answer":"そういった意味で、まず第一歩だということであると思いますが、賄えるように、今後進めていくことが妥当ではないかと考えております。その中で、今回この事業につきましては、さまざまやっている中で連携が難しい状況になるということで、不選定となったというものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"多分次に来る行政課題というのは、そこで選択したところが、実を言うと限られた地域でしか活動していなかったとなってしまうと、それは今度行政課題で、では今度あいている荏原地区とか、大井地区とかはどうしましょうという話になってくると思うので、広く浅くではないですけど、品川区全体を俯瞰して、うまく配置というのかポジショニング、例えばどこかのエリアが空白地だったら、そこにそういった団体の。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"提案","question":"２つの事業ですけれども、それぞれの目的に照らしたり、手法としてどうなのか、いろいろな視点があるかと思うのですけれども、選定、不選定の一番の判断の基準というものが何か、そこを一つ教えていただきたいのと。事業がよくわからないと、提案してもその結果どうなのかという感じにもなると思うので、そこの仕組みもあわせてご説明ください。","respondent":"河内協働・国際担当課長","answer":"私どもから団体に支援を行うというようなものです。福祉的課題の件です。協働事業提案制度および区民活動助成制度におきましては、庁舎、こみゅにてぃぷらざ八潮、窓口対応、電話対応などでいろいろな説明、相談を受けているところです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"もう一点だけ。この事業が始まって、もう何年かたちますけれども、事業が始まったとき、初めてというのもありますから、たしか２つぐらいのことがあって。今までのその経過を改めて伺いたいのと、今後の課題であったり、今後の方向性について、区としてはどういうふうに持っていきたいと思っているのか、最後に伺いたいと思います。","respondent":"河内協働・国際担当課長","answer":"したがいまして、せっかくご提案いただいた内容を無にする可能性もあるということで、一方で区民活動助成制度につきましては、団体の方が取り組んでいる内容を応援するものですので、むしろそちらのほうを積極的に応援して。","voiceIndex":10,"id":"exchange-004"},{"speaker":"こんの委員","kind":"提案","question":"参考までにお聞きしたいのが、もう何年かされているこの事業の中で、協働事業提案制度は今までにいわゆる行政が提案したものに対して、なかなかマッチングしなかったという不選定で終わってしまった、どこも受けられるところがなかったということが、あったのかどうかというのが１点と。この２点をまずお聞きします。","respondent":"河内協働・国際担当課長","answer":"一方で、団体の提案の中にも既に区のほうでやっておりました支え愛・ほっとステーション事業の中身でありますとか、そういったものもございましたので、できるところとできないところはしっかり分けたうえで、そうであったとしても地域支援の新たな担い手。","voiceIndex":16,"id":"exchange-005"},{"speaker":"こんの委員","kind":"提案","question":"そうすると、一緒に聞けばよかったのですが、２番の区民活動助成制度、こちらも区民の方が提案したものを供されるということなのかというのが一つと。そうしたとき、今後そうしたところの知恵もいただきながら、協働まではいかなくても、何かのときには一緒にするというお考えで、いつもそういった区民の団体とのおつき合いというか、そういうものもあるかどうかというところをお聞きします。","respondent":"河内協働・国際担当課長","answer":"不選定になったところですが、不選定になったのはなぜかというところはしっかりご説明するところではあるのですが、区との絡みだとかいろいろなものがあります。最近助成制度で非常に散見されるのが、自立度を高めるための収益性というものがあります。","voiceIndex":20,"id":"exchange-006"},{"speaker":"こんの委員","kind":"質問・要望","question":"現状もよくわかりましたし、また協働というところでの区が一定期間の協働の期間があったとしてもその後のこともしっかり、羽ばたくと言ってくださいましたけれども、確かに区の中でサービス向上を、担い手としていただく、完全なるはばたきはなかなか、やはり区の流れもあるでしょうし、国土設計みたいなところもあると思うので、品川ナイズしなければいけないものは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-007"},{"speaker":"藤原委員","kind":"提案","question":"申請、提案を見ていて、どれも素晴らしいとは思うのですけれども、前回も伺ったかもしれないですけれど、目的のところで「区が直面する行政課題に対して」というのは、そもそも論です、これは行政が私はやることだと思っているのですけれども、なぜこういう形でやるのか。確かに細かくやっていくという意味ではいいかもしれないですけれども、どうなのかなというそもそも論です。そこを伺いたいと思います。","respondent":"河内協働・国際担当課長","answer":"さまざまな中で、行政が主軸でやるべきものについてぶれはないのですが、それを補完することによりましてトータルで区の福祉の向上につなげてまいりたいというふうに考えながら、進めているところです。","voiceIndex":23,"id":"exchange-008"},{"speaker":"藤原委員","kind":"提案","question":"そうしたら、目的のところにそういうことを書いたほうがいいですよ。それと続けて質問しますけれど、そういうふうに納得しましたと言いつつ、協働事業提案制度は申請４件ではないですか。区民活動助成制度は申請５件ではないですか。この数字について、どう評価するのか。それと、それを把握して次への課題はどういうふうに考えているのか、教えていただきたいのと。","respondent":"河内協働・国際担当課長、小川オリンピック・パラリンピック準備課長、堀越地域振興部長","answer":"オリンピック・パラリンピックにつきましては、重要な課題と認識しておりまして、次年度以降もそういったところの提案が出ますように。８月下旬を締め切りといたしまして、こちらにつきましては実は協働・国際担当とも連携させていただいて。応募件数のところですけれども、今回のテーマ、毎年そうなのですが、オープンデータの部分と高齢者の担い手養成という形で。","voiceIndex":27,"id":"exchange-009"},{"speaker":"田中委員","kind":"提案","question":"去年、この提案制度のことについて質問させていただいたとき、ここの審査会に私たちも出て、その内容をちゃんと団体の方たちから意見を聞くようなことはできませんかということを、私、質問したのですけれど、それはなかなか難しいということだったので、それならなおさら、団体の方たちは一生懸命出してきてくれていると思うので、内容をもっとわかりやすく出してほしいと思います。どうでしょうか。","respondent":"河内協働・国際担当課長","answer":"課題1)の選定された事業につきまして、ご説明したいと思います。「オープンデータの公開と利活用促進」です。先ほど委員から、ハッカソン、アイディアソンにつきまして用語の説明がございました。","voiceIndex":31,"id":"exchange-010"}]},{"id":"topic-02","title":"わんわんパトロール事業の推進ついて","agenda":"わんわんパトロール事業の推進ついて","exchanges":[{"speaker":"いながわ委員","kind":"意見","question":"この手提げ袋が防犯グッズという感じで出ていますけれど、防犯グッズという表現になっているというのがまず一つと、これすごく小さい字でわからないのですけれど、この手提げ袋ですが、今、現物はありますか。〔「現物はありません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-011"},{"speaker":"いながわ委員","kind":"質問","question":"本当に多いのです。その人たちがこの防犯のかばんを持っていたら、機運的には品川区に協力をしておきながら、そういう始末をしないという話にもなってくるので、だからせっかくやるのであれば、そういう指導もしっかりやって、できる方に渡すべきではないかという思いもするので、ちょっと質問に当てはまるかどうか別にして、その２点をお聞かせいただければありがたいと思います。","respondent":"濱田生活安全担当課長","answer":"防犯グッズについては防犯バックのことで、今、現物はございませんが、デザインはあります。〔「ちょっと、こうやって掲げてもらえる？","voiceIndex":43,"id":"exchange-012"},{"speaker":"いながわ委員","kind":"質問","question":"ビニール袋とか尿をしたときは水を掛ける、それはいいのですけれど、両手がふさがっているわけではないですか、その人たちは。だから協力してくれる人の安全を考えて僕は質問しているのです。逆に言えば、ただ散歩しているだけでなく、こういうものを持っていればその意識が出てくるわけですから。そうすると、こちらも何かあったら言えるではないですか。ただ１１０番に掛けても、「どこですか。","respondent":"濱田生活安全担当課長","answer":"ですので、協力者についてそこで１１０番して、犯罪を予防してくださいと、お願いはしますけれど、必ずしも、けがなど一般の方されますので、それはもう、まず抑止力を高めるということを目的としておりますので、持っていただくことが今回は大事だということで。","voiceIndex":47,"id":"exchange-013"},{"speaker":"本多委員","kind":"質問・要望","question":"例えばよく商店街とかのイベントで、大崎一番太郎とかがものすごく人気ではないですか。太郎とか銀次郎とか。そのゆるキャラに求めるものはわかるのですけれども、今回のこのゆるキャラとか、整合性がどこにあるのかなと思うのです。というのは、区内でほかにいろいろパトロールとかされていると思うのですけれど、こういう優しい取組みによってほかの見守りが手薄にならないのか、その辺が心配なのです。","respondent":"濱田生活安全担当課長","answer":"いわゆるギブアンドテイクみたいなものです。その協定の内容は全く違いますので、それぞれ独立した事業ということで考えていただければと思います。ほかの見守りが手薄になるということですが、この事業につきましては多面的に実施して、今後そういったことも検討課題として。","voiceIndex":49,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"パトロール事業の推進ということですけれども、やはり気がかりといいますか、心配になる点があるのですけれども、まずこの事業とその推進の根拠条例というのはどの条例かというのと、その条例の目的とこの事業の推進が、どういうふうに具体化されているのかというのをご説明いただきたいのがまず１つ。そこについてはどういうふうに考えていらっしゃるのか、伺いたいと思います。","respondent":"濱田生活安全担当課長","answer":"それとこれを持つことによってまちの方が危険にさらされたり、社会というかそういうふうなことが危惧されるということですが、これはいわゆるＰＴＡが前かごにつけている、通常の買い物のときに協力して「防犯活動実施中」という。","voiceIndex":51,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"そもそも論なのですけれども、このわんわんパトロールという事業を、どういう背景からこういうことをしようという発想になったのでしょうか。","respondent":"濱田生活安全担当課長","answer":"１６団体ありますが、毎年広報しながわ等において募集しておりますが、なかなか応募がありません。その中で防犯というものは警察、行政、区民の方、これがいわゆる三位一体になって、はじめて防犯、抑止力が高まるものだと、私は思っております。","voiceIndex":53,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"思うのですけれど、先ほどまもるっち等の話が出ていたり、私はやはり防犯カメラというのは毎回言いますけれど抑止力になっているという思いがあるのですけれども、その質問ではないのですけれども、課長が警視庁から来てくださって、結構こういう施策が多いとか、好きではないですか。課長が絶大なる効果があるのだったら、ぬいぐるみで効果があるのだなと、専門性ですからと思って。大体でいいです。","respondent":"濱田生活安全担当課長","answer":"予定人数です。１つの事業者、病院につきまして２０人を予定しております。２０人掛ける１８事業者ですから、３６０人。","voiceIndex":55,"id":"exchange-017"},{"speaker":"藤原委員","kind":"確認","question":"１点だけ、確認ですけれども、抑止力になるというお話ですが、課長は警視庁から来てくださっているので犯罪のプロですけれども、いわゆるあのバッグが犯罪を犯す人からすると、あのバックを見て、このバッグ持っていてここの地域はまずいぞと、抑止力になるのですね。３６０人ぐらいの方があのバッグを持っていてくれると、犯罪しようと思う人が、ここはまずいぞと。それで、いいのですよね。","respondent":"濱田生活安全担当課長","answer":"このバッグを持ったから、ということではございません。あくまでもこの品川地区が防犯意識が高いのだということを、犯罪者に認識させることが目的で、犯罪を起こさせないまちづくり、こういったことを構築するのが目的の事業です。","voiceIndex":57,"id":"exchange-018"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうなると、散歩に行く範囲もその人によって、時間帯によってなので、さまざまなのでしょうけれども、そうしたことを考えると、１８事業者で今後拡大をしていくようなご答弁もありましたけれども、ぜひ抑止力ですから、やはりよくよくそれを広めていく、意識を高めていくというところがどうしても、皆さんと一緒に協力をいただきたいという方向性で持っていくのが大事なのかなと思いますので。","respondent":"濱田生活安全担当課長","answer":"途中の経過で説明いたしましたが、わんわんパトロール募集というポスターを動物病院に掲示していただきます。そのポスターを見て、動物病院のほうで登録というのは、申込書を置いておきますので、それを書いていただきます。なおかつ協力者に行う上での注意事項を渡す。","voiceIndex":59,"id":"exchange-019"},{"speaker":"こんの委員","kind":"確認","question":"ありがとうございました。それについてご答弁があれば教えてください。それから、これから平成２９年度の拡充というお話ですけれども、これからさらに獣医師会に入っていないところの事業者を拡大していくのと同時に、開業していくようなところも、これからあると。新しく開業するところも拡充の一つとして考えているのか、これは確認です。そういったお考えがあるかどうか。その２点です。","respondent":"濱田生活安全担当課長","answer":"新規の病院ですが、これは当然新しく加盟する事業者も対象に考えておりますので、そういった事業者の把握があれば、働きかけ等行っていきたいと思います。","voiceIndex":61,"id":"exchange-020"},{"speaker":"こんの委員","kind":"質問","question":"そうなると、抑止力だからただ持っていてくださいねという注意事項だけだと、やはりそれは区として、協力をいただく方の安全もきちんと確保しなければいけない、だからこそ保険もきちんと協力者の方にも入っていただくということにしているわけですから、ちゃんと協力をいただくという意味合いも含めて、きちんとパトロールし、通報するまでの流れみたいなものをきちんと。","respondent":"濱田生活安全担当課長","answer":"委員がおっしゃることも踏まえまして、わかりやすいような、相手に手渡す説明書は作成していきたいと思います。","voiceIndex":63,"id":"exchange-021"},{"speaker":"田中委員","kind":"質問","question":"登録の手続についてですけれど、申込みをして、その場でもうバッグを手渡す、１１０番の手続の紙を渡すのか、それとも後日区から送られてくるのか、それとも区から事業者に送られてきて、それを渡すのか、教えてほしいのと。バッグを持っている方を見かけて、犬を飼っていない方たちが、もし私も持ちたいとなった場合はどうなるのかということを、まず３つ教えてください。","respondent":"濱田生活安全担当課長","answer":"デザインにつきましては、もう今回につきましては変更は間に合いませんので。〔「ああ。散歩中にそのバッグをほしいとなれば、区のほうに問い合わせて、先ほど話しましたとおり、２通りの方法を案内します。近くに自分の通っている動物病院があれば、その動物病院を案内しますし、なければ区のほうに来てくださいと。","voiceIndex":65,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"デザインについては、わかりました。もう発注してしまっているということなので。しながわ」のほうを向けられてしまったらどうするのとか、思ってしまいますよね。もしかしたら、お買い物バッグに使いたくなるようなデザインだったら、いろいろな人が持って、先ほど言った抑止力にもつながるかもしれないではないですか。申込みの手渡し。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"そうなのです。それで先ほどの、ちょっと話がずれてしまうかもしれないですけれど、散歩をしながら、バッグを持ちながら、何かがあったときの１１０番の仕方というのがあったのですけれど、本当に両手がふさがっていたとき、何かを見かけて１１０番したときって、すごく焦ってしまって、今、この現場を伝えなければいけないのに伝えられなかったりとか、結構するのですね。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-024"},{"speaker":"伊藤副委員長","kind":"質問","question":"簡単に質問しますけど、この事業、いつまで行うつもりなのですか。正しいことだけれども、これが例えば５年先、１０年先に至ってどうなのか。なので、今はこれでいいかもしれないですけれど、例えば５年先、１０年先、あるいはその先のこの事業展開をどう考えていくかということについては、ぜひお伺いしたいのですが、いかがでしょうか。","respondent":"濱田生活安全担当課長","answer":"この事業につきましては、ずっと行う予定です。８３運動はどういうふうにやっているか、ちょっと私はわかりませんが、アンケートを年に１回実施して、それで協力者の方の意見を吸い上げ、そこで改善できるところは改善していきたいとは考えております。","voiceIndex":70,"id":"exchange-025"},{"speaker":"伊藤副委員長","kind":"質問","question":"もしこの事業を続けていくということになれば、相当管理をしていかないといけないと思います。間違いなく。だから、これを今やろうとしているわけですから、今まさに課題があったことも含めて、ＰＲ一つとっても、これ、品川区の窓口も、区民に対する直接のＰＲはないわけでしょう。となると、これはどうなっていくかというと、申しわけないけれども、防止条例にもなっていく可能性があるわけです。","respondent":"堀越地域振興部長","answer":"バッグにつきましても、そのバッグを持っていただくというのがこの目的を達成する手段というふうに考えておりまして、いろいろデザインについてご指摘いただきましたけれど、なるべくこういう目立たないとか、耐久性ですとか、いろいろなことを考えてつくったつもりですが。","voiceIndex":72,"id":"exchange-026"}]},{"id":"topic-03","title":"マイナンバー制度実施に伴うコンビニ交付","agenda":"マイナンバー制度実施に伴うコンビニ交付","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"２３４店舗で発行されると書いてあるのですけれど、要はこの発行の手順というのは、基本的に各コンビニが、その店舗に対してこうやるのですよ、もし聞かれたらこう答えてくださいというのをやるのですか。それとも行政がこういう手順でやってくださいと、どちらなのか。機械が多分違うと思うのですね。","respondent":"提坂戸籍住民課長","answer":"それで、基本的にはご本人様が、この画面の展開に沿ってやっていただくような簡単な仕様になってはありますけれど、もしご不明の点があった場合については、このマルチコピー機というのは行政サービスのみでなくいろいろなご利用ができるのですけれど。","voiceIndex":80,"id":"exchange-027"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひ、行くのは皆コンビニでとる方が、想定からいくとコンビニでとるのが多いからやっているのだと思うのですけれど、その人たちがどうすればいいのだろうというのを、しっかり店員の方がフォローアップできるような体制を、改めて各コンビニの本社に通達するのか、２３４店にそれを言うのかは別にしても、そこはしっかりやっていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"私は新たな犯罪に利用されてしまうのではないかと心配するのですけれども、その点改めて伺いたいと思います。それと、さまざまなトラブルの原因というのは明確になっているのか、その対応がどうなっているかもあわせて伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"マイナンバーカードにつきましてＩＣチップのほうには、所得情報ですとか、健康情報、地方税関係情報、年金給付関係情報等のプライバシー性の高い個人情報は入ってございません。顔写真とかパスワードを設定しておりまして、不正利用のリスクは限定的だです。","voiceIndex":83,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"これは現金のやりとりはないですけれど、いわゆる個人情報のやりとりをコンビニで行うと。１人当たりです。総数というよりも。そういう状況で、そこからコンビニ交付を利用するという人が、さらに１人当たりどれぐらいとなるのか、伺いたいのと。これまでにこの仕組みづくりに幾らの初期投資をして、今後これを維持するのに年間幾らぐらいかかるのか、費用についてもご答弁いただきたいと思います。","respondent":"提坂戸籍住民課長","answer":"今回どれぐらいコンビニで交付されるかということで、なかなか想定は難しいのですけれども、昨年度の本庁舎と地域センター、住民票と印鑑証明書につきましてはサービスコーナーでも交付できますので、それを合わせた１年間の交付実績の約半分の件数の、約１割程度を見込みまして。","voiceIndex":85,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"現状でも住民票の写しは、１人当たり年に数回ぐらい、また税情報だとさらに減ると。その状況で１割程度の方がコンビニを使うだろうと、そういう行政需要に対して、区内２３４店舗で、ある意味２４時間、初期投資は品川区は幾らかという、全国的にはすごい金額になるわけで。こうした求められる行政需要や費用面から見ても、決して進める環境にはないと改めて思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-031"},{"speaker":"田中委員","kind":"質問","question":"９月２０日からサービスが開始されるということで、コンビニの店員、アルバイトの方とかいらっしゃると思うのですけれど、どういった注意をされているか、情報漏えいしないための機械的な注意ではなくて、人と人、何といいますか、マイナンバー法でこの番号は見てはいけないとかいろいろあるではないですか、そういった注意は、コンビニの方たちはどのようなものを受けているのか、わかりますか。","respondent":"提坂戸籍住民課長","answer":"品川区でコンビニ交付を開始するのは９月からですが、全国では既に２０５自治体、２３区でも約半数の自治体が既にコンビニ交付を開始しているところでございまして、コンビニについてはそれぞれ本部のほうから。","voiceIndex":88,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"全国でも行われているのはわかっているのですけれど、９月から行われる品川区の状況は、ちゃんと品川区として注意していかなければいけないのですよねという話を、前のこのコンビニ交付の話が出たとき、ご答弁いただいたかと思うのですけれど、そういった注意は、これからはされないのですか。","respondent":"提坂戸籍住民課長","answer":"これから実店舗検証ということで、区内の幾つかの店舗で検証作業を行ってまいりますけれど、その際にコンビニのほうとも連絡をとったりする機会がありますので、その辺の周知徹底を図ってまいりたいと考えております。","voiceIndex":90,"id":"exchange-033"},{"speaker":"いながわ委員","kind":"意見","question":"すみません、１点だけ。よく複合機とかで出てくると、履歴が全部残るのですよね。いろいろ情報漏えいはそこから大体始まるという話もあるのですけれど、コンビニは大丈夫なのですよね。ここで大丈夫と言っていただければそれで終わりなのですけれど。","respondent":"提坂戸籍住民課長","answer":"その辺の情報漏えいの防止については、徹底してコンビニで取り組んでいるはずです。","voiceIndex":92,"id":"exchange-034"}]},{"id":"topic-04","title":"品川区民芸術祭２０１６の開催","agenda":"品川区民芸術祭２０１６の開催","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"そんな中でほかの品川区出身のアーティストはいらっしゃると思うのですけれど、もうそろそろほかの、Ｃｈａｒさんにかわるような方の出演とか、交渉とかしていっていただきたいと思うのですけれども。例えばギターリストの高中正義さんとか、大井町出身ですから、個人名を挙げたらあれですけれども、していただきたいと思うのですけれど、その辺についてはいかがでしょうか。","respondent":"鈴木文化観光課長","answer":"区内に住んでいたり、ゆかりのある音楽家の方というご質問ですが、今、例に挙げていただいた高中さんのほかにも何人かいらっしゃいまして、寺内タケシさん、ＡＩさん、二胡の奏者のウェイウェイ・ウーさんとかいらっしゃいまして、品川文化振興事業団のほうのコンサートとか。","voiceIndex":102,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区民芸術祭ということですけれども、４年後の東京オリンピック・パラリンピックを思うと、この芸術祭に求められてくる新しいというか、もっと強化をしていく視点を考えていく時期になってきたのかなと思うのですね。今全くないというわけでなくて、どういうふうにお考えなのか、どういう環境づくりが求められているのか、そこを伺いたいと思います。","respondent":"鈴木文化観光課長","answer":"それ以外にも、障害者福祉課とも連携をしておりまして、区民ギャラリーでの作品の展示だとか、オリンピックに関する文化プログラムの中でも、そういうような視点で協力もしくはお願いできるようなところについては、今後もしっかりと取り組んでいきたいと考えております。","voiceIndex":104,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"知的障害だけでなく、ちょっと休むスペースが必要であったり。その困難は一体どこにあるとお考えで、どう解決していこうかという区の考えも伺いたいのですけれども、団体の方や区民の方によくお話を伺って、どういう工夫があるのか、できるのか、そういう視点が大事だと思うのですけれど、改めてそこを伺いたいと思います。","respondent":"鈴木文化観光課長","answer":"委員ご指摘のように、４年後に一気にというわけにはいきませんので、今から少しずつ、ただ実施する各団体のほうの施設やいろいろな事情もありますので、できるところからお声かけをして、進めていただきながら、区のほうもしっかり取り組むというところで、考えているところです。","voiceIndex":106,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"課題の抽出と整理、そのために団体や区民からよく話を伺うところから始まるのかなと思うのです。トイレや案内、休憩所も含めて、まずそういう課題の抽出を、当事者の意見を聞いてよく話し合った上で、実践しながら改善していくという。繰り返しですが、ぜひそういう視点を持ってレベルアップをしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-038"}]},{"id":"topic-05","title":"五反田宇宙ミュージアムの開催","agenda":"五反田宇宙ミュージアムの開催","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"前回やって、公表だったので５０周年も絡めて盛大にやるというのは、行きたいなという思いが非常にするのですけれど、広報の部分で、しながわ観光協会にはこういうのは出さないのですか。というのが１点と。やはりそこは連携していただきたいのですけれど、多分これ、９月１０日、１１日は戸越、旗岡、氷川と祭礼が重なっているときで、氷川さんだとこのど真ん中というところですよね。その辺ちょっと。","respondent":"鈴木文化観光課長","answer":"観光協会も文化観光課のほうが所管、窓口になっておりますので、そこは連携をしながらということで。ただ今回は、先ほど申し上げましたように区内の小中学校の授業がない土日というのと、実はこのころ、先ほどの芸術祭もそうなのですけれど、どこもやはり重なってしまうのですね。","voiceIndex":114,"id":"exchange-039"},{"speaker":"いながわ委員","kind":"質問・要望","question":"やはりある意味調整というか、できる限り。私は行けないのですよ。重なっちゃって。それは別として、ぜひ今後いろいろ、観光協会とか情報をある程度持っていらっしゃると思うので、もちろんケーブルテレビもそれなりの情報があると思うし、連携をとってぜひやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-040"},{"speaker":"中塚委員","kind":"確認","question":"この五反田宇宙ミュージアムや、日常的にも生解説というのは今どうなっているのか、どう大事にされているのか、そこだけ伺いたいのです。なぜかというと、運営が変わったときも、生解説というのは大事だと思っていますという説明を、もう大分昔の話ですけれどあったので、今はどうなっているのかなと。そこだけ確認させてください。","respondent":"鈴木文化観光課長","answer":"現在も専門の解説員の方にお願いしまして、生の解説を行っているところです。","voiceIndex":117,"id":"exchange-041"},{"speaker":"中塚委員","kind":"意見","question":"その日集まってもらった方の年齢層だったり、雰囲気だったり、中学生と高校生で、子どもたちも大分変わりますし、社会人になっても、ここにも「宇宙のなぞに挑む、人類の活動を紹介」、こういうのはいつの世代でも大事だし、わくわくすることだし、それには生解説はとても大事だと思いますので、今後ともひとつよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":119,"id":"exchange-042"},{"speaker":"伊藤副委員長","kind":"質問","question":"非常に細かい１点だけなのですけれど。内容のところの、特別投影の１１日日曜日の午後３時３０分からのところで、「金井三男」という、「氏」が抜けているのです。おそらくこうした文書ですから、訂正をしたほうがいいのではないでしょうかという、その指摘なのですけれど。","respondent":"鈴木文化観光課長","answer":"大変失礼いたしました。お願いする方には非常に失礼にあたりますので、申しわけございません、後ほど差し替えさせていただければと思います。","voiceIndex":120,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2760#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":51122,"voices":127}},{"id":"h28-20160822-7","meetingId":"h28-cm08","date":"2016年8月22日","dateIso":"2016-08-22","committee":"厚生委員会","time":"午後 １時００分～午後 ４時２７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２８年度 高齢者福祉行事","agenda":"平成２８年度 高齢者福祉行事","exchanges":[{"speaker":"松永委員","kind":"質問・要望","question":"そこで、この訪問事業の百歳訪問に関してですが、６日間で対象者８２人を回るということで、１００歳以上、１００歳から１０１歳以上の方についてですけれども、体調とかはどういった形になっている、訪問されたときのお相手というか、対象になっている人たちの体調はどうなのかということがありまして、自宅と指定施設の割合についても、もしわかりましたら、教えていただきたいと思います。","respondent":"大串福祉計画課長","answer":"非常にお元気な方もたくさんいらっしゃると同時に、やはり寝たきりという形で、私どものほうでご家族の方とお話はできるのですけれども、なかなかご本人の方とコミュニケーションがとれないといった状況もあったといったところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"松永委員","kind":"質問","question":"それに関して品川区としてどのようにお考えを持っているのかお伺いいたします。","respondent":"大串福祉計画課長","answer":"当然ご本人がお元気な場合であれば、ご本人のお好きなものにご利用いただければと思うんですけれども、それによりがたい場合でも、必ずしもこの方お一人だけということではなく、ご家族で長寿をお祝いしていただく。","voiceIndex":7,"id":"exchange-002"},{"speaker":"松永委員","kind":"質問","question":"ぜひご検討いただければと思います。今後、１００歳以上の人が多分１００人ぐらいずつ年々増えていくかと思うのですが、予算的には、どのような形を考えているのか、例えば、３万円と２万円の金額が変わってくるのか、今後どのような計画があるのか伺いたいと思います。","respondent":"大串福祉計画課長","answer":"今のところ、このお祝い金の金額について何らか変更するという考えは持ってございません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"松永委員","kind":"質問・要望","question":"最後に、大会関係のところで意見を言わせていただきたいのですけれども、グラウンド・ゴルフ大会は結構大勢の方がやられていて、輪投げ大会、シルバーダンスパーティーに関しても行われておりますけれども、その他、囲碁大会とマージャン大会も、きゅりあん等で行われていると思うのですが、この資料に含まれていない理由について伺いたいと思います。","respondent":"松山高齢者地域支援課長","answer":"囲碁大会につきましては中小企業センターのところで行っております。しかし、年々減少傾向にはあります。マージャン大会につきましては、区が主催というよりは、健康マージャン協会の主催で行っているものですので、ここには省かせていただいたという経緯があります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"お祝い品の事業ですけれども、実施年月日が９月１日から９月３０日までになっているということで、多分この期間に民生委員を通じて全てお渡しをするという目標で行われているかと思うのですが、民生委員もなかなか忙しい中で、大変な中、配っていただけるというのでしょうか、お渡ししていただけるということになると思うのですけれども、渡し損なうというのでしょうか、渡し切れない、また。","respondent":"大串福祉計画課長","answer":"基本、民生委員が各家庭を回っていただいて、対象の方にお渡ししていただくというのが一番理想的な形ですけれども、なかなかそれによりがたいといったところもあろうかと思いますので、そういった形で我々福祉計画のほうでは対応させていただいているという形です。","voiceIndex":13,"id":"exchange-005"},{"speaker":"浅野委員","kind":"確認","question":"やはりなかなか厳しいところもあるかと思いますけれども、やはり民生委員がこの機会を通じて高齢者の方の状況も確認できますし、そういう意味では、商品券をいただけるということで、また高齢者の方も喜んでいただけるということで、とてもいい事業だと思います。これからも継続できるように努めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私、以前に２回ほど、「日本一お年寄りにやさしいまち・日の出町」という宣言を行った日の出町に２回ほど行っていまして、いろいろお話を伺ってきたのですけれども、高齢者の医療費無料化ですとか、様々な、お祝い事業もそうなのですけれども、それから、あとは、コミュニティバスなども全部顔パスで、６５歳以上ですと顔パスで乗れるというような環境の中で、本当に高齢者が生き生きしているという。","respondent":"大串福祉計画課長","answer":"長生きをしていただく、また、住みなれた地域、住みなれた町で、ご自宅で過ごしていただくということを区のほうの基本方針としていますし、そういった中で長寿のお祝いを含めていろいろな行事等々を行い、長生きをするということに対しての尊敬と。","voiceIndex":16,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この使い勝手がすごく悪くて、住民税が基本額が課税だけでも２万５１０円払わなくてはいけないとなると、実際に本当に少額の課税者が使えないという制度になっていると思うのですけれども、そういうところでは、２万５１０円に一気に行くのではなくて、段階的にもうちょっと安い段階をつくってほしいというふうな要望というのは、区民の方からいつも聞くところなのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"前は入浴券ではなくて、木曜日は無料で入れるという、木曜日だけがというふうなことだったのですけれども、そういう形ではなくて、やっぱり行きたいときに行けるという、高齢者の主体性というか、そういう意思を尊重しながら、私はぜひ入浴券を配布ということで強く要望させていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"そういうふうに機会を捉えていろいろな方法で今やっているところですけれども、今後、高齢者の数も増えていきますので、そのやり方についても検討していきたいというふうに考えております。","voiceIndex":22,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ、私もケアマネジャーから伺ったときに、いろいろな方のケアプランをつくりながら、また相談にも乗りながら、本当に相談に乗った方がそういう悲劇を起こさないように、自分がかかわった人がそうならないようにということをいつも気をつけながら仕事をしているのですというお話も伺ったのですけれども、やはり介護というのは１人でずっと追い詰められていくというところはどうしてもあると思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-010"},{"speaker":"安藤副委員長","kind":"質問","question":"単純な疑問なのですけれども、介護度が高いご家族を見ている方ほど大変だと思うのですが、そういった方ほど激励をしたいところなのですけれども、そうした方はやはり目が離せないので、なかなかそういったところに足を運べないのではないかと思うのですけれども、そこら辺はどう考えればいいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-011"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"飲むときは大体夜だと思うのですがデイサービスは夜はやっていません。２つお伺いしたいのですけれども、こうした要望がある方はどうしたらこの要望がかなえられるのか方法があれば教えていただきたいのと、また、そういった意味から、この在宅介護者のつどいがありますけれども、在宅介護者支援をさらに充実させる必要があると思っているのですが、そこら辺はいかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"確かに夜だけ預かるというのは、なかなか難しいのかなというのが実態としてあるかと思います。","voiceIndex":29,"id":"exchange-012"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"具体的なケースはここであまり深くやることはないのですけれども、その相談を受けたとき、私はいろいろな多面的な、住みなれた自宅で、それを望んでいるし、それを中心にして頑張りたいという品川区の方針もあるので、もう少し多面的な角度から在宅介護者の方の支援を充実させていく必要があるのではないかというふうにすごく思ったので、そちらはぜひ研究していただければと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-013"}]},{"id":"topic-02","title":"品川区立戸越台複合施設の改修工事","agenda":"品川区立戸越台複合施設の改修工事","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それとももう設計の段階から入れないで、できるだけ少なくするという考え方なのか、いつからいつまで休止ということになるのかということを２点目で教えていただきたいのと、それから、短期入所者というのは、来年度に上大崎に高齢者の施設ができて、そこで３８人のショートステイができるので、そこで受け入れが可能なのかという思いがあるのですけれども、デイサービスも休止ということになると。","respondent":"永尾高齢者福祉課長","answer":"ただ、今回、２月末までの特養の申し込みのときには、こういう工事がありますということのアナウンスをした上でご希望をとって申請を受け付ける予定になっております。","voiceIndex":36,"id":"exchange-014"},{"speaker":"浅野委員","kind":"質問","question":"１点お伺いしますけれども、かなり大がかりな工事だというふうに今認識をさせていただいたところですけれども、学校、高齢者の施設もそうですけれども、高齢者の施設のほうについても同じだと思いますけれども、周りの道路は結構細くて、ちょっと坂道だったかなというふうに思うのですが、工事自体は、この敷地内で全部完結というのでしょうか、重機とかそういうものを入れて。","respondent":"永尾高齢者福祉課長","answer":"当然、建設時の記録などもございまして、工事はなかなか大きい道路にも面しておりまして大変なところもありますけれども、具体的な手法については、これから基本設計や実施設計の中で考えていきたいと考えています。","voiceIndex":38,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今回、戸越台複合施設ということなのですけれども、２０年が経過してということだと、そのほかにも次々同時期にできた特養というのもあるのかなと思うのですけれども、それでまたいろいろと、今回、電気設備、機械設備も工事、新しくしていくということなのですけれども、整備などが古いためにいろいろと低周波騒音とかのご相談も受けたりもしている部分もあるのですが、そういうことから考えると。","respondent":"永尾高齢者福祉課長","answer":"やはり今後、これを皮切りに、荏原等も出てくることは想定しております。具体的には、まだ決定している段階ではございませんが、今回この工事をやりながら、どういう手法が一番いいのかということも検証していきたいというふうに考えております。","voiceIndex":40,"id":"exchange-016"}]},{"id":"topic-03","title":"大井三丁目高齢者憩いの場の施設整備","agenda":"大井三丁目高齢者憩いの場の施設整備","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地域の区民の方から寄贈されたその思いを受けて、高齢者憩いの場とするということなのですが、この高齢者憩いの場というのは、こういう形であるというのは品川区としては初めての施設として考えていいのかということが１つと、それからあと、高齢者憩いの場というのは、何か法律的な規定というか、そういうふうなものは何かあるのかどうなのかということも教えていただきたいと思います。","respondent":"松山高齢者地域支援課長","answer":"３点目は、指定管理者ではなく委託なのかですけれども、こちらは委託で施設運営の委託として考えております。それから４点目、地域ミニデイなのですけれども、地域ミニデイの可能性ということでよろしいでしょうか。","voiceIndex":46,"id":"exchange-017"},{"speaker":"たけうち委員","kind":"質問","question":"２階に高齢者等を支援する地域ボランティアの交流の場となっているのですが、今ちょうど所管事務でやっている地域包括ケアのほうで、いろいろな協議体をこれから設置して、やっていくということですけれども、例えばそういう方たちの拠点みたいな感じのイメージもあるのかどうかということとか、その辺の関係を少し教えてください。","respondent":"松山高齢者地域支援課長","answer":"委員おっしゃられるとおり、地域包括ケアの協議体、地域の協議体の拠点になるのかというご質問でしたけれども、必ずしもここだけが拠点ということではないのですが、当然こういった地域の方々にもぜひ使っていただきたいということと、あと。","voiceIndex":50,"id":"exchange-018"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それからもう１つ別の、さっき聞けばよかったのですけれども、今、大体品川区では、新しくできたりとか、改築するような場合などは、シルバーセンターなどもそうですけれども、やはり子育てのほうとの交流みたいなものを意識されていると思うのですけれども、基本的には今後も同じような形になった場合には、そういうものを１つの原則とまでは言わないかもしれないですけれども。","respondent":"松山高齢者地域支援課長","answer":"今後につきましても、こういったような新しいところにつきましては、あまり限定的ではなく、どの世代もが使えるように幅広く柔軟に考えていきたいと考えています。","voiceIndex":52,"id":"exchange-019"},{"speaker":"安藤副委員長","kind":"質問","question":"名前なのですけれども、これ、「区立大井三丁目高齢者憩いの場」というような名前になるのか、そこら辺をお伺いしたいということが１つです。それから、２階の施設のことですが、高齢者等を支援する地域のボランティア等の交流の場とありますが、これはボランティアの、ちょっとよくわからない、イメージがつかないのですけれども、高齢者、そういったボランティアの方しか使えないということなのですか。","respondent":"松山高齢者地域支援課長","answer":"ほっとサロンにつきましても、地域の方から、ほっとサロンとしてできないかというお声もいただきましたので、こちらのほうも組み入れさせていただきました。","voiceIndex":54,"id":"exchange-020"},{"speaker":"浅野委員","kind":"質問・要望","question":"「門」と書いてあるところがあるのですけれども、出入口はここだけということなのでしょうか。左右と、あと奥のほうについては、例えば有事の際に逃げられるような、そういうような場所はあるのかないのか、この門１カ所だけですと、ちょっと奥行きがあるだけに心もとないかなという気がしますので、この点は、検討するのであれば、早めに入れていっていただければなと思いますが、いかがでしょうか。","respondent":"松山高齢者地域支援課長","answer":"３点のご質問で、道路にガードレールのところですけれども、ここにはたしかなかったかと思います。それと、もちろん工事の際には、高齢者あるいは山中小学校の近くでもありますので、子どもたちの通り道でもありますので、安全対策に十分留意して行ってまいりたいと考えています。","voiceIndex":56,"id":"exchange-021"},{"speaker":"浅野委員","kind":"質問・要望","question":"出入口１カ所ということで、ちょっとそこが気になるところですので、ほかからの指導ですとか、そういうものが入るのか入らないのか私もわかりませんけれども、ぜひとも安全に注力していただきたいと思います。それと、この図を見ると、駐車場ですとか駐輪場とかはないので、お近くの方ですから歩いてきてくださいということだと思いますけれども、その２点について教えてください。","respondent":"松山高齢者地域支援課長","answer":"委員ご指摘のとおり、駐車場等はありませんので、やはり自力で歩いてこられる方が集う場所ということに設定いたしました。","voiceIndex":58,"id":"exchange-022"}]},{"id":"topic-04","title":"ジカ熱などの感染症対策に向けた蚊防除事業","agenda":"ジカ熱などの感染症対策に向けた蚊防除事業","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それからあと、蚊がどれくらいの地域というか、どれくらい飛ぶのかというのがよくわからないのですけれども、これは品川区独自のものなのか、それとも全都でやっているということなのか、東京オリンピックに向けてということであれば、４年後までにはほとんど蚊がいないという状況にまで持っていこうという東京都全体の取り組みなのか、そのことについてもお聞かせください。","respondent":"井浦生活衛生課長","answer":"品川区での取り組みは、先ほど見ていただいたように効果が出ているところですが、２３区の中ではほとんどの区が実施しています。","voiceIndex":64,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２３区の中でほとんどの区がやっているということであれば、東京オリンピックということなので、全都でやるということで、東京都が音頭をとって本当に全都でやるような方向というのは求められないのか、そのことだけ教えてください。","respondent":"井浦生活衛生課長","answer":"東京都からも情報提供がありますので、それぞれの区で地域の状況に則して判断しているところだというふうに理解しています。","voiceIndex":66,"id":"exchange-024"},{"speaker":"たけうち委員","kind":"質問","question":"この対象の保育園、幼稚園については、区立だけなのか、私立も含めてなのかというのが１つです。それから考えているのかどうか、その辺を教えてください。","respondent":"井浦生活衛生課長","answer":"ちなみに、小中学校は教育委員会で同じような事業を同時に行っているところです。私道につきましては、やはり薬剤散布ですので、私道の権利者の許可という形で権利関係というところもあります。私道もかなりの面積がありますので、今後の課題というところで考えてあります。","voiceIndex":68,"id":"exchange-025"},{"speaker":"たけうち委員","kind":"質問","question":"昔、毛虫をやるので、夏の時期に町会参加で消毒をやっていましたね。その後、それができなくなると、今度は配ったりしていたと思うのだけれども、このお薬が高ければあまりそうもいかないのかもしれないが、その辺の兼ね合いと、検討するということなのだけれども、それが実現がどの程度可能なのかということも、ニュアンス的にちょっと教えてください。","respondent":"井浦生活衛生課長","answer":"サンプルとして区の生活衛生課に薬剤がありますので、サンプルという形ではこれまでも提供しています。ちなみに、１粒で１カ月ぐらい効きまして、１粒１６円程度の原価です。〔「早速もらいに行こう。","voiceIndex":70,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これは区立公園と書いてあるのですけれども、林試の森は都立公園ではなかったでしたか。林試の森。あそこも結構子どもたちがよく遊びに行って、池とかもありますし、すごく蚊が発生しそうな感じの場所だと思うのですけれども、区立公園以外のところでの都立公園、そちらの対策はどうなっているのか聞かせてください。","respondent":"井浦生活衛生課長","answer":"現在まではウイルスを持っている蚊はゼロですが、その雨水ます等の対応については、厚労省も提唱していますので、都立公園については、私ども、東京都とお話ししていきたいというふうに考えてあります。","voiceIndex":72,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういう点では、東京都も、東京都主催と言ってもいいくらいのオリンピックにもなっていきますし、区任せではなくて、やはり東京都が責任を持ってそういうふうなところをやるようにということで、都立公園から全都というところでの働きかけを区のほうからもぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-028"}]},{"id":"topic-05","title":"Ｂ型肝炎ワクチンの予防接種","agenda":"Ｂ型肝炎ワクチンの予防接種","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"任意から定期予防接種になって負担なく予防接種を受けられるようになって、本当によかったなというふうに思っています。今まで品川区は、平成２６年度から一部助成を行ってきたということですが、今までの接種率というのはどれくらいの子どもが接種してきているのかわかると思うのですけれども、それを１つ教えていただきたいと思います。","respondent":"舟木保健予防課長","answer":"今も実施していますが、任意予防接種の接種率ですが、平成２６年は８,５７３件接種しております。対象者として計算しますと、大体８割以上の方が接種していることになります。","voiceIndex":79,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"済みません、私、定期接種というのは国から財源が来るのかと思っていたのですけれども、それは全く来なくて、区の一般財源ということなのかを改めて、基本的なことで済みません、教えてください。","respondent":"舟木保健予防課長","answer":"国の予防接種につきましては、接種費用については地方交付税措置となっているのですが、東京都については不交付団体ということで交付されておりません。なので、一般財源での対応となるため、定期接種化することについて、２３区については負担が逆に増えることになります。","voiceIndex":81,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"わかりました。この１回の費用というのは、今までは３,０００円かかったうちの３,０００円丸々区が補助していたということだったのでしょうか。今回の実際３回をやるに当たり、１回の接種費用というのは幾らになるのかということをもう１回教えてください。","respondent":"舟木保健予防課長","answer":"今回、定期接種化するに当たりまして、２３区乗り入れで実施いたしますので、東京都と東京都医師会と２３区のほうで、三者協という協議会で単価を協議いたしまして、単価は共通単価となっております。","voiceIndex":83,"id":"exchange-031"},{"speaker":"たけうち委員","kind":"質問","question":"２ページ目のところで、この訪問型サービスの予防訪問事業等があります。それで、まずこれの利用料というのですか、介護保険の関係なので、基本１割負担なのか、そこをまず教えてください。","respondent":"松山高齢者地域支援課長","answer":"そうですね、こちらの予防訪問事業と通所事業、こちらの６つにつきましては、すけっとと地域ミニデイを除く、一般介護予防事業を除いたものについては、利用料は自己負担１割です。介護保険法にのっとっております。","voiceIndex":90,"id":"exchange-032"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。それから、このすけっとサービスモデル事業の中で、サービス提供者が社協のさわやかサービスの協力員になっていますけれども、今、通常の方は８００円でしたか、７００円でしたかになっていますけれども、そこの考え方も含めてあわせて教えてください。","respondent":"松山高齢者地域支援課長","answer":"平成２８年度からのモデル事業につきましては、有償ボランティアというところで、もちろん個人情報保護ですとか、高齢者の支援の仕方について研修を終えた方々、有償ボランティアが担い手として提供する形になっておりますので、それぞれ同じ、例えば家事１つとっても、では。","voiceIndex":92,"id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そうすると、今、この９月から始まるすけっとサービスモデル事業は、予防訪問事業、生活機能向上支援訪問事業、この利用者を除くとなっていますけれども、いわゆる両方やる意味がないのでということで、今現在、総合事業のほうで、例えば掃除とか買い物だけが必要な方は、希望すれば、９月以降は、もしくは来年度からは、このすけっとサービスのほうに。","respondent":"松山高齢者地域支援課長","answer":"それから２点目、さわやかサービスの協力員なのですが、特に減らすということはございませんので、今と同じということで社会福祉協議会のほうから聞いております。","voiceIndex":94,"id":"exchange-034"},{"speaker":"たけうち委員","kind":"質問","question":"１点目のほうです。専門的な目で見て必要なサービスをやる。それはわかりました。それはもう固定化されてしまっているのか、それとも、それは違うのだということなのか、そこを教えてください。","respondent":"松山高齢者地域支援課長","answer":"確かに専門家が見て、その方がこのサービスが必要だということであれば、移行していくということはあり得ます。","voiceIndex":96,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここの緩和がされているかどうかを改めて確認をさせていただきたいと思います。とりあえずまずそこのところを教えてください。","respondent":"松山高齢者地域支援課長","answer":"１点目が試算、総合事業を導入したことによる試算をしているのかというところですけれども、試算につきましては、やはり担い手の確保をしないと、こればかりは区が住民のサービス、住民によるものを進めますと言っても、サービスができなければというところがありますので。","voiceIndex":98,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、このいきいき活動支援プログラムを使えれば、もともとの介護報酬よりも若干高いというふうな形になるのですけれども、これが使えないとかなり下がってしまうということになると思うのですが、４２事業者がこのいきいき活動支援プログラムを活用しているということなのですけれども、これは母数は何事業者になるのか、４２事業者というのは区内事業者なのか。","respondent":"松山高齢者地域支援課長","answer":"予防訪問事業と生活機能向上支援訪問事業の内訳ですが、こちらのほう、なかなか分けるのが難しいので合わせてという形、こちらはシステムのほうから国保連の請求データによるものなのですけれども、こちらのほうで合わせて１,２９１人という実績状況を出させていただきました。","voiceIndex":100,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"わかりました。それでもう本当に品川区に見捨てられたような思いだというふうな、率直な声も伺っているのですけれども、私は改めてこの総合事業を平成２７年から１年半ぐらいやってきて、実際の事業所の経営ですとか、利益ですとか、利用者の状況ですとか、そういうところを改めて検証することが必要なのではないかなというふうに思っているのですけれども、いかがでしょうか。","respondent":"松山高齢者地域支援課長","answer":"したがいまして、いきいき活動支援プログラムがとれない事業者はありませんので、そちらのほうを工夫していただきたいと考えています。検証につきましては、こちらの介護保険会計ですので、３年ごとの介護保険事業計画の中で検証していきたいと考えております。","voiceIndex":102,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いろいろあるので続けてお聞かせいただきたいのが、黄緑色のところの一番下のところで、主な一般介護予防事業ということで、これは介護保険の認定だったりとか、総合事業対象ということは必要のない、ケアプランも必要のないところで利用できるというものだと思うのですけれども、もともとは一般財源でやっていたものが、総合事業で介護保険の。","respondent":"松山高齢者地域支援課長、永尾高齢者福祉課長","answer":"２点ご質問いただきました。事業者に決める際に、要は、全事業者の声を聞いたのかというようなお話でしたけれども、全事業者対象にアンケートをとっております。介護保険会計全体の話なので、私のほうから説明をいたします。一般介護予防事業ですけれども、平成１８年から予防ができたときに、国のほうで介護保険の対応になりました。","voiceIndex":104,"id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ということは、これが全て一般財源で行っていたということで捉えていいのかということを確認させていただきたいと思います。","respondent":"永尾高齢者福祉課長、松山高齢者地域支援課長","answer":"これについても、区が全額単費ではなくて、東京都の補助金の２分の１、包括補助の２分の１を活用して実施しているものです。平成２７年度から総合事業が始まりました。平成２７年度については１６.９％ということで、０.２ポイント下がったという結果になりますので、この下がった部分の方についてが基本チェックリストのみの方と考えられると予想されます。","voiceIndex":107,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は認定をとにかく保障してほしいということで何度も求めて、それで全ての方々に認定は受けられますよということは、在支のほうでも説明はしていますよという、そういうことは伺っているのですけれども、そういう中でも、認定を受けないでデイサービスと訪問介護のほうにサービスが振り分けられていくという人がどれくらいいるかというのは、やはりこの総合事業の大きな改変の１つなので。","respondent":"松山高齢者地域支援課長","answer":"こちら、確かに人材を何人ぐらい養成すればいいのかというところにつきましては、今後、この総合事業の背景の一番最初にご説明の中で申し上げた人材の確保と費用、介護給付費というのは大きな二本柱ですので、人材をどの程度確保すれば。","voiceIndex":110,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今までもこのさわやかサービスというのは、介護保険以外の部分で自費料金の発生ということで受け持っていたと思うのですけれども、それ以外のところでの新たな余力というのですか、新たにすけっとサービス事業をやるに当たっての登録者という、そういうふうなものがつくられて、さらにこれをもっともっと区としては、今回はモデル事業で、どれぐらいの対象で、どれぐらいの、２５０人の登録者で。","respondent":"松山高齢者地域支援課長","answer":"その中でも、やはり定期的に働きたい人、あるいは逆に自分のフリーでいきたい人、多様な人材がおりますので、そういったマッチングも踏まえて、今後検討していきたいと考えています。","voiceIndex":112,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"最後に、一番最後の協議体の設置ということなのですけれども、今、介護の問題では、介護制度推進委員会があって、傍聴も可能なのですけれども、平成２８年４月から、区に１つ協議体が設置されて、これが位置づけられていくということなのですけれども、その会議はどれぐらいの頻度で行われているのか、また、傍聴なども可能なのか、具体的にどういう方が会議のメンバーなのか、改めてお聞かせください。","respondent":"松山高齢者地域支援課長","answer":"頻度につきましては、まだ４月からということなので、委員の方々にはこういう説明をしたところです。それから、地域の支え合い活動会議につきましては、それぞれ地区ごとに、本当に地域の皆様の活動に基づいて行っておりますので、頻度については地区ごとに異なっております。","voiceIndex":115,"id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"様々な分野からの方々が出られて、介護制度推進委員会に出られている方々ともダブる部分もあるのかなと思ったのですけれども、介護制度推進委員会は傍聴が可能で、介護保険がどういうふうに運営されているかというふうなところが区民も傍聴できるようになっているのですけれども、これもぜひ傍聴ができるようにしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"松山高齢者地域支援課長","answer":"こちらの会議体なのですけれども、やはり地域の方々が一番中心になってあります。こちらの会議体の主な目的は、定期的な地域の情報共有ということと、その方々の連携強化ということになっておりますので、何かそこで政策を決めるということではありません。","voiceIndex":117,"id":"exchange-044"},{"speaker":"安藤副委員長","kind":"質問","question":"実施時間が９時から１７時だったのが、今回１８時ということで、微妙に変わっているのですけれども、それはどんな経過があったのかということが１点です。通所型サービスの６５とか４２事業所という数がありますけれども、この５８とか６５というのは、この１年間、例えば介護報酬単価が下がってしまったことで閉所せざるを得なくなったとか、数字の変化はあるのかどうか、それもあわせて伺います。","respondent":"松山高齢者地域支援課長","answer":"それから３点目に、費用によって事業所の廃業の実績があるのか、要は、費用が下がったことで事業所を廃業したところがあるのかというお尋ねですけれども、そのような事業所はございません。","voiceIndex":119,"id":"exchange-045"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"ですから、改めて、１年間たったということで、先ほど、全事業者の実態をつかむ必要があるのだという意見もありましたけれども、全事業者にアンケートを実施して、苦しい現状があるのか、あるいは何かご意見があるのか、どんないきいき活動支援プログラムをしているのかなど、そういうものもぜひつかんでいただきたいと思うのですけれども、ぜひ求めたいのですが、いかかでしょうかということが２点目です。","respondent":"松山高齢者地域支援課長","answer":"それが入浴サービスや送迎サービスを使っていない方についても込みで介護報酬が計算されていたので、それが課題であったというふうに認識をしております。費用の設定につきましては、事業者の安定した継続の経営とともに、課題の解決というのを今回取り組んでまいりました。","voiceIndex":121,"id":"exchange-046"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"それとあわせて、先ほどもちょっと要望したのですが、改めてそうした実態があるということは私もつかみました。全事業者にこの時点で、とにかく１年たったわけですから、実施前のアンケートはしたみたいですけれども、ぜひそうした実態をつかむアンケートを実施していただきたいと改めて思うのですけれども、そちらも答弁をお願いします。","respondent":"松山高齢者地域支援課長","answer":"かなりの事業者から、いきいき活動支援プログラムを行うことで、自立支援について、改めて事業者として見直すいいきっかけになったという声をいただいておりますので、特にアンケートについては今のところは考えておりません。","voiceIndex":123,"id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3454#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":57320,"voices":130}},{"id":"h28-20160822-8","meetingId":"h28-cm08","date":"2016年8月22日","dateIso":"2016-08-22","committee":"建設委員会","time":"午後 １時００分～午後 ２時５３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"区民住宅（空き室）入居予定者登録募集","agenda":"区民住宅（空き室）入居予定者登録募集","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今の説明で、空き室が出た場合の順番を抽選で決めるということだと思うのですけれども、この資料にあるファミーユ下神明とファミーユ西五反田西館・東館の空き室は、もう出ているということでいいですか。","respondent":"今井住宅課長","answer":"これらの空き室につきましては、７月末日現在ですけれども、ファミーユ下神明、西五反田西館・東館とも空き室はあります。","voiceIndex":7,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、下神明と西五反田西館・東館の抽選と、ほかにもそれまでに出たら、抽選する対象の空き室になるということなのでしょうか。","respondent":"今井住宅課長","answer":"そちらの入居予定者の登録募集も完了いたしまして、現在、逆に申込みがなかった住宅については随時募集という形になっております。今回につきましては、ここに記載しております３棟につきましての入居予定者の登録の順番を決めるものです。","voiceIndex":9,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、この３棟の空き室が今の時点で幾つあるのかというのは、いつも大体募集が始まってからということで、区営住宅とかはなかなかこの場では言えないと言われているのですけれども、これも幾つ空き室があるのかは、どうでしょうか。","respondent":"今井住宅課長","answer":"ただ、こちらにつきましても、昨年度同じように登録募集をしておりましたので、その登録募集の方が随時、入居の審査をしている段階ですので、この空き室自体がぎりぎり、こちらの空き室募集の期限が１０月ぐらいになりますので、１年の切替えのときまでに決まるかもしれないので。","voiceIndex":11,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"区民住宅はいずれにしても契約が切れるという形になるのですが、今回のこのファミーユ３軒については、いつまでの期限があるのでしょうか。","respondent":"今井住宅課長","answer":"ですので、委員ご指摘の契約が切れるというのは、民間借上げ型の区民住宅だと思いますが、そちらにつきましては現在も６棟ございまして、今後、平成３１年度までに契約の終了を予定しております。","voiceIndex":13,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"建設型の場合にも、この仕組みというのはずっと続くという認識ですか。それとも、区民住宅そのものについての考え方を、借上げ型という形ですと当然平成３１年までに終了となりますので、そうなりますと、こちらの建設型についてはどういうふうに変わってくるのでしょうか。","respondent":"今井住宅課長","answer":"建設型については今、８棟ございまして、こちらにつきましては約７５０戸持ってございまして、こちらの状況につきましては、空き室の状況等を含めながら今後検討していくものですが、あくまでも建設型につきましては区が建設したものですので。","voiceIndex":15,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"これは多分、区民住宅を今後どうしていくのかという話になると思うのです。そういう説明は、どういう時期にどういう形で告知をして、入居募集をされるのかという目途みたいなものはあるのでしょうか。","respondent":"今井住宅課長","answer":"ただ、借上げ型区民住宅についてはそれぞれ借上げの満了期がありますので、２年前ぐらいから区民の方、入居者の方に周知をして、２年前、１年前、そして６ヶ月という形で品川区からも周知いたしますし、新しいオーナーになります借上げ型のオーナーの方々も。","voiceIndex":17,"id":"exchange-006"}]},{"id":"topic-02","title":"品川区立区民住宅ファミーユ大井における漏水事故に係る滞納使用料、各損害賠償請求控訴事件","agenda":"品川区立区民住宅ファミーユ大井における漏水事故に係る滞納使用料、各損害賠償請求控訴事件","exchanges":[{"speaker":"鈴木（真）委員","kind":"確認","question":"前回ご説明を受けたのが、そのままになったということで、もう内容はわかりました。裏面の判決の(2)は、被控訴人の「被」が要らないのではないかと、その点を確認させてください。","respondent":"今井住宅課長","answer":"大変失礼いたしました。被控訴人ではなくて、控訴人の間違いです。","voiceIndex":23,"id":"exchange-007"}]},{"id":"topic-03","title":"しながわ水族館開館２５周年記念事業","agenda":"しながわ水族館開館２５周年記念事業","exchanges":[{"speaker":"塚本委員","kind":"確認","question":"イルカとふれあいステージの整備ということで、写真で提示されていますけれども、これはサブプールではなくて、イルカプールのほうでということですよね。いわゆる演目の中でこういうコーナーを設けるということなのか、常時やれるようなイベントなのかというのを確認したいのですけれども。","respondent":"溝口公園課長","answer":"今回初めての取組みになりますので、１日５名程度でまず始めて、イルカの様子を見ながら順次拡大していきたいと考えているものです。","voiceIndex":29,"id":"exchange-008"},{"speaker":"塚本委員","kind":"確認","question":"サブプールということで、来館者が自由にそこに入ってということだったと思うのですけれども、当然誰か係員のような人がつくのかということと、基本的には、そういうことでは開館していればいつでもということでやる設備というか、このステージを整備するということで、再度確認させてください。","respondent":"溝口公園課長","answer":"説明が悪くて申し訳ありません。基本的にこういうイルカと触れ合える場合、イルカに噛まれるとか、そういった危険性もありますので、必ず係員立ち会いのもと、行うようになっているものです。","voiceIndex":31,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"２５周年イベントと、１番と２番で違うのかなと思うのですが、コスト、経費はどのぐらいを想定しているのかということで、それと、２５周年ということなので、ＰＲがすごく重要だと思うのですが、ＰＲはどう考えられているのか教えてください。","respondent":"溝口公園課長","answer":"今回のイベントの経費ですが、区で１,０００万円、水族館でも１,０００万円、合わせて２,０００万円ほどの費用をかけて記念イベントというのをやっていきたいと考えているものです。","voiceIndex":33,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"ＰＲについては本当に大々的にやっていいと思いますし、しながわ水族館という意味でのＰＲポイント、例えばイルカと触れ合うという形、そういうイメージアップを図るのも、表に出してＰＲをしていく。２５周年記念だけではなくて、しながわ水族館とはこういうものというのが前面に出せると、もっと周知といいますか、ほかのところと差別化が図れるのではないかなと思うのですが、いかがでしょうか。","respondent":"溝口公園課長","answer":"ＰＲにつきましては引き続き、他の館と差別化が図れるように、水族館とともに検討しながら進めていきたいと考えているものです。","voiceIndex":35,"id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明ありがとうございました。それと、プロデュース水槽の展示で期間がありますけれども、プロデュース水槽の展示の中で３期間に分けた展示ということで、これがアイドル、俳優、お笑い芸人、それぞれ１名ずつなのか、その辺のことを教えていただきたいと思います。","respondent":"溝口公園課長","answer":"それぞれ期間といたしましては、９月１７日から１１月２６日、長い期間になりますが、９月１７日から１０月１４日までをカントリー・ガールズ、１０月１５日から１１月５日を杉浦さん、その後１１月６日から１１月２６日までをアンタッチャブルの柴田さん。","voiceIndex":37,"id":"exchange-012"},{"speaker":"筒井委員","kind":"確認","question":"確認ですけれども、それは区の予算ですね、区が全部出すということですね。","respondent":"溝口公園課長","answer":"今回、ふれあいステージにつきましては、ソフト的な部分もありますが、本体の躯体をいじる工事になりますので、区で予算化をして整備をするという形になるものです。","voiceIndex":41,"id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"２５周年記念ということですけれども、イベントはそれぞれ、あったらいいなと思う夢の水槽とか、こういった有名人を呼んでという形をとられたわけといいますか、ほかのどこかを参考にしたのか、それとも区民からそういう声があったりしたのか、これになった理由を伺いたいと思います。","respondent":"溝口公園課長","answer":"ちょうど四半世紀経ちますので、そういったところを含めて、さらにもう一度区民の方に親しんでいただける水族館を目指して、区民の方の新たなアイデアといったものを募って、さらに集館、また区民に今後も親しまれる水族館を目指していきたいということで。","voiceIndex":43,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。２５周年記念事業の中ですけれども、そのまま続くのですか。","respondent":"溝口公園課長","answer":"今回、イルカとふれあいステージは、新たに１,５００万円かけて整備するものですので、今後水族館は新たにこういったイベントというのをしっかり続けていきたいと考えていますし、初めのうちはイルカの様子を見ながらという形にはなりますが、できる限り回数を増やして。","voiceIndex":45,"id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"意見","question":"それで、そういったときの写真撮影とか、そういったオプションのようなものもある形に、今後検討とかをされるのかどうか。","respondent":"溝口公園課長","answer":"基本的には、写真撮影については個人のカメラでというのを想定しているものです。","voiceIndex":47,"id":"exchange-016"}]},{"id":"topic-04","title":"地区総合防災訓練の実施","agenda":"地区総合防災訓練の実施","exchanges":[{"speaker":"西本委員","kind":"質問","question":"下のほうに児童センターが参加する予定ということですが、これは今までなかったのでしょうか。それのご紹介をお願いしたいと思います。それと、この中に、せっかく防災センターが新しくなったので、それもうまくＰＲができるといいなと思っているのですが、何か方法がありますでしょうか。","respondent":"黒崎防災安全担当課長","answer":"本年度もさらに増えるように頑張ってまいりたいと思います。しながわ防災体験館の防災センターのリニューアルした件ですけれども、区の各訓練会場に広報ブースなどをつくりますので、そこを通じて、訓練の実施とあわせて、各利用についても広報してまいりたいと思います。","voiceIndex":53,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"児童センターの実績が１１６名ということですが、どういう方が参加されて、どういう指示で児童センターが関与するという形になっているのでしょうか。参加されている内容ですね。職員だけだとそんなにならないと思うのですけれども、いろいろな地域の方に広めていく感じなのだろうと思うのですが、児童センターの参加という意味というのは、どういう考え方で行われているのでしょうか。","respondent":"黒崎防災安全担当課長","answer":"児童センターの参加につきましては、そちらに通われているお子さんとその親御さんということで声をかけしています。若い世代の親御さんの参加を促進するという意味での取組みです。","voiceIndex":55,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"児童センターの利用の中に、赤ちゃんクラブとかいろいろありますよね。ばらばらでやるよりは、共同して何か地域の中で展開するというものがあると、もう少し町会に関わるというのも出てくるだろうし、いろいろなことが考えられると思うのですが、そこら辺は調整を図りはしていないのでしょうか、いかがでしょうか。","respondent":"黒崎防災安全担当課長","answer":"そこの中で、区の防災の各地区の担当者もかかわりながら調整をしていますが、今後は、各地区によって多少ばらつきもありますので、そこは統一された調整がなされるようにこれから研究をし、広報につなげていきたいと考えています。","voiceIndex":57,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"これはとてもいいテーマの一つだと思うのです。もしくは、地域の子育てに関する方々へのアプローチだったり、安全安心という意味での訓練なども積極的にできる状況になるのではないかなと思うので、今後の課題になると思いますが、町会との関係と防災というキーワードに、ぜひいろいろ試行錯誤して考えていただきたいなと思いますので、意見としてよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-020"},{"speaker":"筒井委員","kind":"意見","question":"この紙の下のほうで、大崎第一地区については区内在住外国人が参加予定と書いてあるのですけれども、なぜ大崎第一地区はこのようなことになったのかという理由と、ほかの地区ではなぜやらないのかという理由をお聞かせください。","respondent":"黒崎防災安全担当課長","answer":"ただいまの外国人の参加の件につきましてですが、当初、この地区の総合防災訓練という考え方が出てきたときに、各地区で広報しながわ等で外国人の方への呼びかけ等も行っていたのですが、現在のところ参加人数がまだ少ないということと。","voiceIndex":60,"id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"それは、大崎第一地区が通訳とか、そうしたことが可能な態勢が整っているからという理由ですか。","respondent":"黒崎防災安全担当課長","answer":"こちらも理由がございまして、大崎第一地区には大使館が多いという理由で、こちらを中心に呼びかけをさせていただき、この会場を使っているです。","voiceIndex":62,"id":"exchange-022"},{"speaker":"筒井委員","kind":"意見","question":"ほかの地区についてはまだ区内在住外国人の方が参加される予定はないということで、予定と言いますか、大使館があるという地域需要はあると思うのですけれども、今後はどういうお考えなのかお聞かせください。","respondent":"黒崎防災安全担当課長","answer":"説明がうまくなくて申し訳ございません。昨年もそうですけれども、各地区にそれぞれ呼びかけはしています。","voiceIndex":64,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"医師・薬剤師の参加ということがあったと思うのですけれども、医師・薬剤師の皆さんはどのような形でやられるのか、伺いたいと思います。","respondent":"黒崎防災安全担当課長","answer":"医師等の医療関係者の参加ですけれども、品川区から医師会へ参加の呼びかけをさせていただいておりまして、これはまた先の実績になりますけれども、各地区に１名もしくは２名の医師もしくは看護師の方々の参加をいただいております。","voiceIndex":68,"id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"確認","question":"各地区に配置してやられると。それで、こうした取組み、１１カ所でやられるのですけれども、それはその後、報告とかはどこか区民の見える形でされるのか確認をしたいのですが。訓練のその後の、こういう訓練でしたとか、困難もあったり、こういうことが学べたとか、そういったことが、区民が見られる形で出されるようなことがあるのですか。不勉強ですみません。","respondent":"黒崎防災安全担当課長","answer":"各地区で実施された内容につきましては、実施結果ということで、区で取りまとめさせていただきまして、例年冬、２月頃に行いますけれども、防災協議会の総会でその内容を発表し、資料をお持ち帰りいただいているです。","voiceIndex":70,"id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、区民が見られる形、防災協議会のところでという話だったのですけれども、あまり参加ができなかったり、または知らなかったりする区民が、こういったことを毎年地域でやっているということが、そして皆さんそれぞれ頑張られているというのがわかる形にはなっていないということですか。","respondent":"安井土木管理課長","answer":"これは地区の防災協議会がやっている事業でありますけれども、その事務局は地域センターです。地域センターも地区ごとにニュースを発行しておりまして、毎年この防災訓練の内容であるとか、そういったものを発表して十分周知を図るということで、宣伝は行っておられます。","voiceIndex":72,"id":"exchange-026"}]},{"id":"topic-05","title":"本日は、舟運の災害対策における活用の概要として、区内の桟橋等の現状や東京都の各種計画、および民間事業者等との協定締結の状況など","agenda":"本日は、舟運の災害対策における活用の概要として、区内の桟橋等の現状や東京都の各種計画、および民間事業者等との協定締結の状況など","exchanges":[{"speaker":"西本委員","kind":"質問","question":"実際、桟橋の指定をするのを、それぞれの考え方によって指定をされて、これからいろいろと整備されるのかなと思うのですが、この違いはどう考えたらいいのかなということです。それぞれが同時にやろうとやっていくのか、その上で品川区の地域防災計画の中で、水上輸送計画というのをつくるということですが、どれをもって、どういう考え方で、当面いくと考えられているのかを教えてください。","respondent":"和田河川下水道課長","answer":"建設局と港湾局の考え方が違う理由ですけれども、建設局は河川内の防災船着場について、港湾局は東京港、海の防災船着場について、考え方をまとめたものでございまして、その配置の考え方については当然、河川と海では考え方が変わりますが。","voiceIndex":78,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"品川区は品川区の中で、桟橋の使い方とか整備、例えば東京都ではこう考えるけれども、品川区としてはここがいいのではないかといったことが出てきた場合の協議というのは、あるのかないのか。あくまでも東京都が言われているものをそのままやるわけではないと思うのですが、品川区はどういう考え方のもとで整備をしようとされているのかを教えてください。","respondent":"和田河川下水道課長","answer":"品川区はどのように計画をつくっていくかということですけれども、当然この運用マニュアルに沿った形でやっていくということになるかと思います。この運用マニュアルの策定につきましては、現在検討会が東京都で立ち上がっておりまして、品川区としても委員として参画しています。","voiceIndex":80,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"わかりました。大きな目で見る部分と、私たち品川区というのを中心で見ていく場合では、やはりずれが出てくる可能性がありますので、そこをきちんとお伝えいただきたいと思います。それと、民間の方々との協定がいろいろありますけれども、今は２社、船清と寺田倉庫ですが、今後は増やしていくということは考えられているのでしょうか。","respondent":"古巻防災課長","answer":"協定に関しましては今、先方からのお申し出ということで結んでいる部分がありますので、具体的にまだ広げていくということでは進んではおりません。","voiceIndex":82,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"船清だけではなくて、ほかのところもたくさんあると思うのですが、そこら辺を皆さんに、計画の中に、有効活用という形の中でご理解を求めるということもあっていいのかなと思うのですが、それは個々、言ってきた方々に対して協定を結んでいくのか、それともこちらからで、こういう形で使っていきたいという考えを品川区として示していく方向なのか、どちらなのでしょうか。","respondent":"古巻防災課長","answer":"計画に関しましては今、河川下水道課長からもご説明したとおり、今後東京都の計画に基づいて進めていきますので、その中でどういう形が望ましいのかということを研究しながら進めてまいりたいと思います。","voiceIndex":84,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"ただ単に桟橋があればいいというのではなくて、もちろんそれを運用しなければいけなくなってくるので、運用するときに、ではどういう区とのかかわり合いがあるか、事業者のほうがわりあい事情を知った上で臨機応変にやってくれるということも出てくるのではないかなと思うのですが、もう少し研究していただいて、民間に協力をいただくという軸をつくってもいいのではないかなと思うのですが。","respondent":"古巻防災課長","answer":"繰り返しになりますけれども、これからの計画ですので、今委員からご指摘いただいた点を含めまして、どういった形で計画に入れていくのかということを検討してまいりたいと思います。","voiceIndex":86,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"地域の需要をよくわかっているとか、あとは陸内の、災害時がどういうふうになったときに、こういうところでこういう資源があるので、それをうまく使っていきましょうといったことは、品川区の中できちんとつくっていく必要があるし、つくれる話だと思うので、今後の検討の中に、ぜひそういうソフト面のところについてもいろいろ検討していただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-032"},{"speaker":"筒井委員","kind":"確認","question":"確認になるかもしれないのですけれども、ということは、品川区の「地震時における水上輸送計画（仮称）」というのは、東京都の運用マニュアルができてからだと思うのですけれども、何年策定を目途としているのか、その点をお教えください。","respondent":"古巻防災課長","answer":"具体的なスケジュールについてはまだこれからという形で、都の進捗状況を見据えながら検討してまいりたいと考えているところです。","voiceIndex":90,"id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"区としては、こうした幾つもある民間の桟橋を災害時に使えるように、協定を結んでいこうという姿勢なのかどうかを伺いたいです。","respondent":"古巻防災課長","answer":"先ほども少しお話ししていますけれども、今後計画を策定していくという中で、どういった形で桟橋を活用していくのかということも出てまいると思いますので、そういった中で、協定の必要性についても検討してまいりたいと考えているところです。","voiceIndex":94,"id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"計画が出てからというところもあると思うのですけれども、その以前に、区としての防災への姿勢というところでは、そうした積極的な姿勢をもって進めていただけたらと思います。それと、寺田倉庫のところの桟橋というのは、民間でいうと、船清は船清と名前がついているのですけれども、寺田倉庫はどこになるのですか。","respondent":"和田河川下水道課長","answer":"１ページ目の10)です。ウォーターライン１というものが寺田倉庫の桟橋です。","voiceIndex":96,"id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、ウォーターライン２も一緒に締結しているということでしょうか。","respondent":"和田河川下水道課長","answer":"１１ページをご覧いただきまして、ウォーターライン２の施設も一時滞在施設として、当然ながら入ってありますので、ウォーターライン２も桟橋としては協定の対応に含まれてあります。","voiceIndex":98,"id":"exchange-036"},{"speaker":"塚本委員","kind":"質問・要望","question":"災害時ということであるので、災害対応に寄与するものであれば、品川区はこう使いたい、こういう船を留めさせたいと言えば、そういうふうに基本的には考えられるのか。個別具体的な話は、私も不勉強で指摘できないのですけれども、まずその辺の状況というのを教えていただきたいと思います。","respondent":"和田河川下水道課長","answer":"やはり総合防災部が、どの桟橋をどう使うかというのは、上からといいますか、都からおりてきて、その使用方法に従って区が運用するのか、都や国が使うのかということが決められていくというものですので、現状の素案ではないになっていますけれども、委員ご指摘のとおり。","voiceIndex":100,"id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"１つは区から、もちろん検討の中でやっていくというところなのでしょうけれども、今の自由度みたいなところで、法的なとか、条例的なものの改正とかということにかかわるところというのは、何かあるのでしょうか。","respondent":"和田河川下水道課長","answer":"今のところ、私が認識している限りではございません。","voiceIndex":102,"id":"exchange-038"},{"speaker":"塚本委員","kind":"質問・要望","question":"ここに一応、啓開道路の近くに、緊急時は使いたいというところは患者の輸送など出ていますけれども、こういったところから、品川区として、区の地域防災計画としてこの辺が一番大事なのではないかなという視点はどこか、教えていただきたいと思います。","respondent":"和田河川下水道課長","answer":"ただ、運用の方法の中身ですかね、東京都が勝手に我々の管轄の桟橋を使うというよりは、我々に意見を求めて、我々の許可のもとに使っていただくとか、そういうのは運用の内容の中で、我々の意見が反映できるような使い方ということを。","voiceIndex":104,"id":"exchange-039"},{"speaker":"塚本委員","kind":"質問","question":"最初にこの資料を読んでいたときにはいろいろと、こんなことも、あんなこともというのがあるのかなと思いましたけれども、そういう中ではこの船清とか寺田倉庫とか民間との協定を結んでいく中で、そういうことが品川区にとって、より働くといいますか、東京都とのいろいろなことが起きてくるに当たって有利に働くというか、大いに活躍していただく中で、品川区の災害対応において。","respondent":"和田河川下水道課長","answer":"したがいまして、こういう指定されていない桟橋の中で、品川区としてどのように使っていくのかという視点も、今後必要なのかなと考えております。","voiceIndex":106,"id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"確認","question":"例えば別の、１ページ目の資料でいきますと、勝島運河内というところがありますよね、この辺の折衝というのはどうなっているのかなという部分の確認をしたい。勝島運河は殊に品川区が結構負担して桟橋をつくったのではなかったかと、違ったらあれですけれども、自分の記憶ではたしか、整備したときかなり負担したのではないかと思ったので、そこら辺はいかがでしょうか。","respondent":"和田河川下水道課長","answer":"逆に言いますと、品川区としてこの勝島運河内の桟橋を協定で結ぼうとかという動きは、現在のところしていないという状況です。","voiceIndex":108,"id":"exchange-041"},{"speaker":"鈴木（真）委員","kind":"質問","question":"東京都と結んでいるということで、そうすると品川区としては動きがとりようがないという感じになるということでしょうか。","respondent":"和田河川下水道課長","answer":"そうですね、東京都との締結をしているものと考えられます。それから品川区としては、だからできないというわけではなくて、独自に交渉していないという状況です。","voiceIndex":110,"id":"exchange-042"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そこはわかりました。前半で私は間違えていたらいけないのですけれども、あそこの桟橋をやったとき、区は交渉に入っていたのでしたか。費用的には、区は全然入らなかったのでしたか。たしか最後に、これも間違ったらごめんなさい、トイレとかつくるのにも随分区が絡んで、大変な思いをしたのではなかったかという記憶があるのですけれども、その辺はどうでしょうか。","respondent":"和田河川下水道課長","answer":"申し訳ありません、承知をしておりませんので、調べて後ほど回答を差し上げたいと思います。","voiceIndex":112,"id":"exchange-043"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それと同時に、東品川中継所の関係も、これは直接防災ではない部分が絡んでくるので聞き方が半端になってしまうかもしれないのですが、そこの折衝も今いろいろなところがやっている中で、観光部門と防災部門は分けて折衝するのか、そこも含めて折衝に入っていくのか、その点も教えてください。","respondent":"和田河川下水道課長","answer":"東品川清掃作業所の桟橋に、補正で予算をつけていただいたもので、１０月から工事に入る予定なのですけれども、これについての折衝というのは、防災と観光両面からというか、１つの窓口で両面から折衝しています。","voiceIndex":114,"id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"意見","question":"先ほど１０ページと、逆に１１ページが、あまり固有の会社の名前を出すのはあれですけれども、こちらの企業も一緒に協定に入っているわけですよね。その中で別扱いしてくるというのは何故かなというのは、何となく地域の声も聞くのですけれども、その辺をもう一回お願いしたいのですが。","respondent":"和田河川下水道課長","answer":"それに対しまして１１ページの船清との協定は、屋形船等の施設、桟橋以外の船等につきましても、その一部を使わせていただくという協定になっているものです。","voiceIndex":116,"id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そういう意味で先ほど、先方からお話があって、契約にかかわってくるというのは、その辺の意味になるのかな、そう理解していいのかなというのが何となくわかったのですけれども、もう一つ、東品川中継所のほうは、全体的に含めて調整していっていただきたいと思います、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-046"},{"speaker":"西本委員","kind":"確認","question":"ということになると、これは１３カ所ありますけれども、それはまずいよとか、使用法についての調整というのはそれぞれがやるのですか。それとも、あくまでも締結している、どういう内容なのかわからないのですけれども、都の決めたことに従って、この桟橋が使われるという形の認識なのでしょうか。","respondent":"和田河川下水道課長","answer":"すいません、失礼しました。運河ルネッサンス協議会で協定を結んでいる桟橋につきましては、東京都の防災船着場の桟橋には指定されてございませんので、これについては区が独自に使えるものという認識です。","voiceIndex":119,"id":"exchange-047"},{"speaker":"若林委員長","kind":"確認","question":"品川区は参画をしていて、いろいろ意見を申し述べるというお話があったわけですけれども、全体的に当然これは東京都が統括する、コントロールするものというところの確認と、他区は、この検討会とかこれからの運用マニュアルに対してどのような姿勢で臨まれているのかということを確認しておきたいと思います。","respondent":"和田河川下水道課長","answer":"それから各区の立場とか意見については、第１回の検討会が７月１９日に開催されていまして、第２回はまだでございまして、７月１９日には趣旨の説明のみで終わっておりますので、各区の意見は聴取できていない状況です。","voiceIndex":121,"id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"いずれにしても、東京都の動きがはっきりする時期があれば、それに合わせた形で議論を深められるのではないかなと思うのですが、スケジュールは見えていますでしょうか。","respondent":"和田河川下水道課長","answer":"１１月中旬に第２回検討会、それを受けまして１２月から１月にかけて作業部会が１回程度、２月中旬に第３回検討会が開催されまして、その後、策定というスケジュールになってありますので、年度末にかけて検討が深められていくというスケジュールになっているところです。","voiceIndex":130,"id":"exchange-049"},{"speaker":"西本委員","kind":"意見","question":"かなり速いスピードで進められているなと思うので、かなり大きく動きが出てくるのではないかなという見通しが出てくると思うのです。なので、それを見た上で、また検討していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":132,"id":"exchange-050"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"わかっていればというところなのですが、今回３棟で、その後は検討中ということですが、見通しとかというのは何も出ていない、公開はこれだけという話なのでしょうか。","respondent":"稲田都市開発課長","answer":"今回この３棟だけということで説明を受けております。りんかい線が、残る部分については地下に通っているということで、検討を要するですが、そういうことでスケジュール等、まだはっきりしていないです。","voiceIndex":139,"id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4180#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":32619,"voices":143}},{"id":"h28-20160822-9","meetingId":"h28-cm08","date":"2016年8月22日","dateIso":"2016-08-22","committee":"文教委員会","time":"午後 １時００分～午後 ５時０６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を109件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"初めにひろまち保育園の問題の報告がされたので、ちょっとそこについてもお聞きしたいと思います。先ほど事業者との話し合いで契約解除ということでしたけれども、報道によれば看護師の配置をしていなかったとか、園長と法人の方針が合わなかったとか、備品購入におかしなところがあったという報道がありますが、その辺を踏まえて契約解除の理由を詳しく教えていただければと思います。","respondent":"竹田保育課長","answer":"それから園長との保育についての考え方ですが、今回不正の疑いについて、保護者会での説明などを法人については求めていたところですけれども、区の納得いくような説明がなかったこと、ほかにも区が公立の保育園で培った保育を踏まえ。","voiceIndex":6,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"法人側が民設民営に固執したということですけれども、もう少しその辺を、相入れなかった、契約解除につながった部分をもう少し詳しく教えていただければと思います。","respondent":"竹田保育課長","answer":"内容を事細かにご説明すると多くの時間もかかってしまうのですが、例えば報告関係の書類など、もろもろの面において法人側はご自分のスタイルを貫きたいというところだったのですけれども、私どもは区の保育の質を踏まえてというところを主張したのですが。","voiceIndex":8,"id":"exchange-002"},{"speaker":"のだて委員","kind":"確認","question":"やはり保育方針が区のやり方と合わずに解除になったということだと思うのですけれども、契約のときに区の方針に基づいてやっていただくということがたしか明記されていると思うのですが、それに合わないということで解除になったということでいいかという確認です。今在園されている園児の数と、保育士はもちろんですけれども、事務職の方など職員の人数も、何人いたのか教えていただければと思います。","respondent":"竹田保育課長","answer":"それから在園児については約１８０名が今通園しております。保護者の方々には明日夕刻、説明会のほうを予定しているものです。すみません。保育士ですが、保育士のほうは三十数名、そのほか栄養士、事務員等がおります。","voiceIndex":10,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"約とか数名とかではなく、具体的な数字を教えていただければと思います。あわせて正規の方と非正規の方の人数も教えていただければと思います。","respondent":"竹田保育課長","answer":"すみません。資料がちょっとすぐ出ませんので、後ほどご報告します。","voiceIndex":12,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"そして今回、３月までは継続されるということですけれども、その今いらっしゃる職員、区の職員が退職してそちらに勤めている方もいるということも聞いているのですが、そういった方などが今回３月で終わってしまうというところで、職員の方はこれからどうなっていくのか、夢工房のほうで勤め続けていくのか、それとも今回、この品川、これでなくなったので雇いどめとなってしまうのか。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"離職率ですが、直近の理事長との話の中で約１０％というふうに聞いております。それから保育士の件ですが、園に従事する保育士は新しい事業者が雇用する保育士となります。今いる保育士は夢工房の社員ですので、新しい事業者が決まった後どのように志望されるかは私どもは承知をしておりません。","voiceIndex":14,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったところで、今回方針が合わないということで契約解除ということになって、しっかりどうなっていくのか、このひろまちがなくなったことによって仕事を失ってしまう方がいないように、区としても配慮していっていただきたいと思うのですが、その辺の実態、状況をつかむという点も含めてやっていっていただきたいと思いますが、いかがでしょうかということと。","respondent":"竹田保育課長","answer":"委員が先ほど契約解除とおっしゃいましたけれども、役所の契約、本契約は１年の契約になっておりますので、本契約は年度末まで１年間しっかり契約どおり行う予定です。","voiceIndex":17,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"３月末までも看護師配置のほうは求めていくということでいいということですね。状況をつかんでいただきたいということもお聞きしたので、それについての答弁もお願いいたします。やはり今回運営委託して、区の方針と合わずに解除になったというところで、姫路市のほうでは運営費の不正受給等もあった中で、区のチェック機能というのはどういった仕組みになっているのでしょうか。","respondent":"竹田保育課長","answer":"先ほど保育士の状況ということですが、先だって合意解除後に法人のほうから職員については説明があったというふうに聞いております。私どもも区としての説明をまたしていきたいと考えております。","voiceIndex":19,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"今回、やはりそのチェック機能がうまく機能しなかったためにこういったことが起きたと思うのですけれども、今後丸ごと運営委託していくというところで、区の保育方針を本当に実現できるのかというのは疑問なのですが、やはりこういったことがないようにしていくには公営を考えていくべきだと思うのですけれども、丸ごとの運営委託で区の保育方針、実現できるのでしょうか。","respondent":"竹田保育課長","answer":"それから公設民営の件ですが、利用者に質の高い保育を提供することを一番に考えて、このことに不安がある場合は業者変更も辞さず、強い姿勢で取り組んでいくことを今回のものは示すものでございまして、今後もこの考えに変わりはございません。","voiceIndex":21,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"チェック機能は機能しているということでしたけれども、そうするとなぜ今回こういったことが起きたのかと思うわけです。その仕組みをもう少し詳しく、機能が発揮しているというところを教えていただければと思います。","respondent":"竹田保育課長","answer":"どういうことをもってチェック機能が働いていないとおっしゃられているのか、ちょっとわからないところなのですが、運営委託をして支出したものについてはその明細と領収書等をご提出いただいて、その品物を、現物を現場で確認しているところですので。","voiceIndex":23,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"やはり今回契約解除になったというところで、保育方針が合わなかったということが事前にわからなかったわけです。そういったところでチェック機能がしっかり機能しているのかということなのですが、いかがでしょうか。","respondent":"竹田保育課長","answer":"昨年現在の業者が、事業者が決まってから、何度も話し合いのほうを進めてまいりました。しかし、実際に園運営を始めると諸問題、いろいろな問題が発生いたします。","voiceIndex":25,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"何点か確認をします。その上で、何点か確認をします。保護者の皆様に何かこのことで影響が出ているのか、このことが報道されたことによって、保育事業に支障が出ているのかどうか、ちょっと確認をさせていただきたいと思います。それと明日、保護者の方への説明会があるということなのですが、ここで出ました声をまた委員会で報告をしていただきたいと思いますが、いかがでしょうか。","respondent":"竹田保育課長","answer":"明日保護者の方には臨時の保護者説明会を開きまして、現状などの内容を十分ご説明して、ご理解とご心配、ご不安を解消するように努めていきたいと考えております。その場の状況についてはご報告させていただきたいと考えております。","voiceIndex":28,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問","question":"現在保育園の運営に関しては支障がないというふうに受けとめてよろしいのでしょうか。","respondent":"竹田保育課長","answer":"現状の保育園運営について、支障はないと考えております。","voiceIndex":30,"id":"exchange-012"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ひろまちについて２点と、第三者評価について１点、ちょっとお聞きしたいのですけれども、まずひろまちについて第１点目は、一応お互い相反する考えが一致しないところがあるので、３月で契約を解除しますというご説明だったのですが、では３月まではどういう状態で運営されるのか。","respondent":"竹田保育課長","answer":"事実保護者の方から園の運営に対するクレームは一切いただいていないところです。現事業者も３月３１日まではしっかりと保育の業務を行っていきたいというふうに言っておりますので、しっかりと３月３１日までは支障なく運営していきたいと考えております。","voiceIndex":32,"id":"exchange-013"},{"speaker":"鈴木（博）委員","kind":"質問","question":"選ぶときに保育課長のほうでいいところが見つかったとおっしゃったように、そこそこのレベルだと思うのですけれども、要するに今の話だと、夢工房は夢工房のやり方があってそれに固執しているから、品川区のやり方と保育の面で合わないところがあるから今年度いっぱいで終わりにしますというお話だったわけだから、そうすると今から３月までの間というのは向こうのやり方、自分のやり方をやるというのと。","respondent":"竹田保育課長","answer":"今までお話を進めていく間で、幾つか解決できた問題もあります。今後もお話を続けて解決に向けて隔たりを１つずつ埋めていきたいと考えております。ただ、今後も５年間継続していくことは難しいと考えて、今回合意に至ったものです。","voiceIndex":34,"id":"exchange-014"},{"speaker":"鈴木（博）委員","kind":"質問","question":"とりあえずやり方が違う部分があるということなのだけれども、それは在園しているお子様たちに迷惑がかからないように、その辺の配慮をよろしくお願いします。それとあと第２点なのですけれども、今回夢工房を選ぶときに、私は去年も文教委員会にいたのだが、課長のほうが胸を張ってすばらしいところが見つかりましたというご説明だったと思うのですけれども、あれ、言ったではないですか。","respondent":"竹田保育課長","answer":"今回私どもが仕様書等で求めていたものは、公設民営、区立の保育園ということですので、区が今まで培ってきたノウハウ等も踏まえて、活かして、それで私立のよさを加味して運営していただきたいというところでございましたが、その趣旨が十分伝わっていなかった。","voiceIndex":36,"id":"exchange-015"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"東京都福祉サービス第三者評価について今ご説明いただいたのですが、これを読みますと東京都福祉サービス評価推進機構が認証した評価機関が客観的・専門的に評価したということで、次に書いてあるアンケートの項目というのは、これは利用者を対象にしたアンケートの結果がこうですということだと思うのですけれども、このアンケートの結果というのは。","respondent":"竹田保育課長","answer":"こちらアンケート項目、幾つかの抜粋でございまして、実際はもう少し多くあります。この質問項目が適当かどうか等も含めまして、専門的に検証した結果、こちらのアンケートを実施して一定の結果が出たものと考えております。","voiceIndex":38,"id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問","question":"アンケート項目でここに６つの項目が並んでいるのだけれども、この６つの項目というのは、結局保育園を利用している保護者の方に対するアンケートなわけですよね。ここにわざわざこのように書くからには、何らかのフィルターとか、バイアスだとか、テクニックだとか、手続だとかあったのではないかなということを考えたのですけれども、これがどういう形のアンケートをしたのですか。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"残念ながら全利用者からは回答はいただいておりませんが、この結果に基づきまして、あるいは評価機関が園にヒアリングを行いまして、それぞれの園ごとによいと思う点、改善が必要な点等が報告されて。今後ですが、もちろんプロポーザルの審査、書面で来たものだけではなくて、さまざまなところから情報を得ながら、よりよい業者を選びたいと考えていますし、保育の方針が整わない場合、あるいは質が整わない場合。","voiceIndex":40,"id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"引き続いて次に行きます。ということは１０人に３人は不満を持っているという回答だと理解できるのですけれども、これ正確な評価はいいのですが、ではこの評価の中身は、これはちょっと部分的に、少しこれではまだ改善する余地が多くあるのではないかなというような反省というか、そういう線で見てもいいのではないかと私は感じたのですが、保育課長、いかがでしょうか。","respondent":"竹田保育課長","answer":"こちらのアンケートの率については、各園ごと、項目ごとにそれぞれ異なっておりますので、あくまでもこちらは平均です。それぞれの園ごとにこちらのアンケート結果を踏まえて、十分現状を検証し、改善に役立てていきたいと考えております。","voiceIndex":43,"id":"exchange-018"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ただしこれを見てみると、やはり点数が低い項目というのは、公立も私立も低いので、もちろん個別の需要があれば個々の保育園において自己評価は当然違うのですけれども、やはりこういう点は気をつけたほうがいいのではないかなという１つの目安になるというふうには考えられないのでしょうか。","respondent":"竹田保育課長","answer":"こちらの結果を踏まえて十分、例えば低い項目については今までのやり方が適正だったのか、もうちょっとよい方法がないのかということの改善の余地があろうかと思いますので、評価が低かった点については十分検証して、次回に、今後に役立てていきたいと考えております。","voiceIndex":45,"id":"exchange-019"},{"speaker":"あべ委員","kind":"質問・要望","question":"このひろまちについてお伺いしたいと思います。その上で幾つか質問重なるところもありますけれども、お伺いしたいと思います。あわせて保護者の方や関係者の方、やはりいろいろとご不満に思っていらっしゃる方もいらして、私のほうにもそういう声も伺っておりますけれども、そういったことをできるだけ関係者に、スケジュールも含めて早く周知をしていただきたいと考えていますが、いかがでしょうか。","respondent":"齋藤子ども未来部長、竹田保育課長","answer":"ただ、我々としては、これまで品川保育を体現してきた園長、副園長の保育の方針というのはすぐれたものだろうと考えたいし、そういった保育をしてもらえれば５年間時限的な保育所の中で円滑な運営ができる、結果として。同時に実施要領等も定めておりますので、こちらの詳細については今回の応募の業者に十分説明し、ご理解、納得していただいた上で選定を進めてまいりたいと考えております。","voiceIndex":48,"id":"exchange-020"},{"speaker":"あべ委員","kind":"質問","question":"ただ、だからといって、あけてみたら毎回こういうことが起こるというわけにはいきませんので、となるのであれば、例えば実際に運営を始めたときの意思決定のあり方や組織のあり方ということも含めて、仕様ないし何らかの形で明文化をしていくというのも１つのやり方ではないかなと、今のお話を伺って感じました。必要になってくるのではないかなと思いました。","respondent":"齋藤子ども未来部長","answer":"ただ、選んだ業者と我々がうまくいかなかったのは、実際に保育をしてみないとわからないことでありました。今回、しつこいようですけれども、繰り返しになりますが、対応においては大変紳士的な対応していただきまして、合意解除というところにおさまったものではあります。","voiceIndex":51,"id":"exchange-021"},{"speaker":"あべ委員","kind":"提案","question":"今回こういう形で合意解除、要は今回のことがいいとか悪いではなくて、何ですか、やってみてだめだったからまたということが繰り返さないためには、どこまで仕様書を精査していけばいいのか、その文言についてまで具体的にこちらとして提案することではありませんし、それは区のほうで今回の経験をベースにしながらまた詰めていかれればいいのではないかと思いますけれども。","respondent":"齋藤子ども未来部長","answer":"プロポーザルのあり方、仕様書に大きな問題があったとは考えておりません。引き続き実際にやっていただいて、やっていただいた後に何か課題があれば話し合いをする場を十分に持って、考え方のすり合わせをしたいと、このように考えております。","voiceIndex":53,"id":"exchange-022"},{"speaker":"あべ委員","kind":"確認","question":"ひろまちのほうはこれまでとして、公営・民営保育園の運営費についてということで資料をいただきました。ちょっとこれ確認させてください。要はここで出てきている数字は、民営保育園のほうはほぼ１００人程度をベースにしているけれども、公営保育園のほうはこの数字というのは、定員１００人だけれども在籍園児は１３０人とか１４０人とかいますよということでよろしいのでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"公営運営費の算出の仕方なのですけれども、幼保一体施設等を除く３８園にかかわる経費を全部昨年度末の在籍児童数で割って１人当たりの金額を出して、その１００倍をして１００名分という出し方をしていますので、ちょっと説明が、言葉が足りなくて申しわけなかったのですが。","voiceIndex":55,"id":"exchange-023"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、歳出に関しては子ども１人当たりの経費というのはほとんど変わらないけれども、人件費については、これはどうなのかな。私立のほうは１人当たり人件費が３分の２程度になっていると。歳入については、公営はほぼ全額区で負担しているけれども、民営になれば国と都がその多くを負担している。民営は４分の１強、３分の１になるぐらいを負担しているという理解でよろしいでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"ですので、公営・民営どちらにしても、園児１人当たりの金額というのはそうそう大きくは変わらないというところなのですが、人件費を分析した結果、民営の保育園のほうが多くの保育士および職員を抱えているので、１人当たりの人件費が低いという分析結果になっております。","voiceIndex":57,"id":"exchange-024"},{"speaker":"あべ委員","kind":"意見","question":"となると、民営化がいいかどうかというような話よりも、この仕組み自体が非常に、１人の子どもを育てる仕組みとして大変国の仕組み自体に疑問を感じる、それに対して区でどうせよというわけにはいかないのですけれども、こうした仕組みというのは果たして、要は民営に通う子どもも公営に通う子どもも同じ品川の子ども、あるいは日本の子どもであるにもかかわらず。","respondent":"佐藤保育施設調整担当課長","answer":"その３年後ですか、平成１６年度に実際に国庫負担金等の負担金が廃止され、一般財源化されたというところになっている経過というふうに認識しております。","voiceIndex":59,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"でも何もわからない。東京都の監査というのは、当然この芦屋市の問題が出た後に、品川区にも入っているのでしょうか。東京都はお隣の港区と、あと目黒区に３カ所開設をして、私どもそこの中身も聞いてきてはいるのですけれども、都の監査が入っているかどうか、どこまで調査ができて、この運営費の問題はないと言われているのか、ちょっとその点を１点、まず最初にお伺いします。","respondent":"竹田保育課長","answer":"検査方法ということですが、先ほどご説明しましたとおり、購入備品等の一覧表を提示していただき、それに領収書を１件１件突き合わせ、現物を確認しながら検査しています。それから先ほどのだて委員からのご質問のお答えできなかった職員の人数について、ご説明差し上げます。","voiceIndex":62,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから本来１歳児園だと看護師配置が義務づけられていないにもかかわらず、やはり大規模な園であるというもので健康を配慮して看護師の配置を決めてくださったのだと思うのですけれども、４月当初から現在において、配置をされていないのがわかっていて改善がされていないのか、私不正というところにおいては、配置をされていなくても請求があったかどうかというのを、ちょっとそこを確認させていただきたい。","respondent":"竹田保育課長","answer":"それから私どもの考え方を事業者に伝える方法として、仕様書あるいはプロポーザルの実施要領等において詳細に保育内容等定めておりますので、こちらを十分ご理解いただけるよう説明に尽くしてまいりたいと考えています。","voiceIndex":64,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"ただ一生懸命説明をしていきますというところだけでは納得がいかないと思うのですが、いかがでしょうか。職員なのですが、国の基準を満たしているというのはわかりましたけれども、総勢で何人になるのか。非正規が先ほど１名と言っていましたけれども、非正規の職員は１名だけなのですか。ちょっとそこをもう１回明らかにしてください。","respondent":"竹田保育課長","answer":"職員数ですが、先ほど申し上げたとおりです。一般的に公立では非常勤職員を多く採用しているところですが、私立では非常勤職員を少なめに採用しているというような、一般的な傾向がありますので、こちらもその流れに沿っているものだと考えています。","voiceIndex":66,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど看護師のことを伺ったのですが、ちょっと答弁されていないので、看護師が採用されていないというのはわかったのですけれども、その運営費の申請がされていたのかどうか、その辺の改善がどうだったのかを漏れているので聞かせていただきたいのと、あと仕様書のところなのですが、ぜひ私たちとしては仕様書以外にどうしたら品川の保育をしっかりと守って、実行していただけるのかというところにおいては。","respondent":"竹田保育課長","answer":"それから品川区の保育の基準ということですが、全国的にも珍しい「のびのび育つしながわっこ」という形で１冊の冊子に見える形にしておりますので、そちらの区の基準に沿って運営のほうも今後行っていきたいと考えております。","voiceIndex":68,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今の最後の処遇の公表のところで、自治体によってはきちんと企業を把握するということで公表を求めて、委員会の資料に出ている自治体もありますので、やはりここを外したら、表向きをいくら公表し、ホームページに載ったりいろいろしていても、実際が違っていてはわからないし、働いている中の人や保護者の意見というのはなかなかあらわれてこないですよね。とりあえずいいです。","respondent":"竹田保育課長","answer":"処遇についてはどのような公表の仕方が可能かどうかは、今後検討していきたいと思います。それから看護師の運営費については、今後、今年度トータルで考えていきたいと考えております。","voiceIndex":70,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今の答弁、ちょっとよくわからないので。不正受給があったのかなかったのかを知りたいのであって、夢工房自体が看護師の賃金を請求していたのかどうかという、そこが一番知りたいので、そこを答えていただきたいということです。","respondent":"竹田保育課長","answer":"それから保護者の不安についてですが、今のところご質問等はいただいておりますけれども、具体的なご不安は示されていないところですが、明日しっかり説明するとともに、事業者が決まった際にも十分説明をして、不安の解消に努めていきたいと考えております。","voiceIndex":72,"id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問・要望","question":"すみません。その辺は行政としてしっかりチェックをすべきではないでしょうか。だから私は、どこが問題であって、どこをどう改善して３月までしていきます、でもそれでもなおかつ改善されない部分があるので業者をかえます、業者をかえるに当たって、このようなことがないようにこういった手を打っていきますというところまでご説明がない限り、絶対保護者は納得できないと思うのですが、いかがでしょうか。","respondent":"竹田保育課長","answer":"それから保護者の方のご不安ですが、不安がないように明日も説明会を行いますが、適宜情報提供して不安の解消に努めていきたいと考えております。","voiceIndex":74,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"すみません。繰り返しになってしまっているのですけれども、看護師に関してはちょっとやり方が違うとか、計算の方法が違うという話だったので、ぜひ私たちにもわかるように、不正はありませんでしたとはっきりわかるような資料で提示をしていただきたいと思うのですが、いかがでしょうか。これ委員長になってしまいますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は１つには、今日運営費の説明もありますが、公定価格のところの計算式がよくわからないのです。だからそういった意味で、運営費というのはどのような計算をされて算出をされていくのかというところも含めて、私は資料を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"お金の問題については、今年度が初年度でもありますので、何といったらいいのですか、今から何か不正をしようというようなことは当然ないと考えていますので、そういったことも踏まえて、安定的な保育ということを最優先に考えていかなければいけないのではないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"運営費と処遇について。大事な資料を出していただきましてありがとうあります。感謝します。２つあるのですが、この辺の計算して出された部分がどう使われていくのかという基本のところを知りたいのです。法人の方に伺うと、法人のお金の配分の仕方というのは、やはりさじかげんがあると。その辺はどこまでつかんでいらっしゃるのかお伺いしたいと思います。","respondent":"竹田保育課長","answer":"ちなみに給与項目として出されているのが、３２園中基本給に充てたとしている園が１７園、手当で運用しているというところが同じく１７園、賞与が６園、一時金として支出しているというのが１５園ありまして。","voiceIndex":85,"id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最初に委員長にお願いしたいのは、公定価格の表をぜひ見せていただきたい。黒塗りがあってもいいのです。それが１点です。１戸当たり８万２,０００円、すごいなと思うのですが、使い勝手が悪いという声を伺ったので、ちょっと実態がどうなのかなと。何か事業者が丸ごと借り上げをしないと使えないというような要項か何か、説明になっていたのですが、その辺どうなのか確認をさせてください。","respondent":"竹田保育課長","answer":"こちらのスキームの中で、事業者が原則として区内に宿舎を借り上げ、保育従事職員用の宿舎としていることが要件となっておりますので、事業者が一括して借り上げて従事者に提供しているものについて補助しているものです。","voiceIndex":87,"id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大きな事業者であれば丸ごと借り上げたりもできると思うのですけれども、なかなかそうなっていない事業者については、１戸当たりの補助をしていただきたいなという声が上がっています。お隣の大田区は１戸ずつにこの制度が使われていると伺ったので、ぜひ改善ができるのだったら改善をしていただきたいなと思うのですが、いかがでしょうか。","respondent":"竹田保育課長、佐藤保育施設調整担当課長","answer":"宿舎借り上げですが、法人契約されたものが対象としておりますので、借り上げ物件等を探す際には十分ご理解いただいた上で、本制度を利用していただくようにしたいと考えております。２点目の土地・建物の賃借料をどういうふうに入れているのかという話なのですが、今回公営保育園との比較になりますので、公営保育園のほうには土地・建物賃借料という考え方はありませんから、民設民営のほうはそのまま全て削除して。","voiceIndex":89,"id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"家賃助成についてはぜひ改善してほしいという意見が出ていますので、ちょっとお隣の大田区では１戸１戸で支援されているという声が出ていますから、ぜひ調査をして、改善できるところは使いやすくしていただきたいなとお願いをいたします。そこの大もとの改善のところにおいて、やはり国の補助金の足りなさというか、そこのところをどう考えていらっしゃるのか、１点お聞きしたいと思います。","respondent":"竹田保育課長","answer":"それから国の公定価格についてどう思うかということですが、こちらは国の、日々見直されております。処遇改善等含めて見直されておりますので、その動向を注視していきたいと考えております。","voiceIndex":92,"id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"新制度ができて、公定価格というものが示されてきているわけですから、その大もとを改善していくという意味で、自治体負担が大きいというところに大もとにある保育の開設時間などについても、ぜひ国にしっかりと物を申していく、意見を言っていく自治体であってほしいと思いますが、いかがでしょうか。","respondent":"竹田保育課長","answer":"委員おっしゃるとおり、公定価格が始まり１年が経過しまして、もろもろの課題が見えてきたところです。国においても、この課題を解決すべく、今若干の修正等の検討をしているというふうに聞いておりますので、その動きを注視していきたいと考えております。","voiceIndex":94,"id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"多くの委員もお話しされているので、ちょっと確認だけで、あと数カ月という形なので、やはり残った、ごめんなさい、ひろまちのほうですけれども、運営のほうをきちんと在園児の方に提供していただきたい、この辺は確認されていると思うのでぜひお願いします。","respondent":"竹田保育課長","answer":"私を初め、本課の職員も数名参加しますし、園長を含めた夢工房の職員ももちろん参加して、ご説明に当たります。","voiceIndex":97,"id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"この私立認可保育園に処遇改善を全部の園が申請して、全部の園にこういった改善のための補助がされているのかということが１つ、そして先ほどもちょっと出ていたのですが、事業者が区に報告し区が確認という、その実績報告については、先ほどもありましたように、何ですか、どのような立場、基本給にどれぐらいというのはありましたけれども、その辺の把握をきちんとしていかれる。","respondent":"竹田保育課長","answer":"それから処遇改善の方法ですが、こちらにつきましては各園の運営実態によるとされておりますので、経験年数等の傾斜配分を行う園もあれば、一律に処遇改善している園もありますので、それぞれの園の実態に即してされるものと考えております。","voiceIndex":99,"id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ということを区のほうできちんと確認していただきたいという要望です。いかがでしょう。","respondent":"竹田保育課長","answer":"既に処遇改善の内容についてはそれぞれ様式で報告を受けておりますので、そちらに沿って……。全園から報告を受けて、しっかり確認しております。","voiceIndex":101,"id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"ちょっとひろまちのことについて１点だけ質問したいのですが、看護師の配置はされていないということが事実だということで、でも不正はないというところで、何をもってそこで不正がないとしているのかお聞きしたいと思います。これは公定価格、東京都のキャリアアップ補助金、こういった従事者の宿舎借り上げ、全てそういった対象なのか、伺いたいと思います。","respondent":"竹田保育課長","answer":"不正の考え方ですけれども、こちらに誤った、偽った報告をした場合は不正だと考えておりますが、偽った報告というのは受けておりませんので、不正とは考えておりません。","voiceIndex":104,"id":"exchange-044"},{"speaker":"のだて委員","kind":"質問","question":"この公定価格のところで加算実績額が職員の賃金改善に限定されるとあるのですけれども、これはどのように限定されているというのか、チェックされているのか伺いたいと思います。賃金改善の給与項目のところで、基本給、手当、賞与、一時金、先ほどありましたけれども、「等」というのもあるのですが、これはほかにどういった支給の方法があるのか伺いたいと思います。","respondent":"竹田保育課長","answer":"それから「一時金等」の「等」ですが、こちらそれぞれの施設によってさまざまな手当等がありますので、各園の実態に合わせて支給できるように「等」という表現をしているものです。","voiceIndex":106,"id":"exchange-045"},{"speaker":"のだて委員","kind":"確認","question":"この処遇改善の実績報告の中で区が確認するというところがありますけれども、キャリアアップのところでも「適切に実施されたか確認を行い」とあるのですが、どのように確認して適切に実施されたと確認しているのか伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"その確認してというのはどのような、適切に実施されたというのは何を確認してそう認識しているのか、決定しているのか聞きたいと思います。このキャリアアップ補助金のところで、私立認可保育園が１８園の実績があるというところで、ほかのところはなぜやっていないかというような声を聞いていたら教えていただきたいのですが、これ対象になる職員がいないということなのでしょうか。伺いたいと思います。","respondent":"竹田保育課長、佐藤保育施設調整担当課長","answer":"それからキャリアアップのほう、全園で行われているのかというご質問ですが、全園に対象園には区から支出したところですけれども、詳細がこちらかなりおくれて都から示されたということがあって。保育士だけ単純に比較すると、公営は１８名、民営は２２名ですけれども、公営の分に関しては先ほどもご説明しましたが、賃金のほうが高くなっていますので、各園の運営の実情に応じて違ってくるのだろうと考えています。","voiceIndex":114,"id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"公営のところでは１８人というのは保育士だけということだったので、そうすると一概に比較できないという気がするのですが、このもう少し詳しい資料を出していただかないと、しっかりとした検討ができないのではないかと思うのですが、これは委員長に。細かい、もう少し具体的な資料を出していただきたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"私のほうは運営費の比較のもととなった、もうちょっと詳しい資料を出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-049"},{"speaker":"のだて委員","kind":"質問","question":"この職員の人数や、質問もありました財調、どのくらい入っているのかというところもわかれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-050"},{"speaker":"新妻委員","kind":"質問・要望","question":"長時間にわたって課長、部長よりご答弁いただいております。会派としては要望はいたしません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-051"},{"speaker":"飯沼委員","kind":"提案","question":"提案をさせていただいたので、ぜひ提出を委員会にしていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":132,"id":"exchange-052"},{"speaker":"新妻委員","kind":"質問・要望","question":"これもご説明をいただきました。今いただいている資料で十分と思いますので、要望はいたしません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-053"},{"speaker":"新妻委員","kind":"質問・要望","question":"出されている資料で十分と思いますので、要望はいたしません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-054"}]},{"id":"topic-02","title":"区内事業者との連携企画","agenda":"区内事業者との連携企画","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"こちらは丸亀製麺から協力を申し出ていただいたのか、それとも区のほうで幾つか当たって決めたのかというところが１つと、先ほど移動の交通費もこの予算の中に入ってきているのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"移動の件につきましては、学習支援事業委託料で入っておりますが、急遽委託料を若干上乗せをいたしまして、委託料で賄っております。こちらで負担しています。","voiceIndex":168,"id":"exchange-055"},{"speaker":"飯沼委員","kind":"意見","question":"下の米印のところに、この丸亀製麺のところで、「子どもの孤食化の課題解消に向け」という社会貢献の活動と書いてありますけれども、これを受けて品川区がやったのだと思うのですが、この辺の目的と位置づけ、それから今後どういうふうにこういった事業を展開、受けとめていくのかという、今後についてもちょっと聞かせてください。","respondent":"廣田子ども家庭支援課長","answer":"今回先方の申し入れではあったのですけれども、この会社が女性に多く働いていただいていて、自分が温かいものを提供しているのに自分の子どもたちは家で１人で食べているというところの発想からは始まったというところのお話をいただいて共感しまして、一緒にやることに。","voiceIndex":171,"id":"exchange-056"},{"speaker":"飯沼委員","kind":"意見","question":"参加した男子生徒の感想はここに載っているのですが、こういったことを積極的にされていく企業であると思うのですけれども、企業のところの感想と、あと職員の方の感想、あったら聞かせてください。","respondent":"廣田子ども家庭支援課長","answer":"先方としましては、本社が神戸のほうにあるので神戸市ともやっていらっしゃって、できれば親子でも参加していただきたいというようなところはあったのですけれども、子どもたちが非常に楽しみにしていて。","voiceIndex":173,"id":"exchange-057"}]},{"id":"topic-03","title":"認可保育園の新規開設","agenda":"認可保育園の新規開設","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"前回のときもお聞きしましたけれども、保育士の確保のほうはどうなっているかということをお聞きしたいのと、事業者から何か声を聞いていたら教えていただきたいと思います。この間８園増設されておりますが、増設される場所ですか、どういったところにできるのかということを伺いたいと思います。先ほど平成２９年度の開設予定があるということでしたけれども、何園ぐらい予定があるのでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"モニカにつきましては、施設長については既に他園からの異動で決定しているということで、ほかの保育士につきましては異動、新規採用を含めて配置するという予定と伺っています。","voiceIndex":180,"id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、保育士の確保のほうはこれから順調に進んでいるということで、確認させていただきたいと思います。それから荏原地区が少ないというところで区のほうでも懸念されているということでしたけれども、今検討中ということですが、どういったことを検討されているか、お話しできる範囲で構いませんが、教えていただければと思います。","respondent":"大澤待機児童対策担当課長","answer":"待機児童の多い地区につきましては、公有地ですとか、民有地の活用についても、区としても検討しているです。","voiceIndex":182,"id":"exchange-059"},{"speaker":"新妻委員","kind":"質問","question":"ご説明ありがとうございました。着実にこのように待機児童対策、取り組みをいただきましてありがとうあります。今回、今４園報告いただきましたが、ここに開設をするに当たっての地域住民への説明会といいますか、近隣住民の皆様にはこの４園とも説明会というのは開催をされていて、この地域の方からのご理解というのは得られているのでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"その結果といたしまして、2)番のさくらさく保育園については８月３日に説明会を行いました。","voiceIndex":185,"id":"exchange-060"},{"speaker":"新妻委員","kind":"質問・要望","question":"着実に地域の方としっかりと共存していけるような、そういう保育園づくりをまた進めていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-061"},{"speaker":"あべ委員","kind":"質問","question":"前回に引き続き、プラス４園ということでご報告いただいて、年間８園以上の開園をするというのは、事務的にも大変なことではないかということで敬意を表するとともに、保育については体制もちょっとつくり直して、職員の方もついているとは思うのですけれども、職員は足りていますか。大丈夫ですか。","respondent":"大澤待機児童対策担当課長","answer":"開設につきましては保育課の開設指導係が担当しておりますが、今年度は職員の人数が増えておりますので、何とか職員頑張って対応しております。","voiceIndex":189,"id":"exchange-062"},{"speaker":"あべ委員","kind":"質問・要望","question":"ある程度人数も増えたということですし、大切な仕事ですので頑張っていっていただきたいと思うのですが、残業等々も多いと聞いておりますので、頑張ってはいただきたいのですけれども、やはり全体の体制にもさらに配慮していっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういったところにおいて、今回の４つ、さらに４つなのですが、新しい企業が入っているのかどうか。やはり保育内容の充実を目指していた品川区としては、ぜひよりよい事業者を選定してほしいといったところで、その辺のチェックがどうなっているのかなというのと、私たちはやはり保育内容を確保していくためには、品川独自の基準をぜひつくっていただきたいなと思っていますが、この点はいかがでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"事業者のほうからはガイドラインが明確なので、品川では運営しやすいというふうに言われておりますので、どちらの事業者もそれに沿ってやっていただけると認識しております。","voiceIndex":193,"id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問・要望","question":"両方合わさって改善をしていくのではないかなと思っています。この間、ご努力は評価いたしますけれども、まだまだ足りない部分を、やはり区が区の責任において足りない、アンバランスな地域にも計画的につくっていくという姿勢をぜひ求めたいと思いますが、いかがでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"現在のところ、新規園については基本は民設民営ということで、公設という考えはございませんが、待機児童の多い地区に関しましては、先ほども申し上げたように公有地および民有地、活用ができるように、それは区としても今検討していますので、今後も努力してまいります。","voiceIndex":195,"id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ公有地、民有地の活用というところもありますけれども、ぜひここを品川区が率先してやっていただきますように強く要望しておきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-066"}]},{"id":"topic-04","title":"目黒駅前地区第一種市街地再開発事業に伴う認可保育園の開設","agenda":"目黒駅前地区第一種市街地再開発事業に伴う認可保育園の開設","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"ここで貸し付け、開設期間５年というものの捉え方なのですけれども、暫定で５年ということではなくて、区の財産を貸し付けるに当たって、その手続上５年という考え方であって、基本的にこの保育園というのは、よほど何かが起こればわかりませんが、基本的には他の保育園を設置するときと同様、期限を定めないで運営していくことを原則というか、念頭に置いているということでよろしいのでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"今の委員のおっしゃるとおりでございまして、賃貸契約が５年ですので、基本的には継続していただくということで、公募のときにも事業者には説明いたします。","voiceIndex":202,"id":"exchange-067"},{"speaker":"のだて委員","kind":"確認","question":"ちょっとすみません。そもそもになってしまうかもしれませんが、区に譲渡されるというところで、この間の経緯を教えていただければと思います。先ほどもありましたけれども、開設から５年間の期間ということで書いてあったので、公設民営みたいな形になるのかなと思ったのですが、これは種別のところで見ると私立と書いてあるので、これは私立の認可園ということでよいのか、確認です。","respondent":"大澤待機児童対策担当課長","answer":"目黒駅前の再開発事業につきましては建設委員会で経緯は説明しているのですが、地域貢献ということで区のほうに公共施設分を譲渡いただくというような内容です。保育園につきましては、私立の認可保育園です。","voiceIndex":208,"id":"exchange-068"},{"speaker":"鈴木（博）委員","kind":"質問","question":"非常につまらない質問なのですけれども、この断面図を見ていると事務所の建物の保育園の３階部分が飛び出していて、この右側が空欄になっているのですが、ここは吹き抜けか何かなのですか。","respondent":"大澤待機児童対策担当課長","answer":"こちらエレベーターホールというふうに聞いております。","voiceIndex":210,"id":"exchange-069"},{"speaker":"鈴木（博）委員","kind":"質問","question":"エレベーターホールというのは吹き抜けということでいいのですか。","respondent":"大澤待機児童対策担当課長","answer":"すみません。ちょっと細かいところまでは、分かりかねます。申しわけありません。","voiceIndex":212,"id":"exchange-070"},{"speaker":"飯沼委員","kind":"提案","question":"そういった意味で、東京都が所有するこの事務所棟のところにもっと認可保育園がつくれないかどうかという提案をしたいのですが、以前には多分していたと思うのですけれども、この辺の需要と絡めてまだ必要であると考えているのか、ぜひこの東京都の持ち分のところに、この１カ所ではなく新たに認可保育園をつくっていただきたいと思うのですが、いかがでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"このほかに保育施設をということですけれども、ちょっと今ここですぐにどうというお答えはできなくて、再開発につきましては都市開発課の案件になりますので、ご意見として承っておくですが、このマンションの敷地以外にも、こちらの地域でまた事業者から提案がありました場合は。","voiceIndex":215,"id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問・要望","question":"税金を払っている割にはいろいろ恩恵が少ないと言われるような地域でもあります。そういった意味では東京都にも大いに協力をしていただいて、ぜひ認可保育園をつくっていただきたい。もちろん子ども未来部のところだけで決められることではありませんけれども、ぜひぜひ区のところで検討していただきたいという声を伝えていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":217,"id":"exchange-072"}]},{"id":"topic-05","title":"北品川一丁目保育施設運営事業者の選定","agenda":"北品川一丁目保育施設運営事業者の選定","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"５事業者から応募があったということですが、このサクセスアカデミー以外のところでどういったところが応募されたのか伺いたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"５事業者の内訳ですが、社会福祉法人が２社、株式会社は３社です。","voiceIndex":222,"id":"exchange-073"},{"speaker":"のだて委員","kind":"質問","question":"この北品川のところで今回サクセスアカデミーということで、今回また同じような、保育の方針だけではないと思うのですが、契約解除ということにならないようにお願いしたいのですけれども、今の区の解除にならない見通しはあるのかというか、どう考えていらっしゃるか伺いたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"今回決まったサクセスアカデミーは、先ほどもご説明しましたが、もう既に品川区内で１園認可保育園をやっておりまして、品川区の保育方針についてよく理解をしているということはプロポーザルの第一次審査の中でも確認していますので、認識の違いというのはないと考えております。","voiceIndex":224,"id":"exchange-074"},{"speaker":"のだて委員","kind":"質問・要望","question":"一度目、ひろまち保育園で契約解除ということがありましたので、二度目がないようにしていっていただきたいと思うのですが、やはりそのためには公営にしていくことも必要なのではないかと思うのですけれども、公営にしていくことをこのときには考えていたのか伺いたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"かねてからご説明していたと思うのですが、区としては民間でできることは民間でお願いするという方針に基づきまして、民営を基本として考えているところです。","voiceIndex":226,"id":"exchange-075"},{"speaker":"のだて委員","kind":"意見","question":"民間でできるところはお願いしていくということですけれども、今回ひろまちの件でいえば、区の方針でやってもらおうとしたところができなかったというところがあると思いますので、そういった中で、やはり公営にしていくことも考えていく必要があると思いますが、改めてそこを踏まえてご答弁いただければと思います。","respondent":"佐藤保育施設調整担当課長","answer":"具体的には月に１回私立園長会や、随時職員と交流する場もありますので、その辺も有効に活用して継続的なチェックをしていきたいと考えております。今後も民設民営化、民営の保育園に運営を委ねることに何ら変わりはございません。","voiceIndex":228,"id":"exchange-076"},{"speaker":"のだて委員","kind":"質問・要望","question":"私たちは常に言っておりますけれども、やはり公営で保育の確保をしていくことも必要だと思いますので、そこもぜひ検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-077"},{"speaker":"あべ委員","kind":"確認","question":"先ほどと似た質問なのですけれども、こちらは開設期間が５年間とあります。この場合の状況に応じて延長ありというのは、継続としてずっと続いていくということなのか、ここはむしろ５年間暫定のイメージが強いのでしたか。ちょっとそれを確認させてください。","respondent":"佐藤保育施設調整担当課長","answer":"こちら品川駅の南地域の再開発の地域に入っていますので、５年は一応開設するということで、それ以降は再開発の状況を見て、１年１年延長を考えていくです。","voiceIndex":232,"id":"exchange-078"},{"speaker":"あべ委員","kind":"質問","question":"先ほど目黒のほうは、やはり床を持っているのは区だけれども、こちらのほうは貸与をして私立、北品川のほうは貸与ではなくて公設民営の形、この私立の形をとる、同じように物件そのものは区の所有であっても、それを公設民営にするか、私立にするかというのは、その後の用途によって決めていくというふうな区の基本的な考えと理解してよろしいでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"実際に民設民営の園を運営する事業者等と話をすると、大体１０年ぐらいないとなかなか経営的に難しい面もあるということと、国庫補助金等のほうで決めた１０年間ぐらい変えられないという件もありますので、５年間なり、期間に限定のある場合は公設で建てて。","voiceIndex":234,"id":"exchange-079"},{"speaker":"あべ委員","kind":"質問・要望","question":"ありがとうございました。休憩前のひろまち保育園に関連する議論の中で、やはり区が公設民営園に求めるものというのは、民間の園に求めるものとプラスして、ちょっとまた違いがあるのかなと。そこが前半のところの議論だと感じています。そこら辺、民営としてやっていくのとは違って、区立認可園として求めていくものがあるのだよということは、もうご理解いただいていると考えてよろしいのでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"委員のおっしゃるとおり、公設民営で、あくまで設置主体は区になりますので、「のびのび育つしながわっこ」等でより細かい運営方針に沿った中身をやってもらうというところについても、重点的にやっていきたいと考えております。","voiceIndex":238,"id":"exchange-080"},{"speaker":"飯沼委員","kind":"質問・要望","question":"スケジュールのところを見ますと、第一次の審査会が６月１５日、第二次７月１３日、決定７月２９日となっていますけれども、この選定のメンバーを改めてお伺いしたいのと、６月９日に夢工房の問題が新聞報道されたわけですけれども、それを受けての審査会となっておりますので、その点特段夢工房の問題点も含めて、議論の中で検討された中身があったら教えていただきたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"二次審査についても、審査員は事前に集まって質問項目等のすり合わせを行うとともに、先ほどもご説明したのですけれども、厳正に質疑を行いました。","voiceIndex":241,"id":"exchange-081"},{"speaker":"飯沼委員","kind":"質問","question":"この公設民営保育園を経験している、どこの自治体でどのような仕事をされているのかというのはとても重要なチェックポイントであると思うのですが、この辺がどうだったのかを教えてください。","respondent":"佐藤保育施設調整担当課長","answer":"他自治体での請負状況といいますか、中央区のほうで１園、大田区のほうで１園、あとは千葉県のほうで１園等、指定管理という形でやっております。","voiceIndex":243,"id":"exchange-082"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私かねがね、なぜ品川区が指定管理者制度でなくて丸投げの民営化なのかなという疑問を持っていて、何回も質問しているのですが、全然その点に対して余り明確にいただいていないのですけれども、お隣の港区なども指定管理でやっているという話が結構しっかり聞こえてくるのですけれども、ちょっとその辺、最初の段階の質問と、ちょっともう１回指定管理ではなく公設民営、民営化のほうでやっているという考え。","respondent":"佐藤保育施設調整担当課長","answer":"指定管理者、公設民営ということで事業者をどういうふうに考えているのかというところなのですけれども、これは実際に二次審査の中で話をしたところなのですが、先ほども言いましたけれども、１園もう区内で私立の保育園をやっていますので。","voiceIndex":245,"id":"exchange-083"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なくて今回言っているのは、公設民営、民設民営ではなくて品川区内で保育を認可保育園でやるということではなく、品川区立の保育園を運営し、さっきほかの委員からのお話ありましたが、重要なのは公設民営、品川区立の認可の保育園であるという担保をしていくために、品川区は一体何を求めているのですか。余りさっきの答弁だと分からない。この間の答弁で。そこをぜひ聞かせていただきたいと思います。","respondent":"齋藤子ども未来部長","answer":"その峻別をするために、では指定管理者のほうがいいのか、業務委託のほうがいいのか、これを各自治体がいろいろ、さまざま状況に応じて、今回のように、例えば５年が基本的に限定の場合は指定管理をお願いできないのでこういった手法をとって。","voiceIndex":247,"id":"exchange-084"},{"speaker":"飯沼委員","kind":"質問","question":"部長のご答弁では余り変わりがないとおっしゃったのですが、指定管理者制度と今回の公設民営の業務の委託のところと、同じように議会としてチェックができるのか、ちょっと私も研究が足りないのですけれども、その辺はいかがなのでしょうか。","respondent":"齋藤子ども未来部長","answer":"指定管理の場合はモニタリング制度というのを区としてとっておりますので、モニタリングの結果を議会に報告します。業務委託の場合はそれについてはないということになります。","voiceIndex":249,"id":"exchange-085"},{"speaker":"飯沼委員","kind":"質問","question":"ごめんなさいね。これがないけれども、初めての公設民営の業務委託のところにおいては、ないけれどもほかにかわるものというのはあるのですか。だから今の部長の考えだと、業務委託だとこのモニタリングはないので、ここの部分はチェックができないということなのでしょうか。ちょっとそこだけ教えてください。","respondent":"齋藤子ども未来部長","answer":"モニタリング制度はありませんので、モニタリング制度に従った書式というもので議会報告することはありません。","voiceIndex":251,"id":"exchange-086"},{"speaker":"沢田副委員長","kind":"質問","question":"法人の特色ある事業内容のところで、当法人は「地域と共に育つ保育園」ということで本当にすばらしい、これはどこの保育園も本当にこうであってほしいなと思うのですけれども、具体的にこの地域はやはりいろいろと行事も盛んな地域ですし、今後どういったことを考えているのか、まだ１カ月ぐらいですけれども、どのようなことを考えられているのかということと、それから地域との交流ということで。","respondent":"佐藤保育施設調整担当課長","answer":"今後また委員のご趣旨を踏まえて、事業者と相談して地域貢献のほうを考えていきたいと思います。","voiceIndex":255,"id":"exchange-087"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"大変温かい地域ですし、しっかりと皆さんと連携して、地域の方ともいろいろ話し合って、行事もたくさんありますので、進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":257,"id":"exchange-088"}]},{"id":"topic-06","title":"品川区立戸越台複合施設の改修工事","agenda":"品川区立戸越台複合施設の改修工事","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"これは事務事業概要のときにも少しお聞きしましたけれども、そのときには基本設計はこれからやるということで、余り具体的な工事内容というものをおっしゃっていなかったのですが、そのときには設備関係などが古くなっているのでという話がありましたけれども、ほかにも耐震改修は終わっていると思うのですが、どういったことをやっていくのかというのをもう少し詳しく教えていただければと思います。","respondent":"品川庶務課長","answer":"主なところとしましては配管、それから給水管の取りかえ、それから屋上防水のやり直しですね。それからあと外壁改修や、あとは防水の改修など、このあたりが主なところとなります。","voiceIndex":262,"id":"exchange-089"},{"speaker":"のだて委員","kind":"質問","question":"そうすると躯体以外のところで大体大規模に改修をしていくという捉え方でいいのかというところと、学校施設については休業期間中に集中的に工事するということですけれども、夏期休業などでやると思うのですが、そこの期間で大体終わるというスケジュールになるのか伺いたいと思います。","respondent":"品川庶務課長","answer":"委員のおっしゃるとおり、設備関係の工事が中心となります。それから学校の休み期間中にできるのかというところですが、ここはもう基本設計の段階で極力やっていくというような考え方です。","voiceIndex":264,"id":"exchange-090"},{"speaker":"のだて委員","kind":"質問・要望","question":"居ながら工事ということもありますし、できるだけ利用されている方に影響がないようにやっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":266,"id":"exchange-091"},{"speaker":"あべ委員","kind":"質問","question":"２０年目の改修工事で高齢者施設部分、学校施設部分、それぞれ丸２年間ぐらいかかる。結構長くかかるなと感じます。これはやはり複合施設であることの特性みたいなものが関係しているのでしょうか。ちょっとその辺お答えいただければと思います。","respondent":"品川庶務課長","answer":"細かい点はちょっと把握はできないところもありますが、さすがにやはり居ながら工事ということで、各階ごとに工事のほうを進めていく関係で、やはり工事の期間のほうは長くなっていると。そういう考えです。","voiceIndex":268,"id":"exchange-092"},{"speaker":"あべ委員","kind":"質問","question":"公共施設がこういう複合の形になるとメリットもとてもたくさんあると思うのですけれども、こういう大規模なメンテナンスという意味では多少難しさもあるというふうに受けとめてよろしいでしょうか。","respondent":"品川庶務課長","answer":"いろいろな複合施設でありますし、やはり高齢者施設ということもありまして、それぞれ各階をやる中で引っ越し等も発生するようなところもあります。こういった点から、やはり居ながら工事の難しさがあるのではないかと思います。","voiceIndex":270,"id":"exchange-093"},{"speaker":"あべ委員","kind":"質問","question":"それと高齢者施設と学校施設を少し時期をずらせてということなのですけれども、例えば高齢者施設に着工した時点で、学校施設に対しても、学校エリアに対しても、騒音とか、振動などという影響というのはあると考えてよろしいのでしょうか。","respondent":"品川庶務課長","answer":"それから学校施設をずらしている関係は、この後説明もあるのですけれども、在籍する生徒の関係で、極力今在籍している生徒に関しては工事期間を影響させないような形でスケジュールを組んでいるというようなやり方です。","voiceIndex":272,"id":"exchange-094"},{"speaker":"あべ委員","kind":"質問","question":"高齢者のほうはちょっと所管違いになりますので、学校施設については今後どのような形で説明会等々を行っていくことになるのでしょうか。","respondent":"品川庶務課長","answer":"ちょっと具体的に、まだ基本設計の段階ですので、設計等のスケジュール等もある程度方向性が見えてきた時点で説明は行っていく予定です。","voiceIndex":274,"id":"exchange-095"}]},{"id":"topic-07","title":"学校案内パンフレットの配布","agenda":"学校案内パンフレットの配布","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"堅苦しいとともにとてもわかりにくいので、これちょっと、今までも多分こうやって書いていたのだと思うのですけれども、改めてこの理解を深めるという意味でもう少しわかりやすい表現の仕方がないかなということを率直に感じておりますが、いかがでしょうか。","respondent":"有馬学務課長","answer":"ただこれが重々しいのかどうなのかというところはあろうかと思いますけれども、校長等からも意見を聞きながら、ちょっと検討はしてみたいと思いますが、今のところはある程度重くして、卒業式、入学式と同等の儀式ということで節目の儀式。","voiceIndex":281,"id":"exchange-096"},{"speaker":"飯沼委員","kind":"質問","question":"今までの考え方はわかりました。でも、やはり義務教育学校ということ自体も理解をしていただくのがこれから重要かと思いますけれども、中身がわかるような表現というのですか、やはり儀式というのは、「えっ、一体何でしょう」と、率直に地域から声も上がっておりますので、ぜひいろいろな声を聞いて検討をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":283,"id":"exchange-097"},{"speaker":"あべ委員","kind":"質問","question":"すみません。この一番最後の入学校決定までの流れの左ページの米印２つ、この連絡というのは今、かなり速やかに教育委員会に連絡があるのでしょうか。要は国公私立中学校に入学が決定する、あるいは結果待ちだった方の結果のご連絡というのは、速やかに今は教育委員会に届いているのでしょうか。","respondent":"有馬学務課長","answer":"そういうところにつきましては、学校のほうとの連絡を図りながら、情報をなるべく早くもらうようにして、なるべく２月の末の段階で繰り上げが終わってしまいますので、それまでの間にいろいろ情報はとるように努力をしています。","voiceIndex":285,"id":"exchange-098"},{"speaker":"あべ委員","kind":"意見","question":"連絡がおくれてしまうと、それだけやはり待っている方のご迷惑とご不安を引き延ばしてしまうことになると思うので、何とかより多くの方がやってほしいというか、やらなければいけないことなので、何か目立つ方法はないかなとか、学校のほうからのプッシュもそうなのですが、さらなる、ちょっとこれもなかなか読んでいて若干わかりにくい文章かなという気もするのですけれども。","respondent":"有馬学務課長","answer":"そのときにある程度、就学指定は決まっていて来られない、来ていない方ということを学校のほうから情報を集めまして、それで一応対応することにしていますので、その学校説明会の場、２月に行われるその場、ここをもうちょっと有効に活用しながら、周知というか。","voiceIndex":287,"id":"exchange-099"},{"speaker":"あべ委員","kind":"意見","question":"何とか、ここの下の注意書きではなくて、この表の中に組み入れることができないかなと思っていたのですが、これはこれで結構複雑なので大変かもしれません。何らかさらに工夫をしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":289,"id":"exchange-100"},{"speaker":"高橋（し）委員","kind":"確認","question":"すみません。ちょっとわからないのですけれども、余り議論になる話かわからないのですが、例えば履歴書を書くときにこの義務教育学校を卒業した方は、例えば伊藤学園義務教育学校前期課程修了で、どこかの中学校に行ったときに転入学と表現して書くのでしょうか。その後、９年生は卒業でいいのですけれども、そこのところの表現を確認したいのですが。","respondent":"有馬学務課長","answer":"基本的に義務教育学校の卒業者については、例えば小学校では小学校卒業、中学校の卒業者は中学校の卒業者と同様に扱うということでそれぞれの上の学級に進学資格を有するものという形になっていますので、基本的には義務教育学校の前期課程修了、それから後期課程修了。","voiceIndex":291,"id":"exchange-101"}]},{"id":"topic-08","title":"中学校特別支援学級（通級指導学級）の新設","agenda":"中学校特別支援学級（通級指導学級）の新設","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"冨士見台中学校に設置をするというふうに決められた、これは地理的なものが大きかったのでしょうか。その選定の背景を挙げていただければと思います。それからかなり人気も高まっているような数字と聞こえましたけれども、現段階で定員がいっぱいで通えていないというお子さんも結構いらっしゃるのでしょうか。そして今回新設することによって、ほぼそれが解消されると考えてもよろしいのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"２番目なのですが、定員がいっぱいで今入れないという現状ではありません。ただ、今後そういうことが起きるだろうということで、ここ数年本当に急に対象の子どもたちが増えたということで、急遽どちらにつくろうかということで、冨士見台中学校に設置をしたという経緯です。","voiceIndex":297,"id":"exchange-102"},{"speaker":"のだて委員","kind":"質問","question":"この通級学級は先生というのは、１学級当たり１０人定員ということですが、何人ぐらいいらっしゃるのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"この通級指導学級は、教員の定数は１０名に１名なのですけれども、東京都はプラス１名を担任として配置をしていただいています。つまり、もしこの冨士見台中学校が１クラスでスタートするのであれば教員数は２名、２クラスで開設するのであれば３名ということになります。","voiceIndex":300,"id":"exchange-103"},{"speaker":"飯沼委員","kind":"質問","question":"新たに１校を増やすということなのですけれども、この２校のところ、地域的に分けたりするのか、選択の余地があるのか、また内容的に違いがあるのか、同じような内容で行っていくのかどうかを１点お伺いしたいのと、あと各学校との連絡をどのように行っていくのかというところも教えてください。お願いします。","respondent":"村尾教育総合支援センター長","answer":"２番目の在籍する学校等なのですけれども、通常この学校では、在籍する学校と、それからこの冨士見台中学校が開設しますと冨士見台中学校の担任と、ある意味指導計画をお互いがつくって、１学期どこまで学習をしましょうとか。","voiceIndex":303,"id":"exchange-104"},{"speaker":"飯沼委員","kind":"質問","question":"大崎中学校１校ではなかなかやり切れないところがあったのだと思います。増えてさらに利用しやすくというか、指導が充実することを望んでいますけれども、ちょっとよくわからないのですが、生徒は具体的にどのように通っているのですか。通級に対して。足なども含めて。","respondent":"村尾教育総合支援センター長","answer":"基本的には通級ですので、１人が例えば月曜日なら月曜日とか、また時間も決まっていますけれども、特に大崎中学校などは、大崎中学校に在籍している子どもが途中１時間だけ通級へ通うようなやり方もあるのです。","voiceIndex":305,"id":"exchange-105"},{"speaker":"高橋（し）委員","kind":"質問","question":"この通級、これ特別支援に関しては保護者の方々が教員に対して大変信頼を持つことによって成り立っているようだと思って、そうすると、今大崎の中学校には４クラスですから５人の先生がいらっしゃった。","respondent":"村尾教育総合支援センター長","answer":"委員のおっしゃるとおり、担任と保護者の関係すごく大事な部分で、本年度、実は平成２８年度、小学校でも特別支援教室が開始されて、やはり新しい学校にぽんとつくられたこともあります。","voiceIndex":309,"id":"exchange-106"},{"speaker":"高橋（し）委員","kind":"質問","question":"これ恐らく、もう一つは新設することに関しては東京都とかなり折衝をされたと思うのですけれども、そういったところでこういうものが実現したという点について、ちょっとご説明していただければありがたいと思います。","respondent":"村尾教育総合支援センター長","answer":"ただ、東京都のほうの第三次特別支援教育推進計画の方向でいうと、平成３０年度に今小学校でスタートしている特別支援教室が中学校版で開始をする予定で今進んでいます。","voiceIndex":311,"id":"exchange-107"}]},{"id":"topic-09","title":"品川図書館空調改修工事","agenda":"品川図書館空調改修工事","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"先ほど本には触れないということでしたけれども、今ある本を借りるということはできるということでいいのか確認させていただきたいと思います。","respondent":"木村品川図書館長","answer":"そのようなご認識で結構です。","voiceIndex":318,"id":"exchange-108"},{"speaker":"あべ委員","kind":"確認","question":"一応確認なのですけれども、この障害者サービスは、サービスそのものは継続可能なのでしょうか。","respondent":"木村品川図書館長","answer":"継続可能です。","voiceIndex":321,"id":"exchange-109"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4892#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":71192,"voices":327}},{"id":"h28-20160822-5","meetingId":"h28-cm08","date":"2016年8月22日","dateIso":"2016-08-22","committee":"総務委員会","time":"午後 １時００分～午後 ２時３５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２８年度都区財政調整交付金当初算定結果","agenda":"平成２８年度都区財政調整交付金当初算定結果","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そういう中で、これはこれから集まる、収入が入ってくる、そういうのもあって差額が出ても仕方ないという考え方なのかなと、ちょっとよくわからないので、その辺を教えていただきたいなと思います。その２つです。","respondent":"秋山財政課長","answer":"４月の当初、決算、年度末について額がですけれども、２月の当初のときはあくまでも予算ベースで見積もりをして、当初算定というものを行います。特に、収入額については調整三税の収入の見込みというものから出していくわけです。","voiceIndex":6,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"できるだけ経済状況に見合った財政執行というのはやはり必要に応じて、補正予算は組んでいますよ、補正予算は組んだりしているけれども、やはりしていく必要があるのではないかなと思っているので、その辺は一定程度フレキシブルに対応していく場面もあっていいのではないかなと思ったりしていますので、そういうところでどういうふうに考えるのかを伺っておきたいなと思います。","respondent":"秋山財政課長","answer":"１点目の三税の認識ですけれども、今年は固定資産税が１.９％の伸び、それから市町村民税法人分は１.９％の減ということで、先ほどもお話させていただきましたけれども、市町村民税の法人税については一部国税化の影響で減になっているというものです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"最後におっしゃった言葉尻をとるつもりは全然ないけれども、民生費は額的には上がっているというお話ですが、それは事実ですけれども、やはり例えば高齢者人口が増えているとか、保育園の待機児が増えている、待機児というか保育を必要とする人が増えているとか、そういういろいろな自然のそれなりの要因があって増えているわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません、何点か教えていただきたいと思います。お聞きしたいのは、先ほど来、まず市町村民税法人分で国税化の話が出ていて、これは具体的にどれぐらい見込んだからこんな１.９％マイナスになってしまったのかというのを教えていただきたいなというのが１点。投資的経費も減っているのだけれども、そこら辺のところの考え方というのを教えていただければなと思います。","respondent":"秋山財政課長","answer":"最初に、市町村民税の法人分ですけれども、平成２８年度で約７００億円の減収を見込んでいました。ただ、そうはいっても、法人の所得が上がっていますので、今回差し引きで１１３億円の減になったと見積もっているものです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ちょっと今の最初の法人分なのだけれども、よくわからなかったのですが、７００億円減収というのは、国税化に伴う減収と理解すればいいのか、ただ国税化だけに伴う減収が７００億円だったけれども、全体が増えているから１１３億円の減で済んでいるよということは、そうすると５９０億円ぐらいは増えているという理解でいいのかというのだけ教えていただきたい。だからこれ、減らない、減るという……。","respondent":"秋山財政課長","answer":"主張はしていますが、なかなかそれが都区協議の中で５５％を上げるというところもなかなか困難ということもありますし、あとはそういうところもありまして、現状としてこういうふうになっているというふうな理解をしています。","voiceIndex":13,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひそこは頑張っていただきたいなと応援をするというか、５５％の部分については、そこはちょっと触れられない部分が大分あるのだろうけれども、我々も含めて５５％については触れていきたいと思って、いろいろなチャンネルで５５％には触れていきたいけれども、やはり協議の中でそこら辺の、自分たちの部分で、これは品川区だけということではなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"}]},{"id":"topic-02","title":"品川区制７０周年記念しながわ百景のリニューアル","agenda":"品川区制７０周年記念しながわ百景のリニューアル","exchanges":[{"speaker":"南委員","kind":"質問","question":"今日配られた写真の中身についてですけれども、例えば１番とか８番とか小さな写真が入っているのがありますけれども、これを例えば１番なら１番で大きいのと小さいのと組み合わせてこの風景に指定すると、そういうことなのですか。","respondent":"中元広報広聴課長","answer":"委員おっしゃるとおりで、こちら、大井コンテナふ頭の夜景と昼間の風景合わせて１カ所ということで統合してお示しをしています。","voiceIndex":20,"id":"exchange-007"},{"speaker":"南委員","kind":"確認","question":"ごめんね、文句ばかり言うつもりは全然ないのですけれども、例えば１０番の花街道も、もっと菜の花がきれいに咲いている、そういう角度から、これは船を入れたかったのか運河を入れたかったのか、でこういう角度になったのだと思うのですけれども、何かちょっともっと花のきれいに咲き誇っている、そういう雰囲気がもっと出てもいいのではないかなとちょっと思ったりしたので。","respondent":"中元広報広聴課長","answer":"ただ、季節物でして、１月１日号にはちょっと間に合わないのですが、今後外へ打ち出していくに当たりましては、写真の撮り直しも含めて検討し取り組んでまいりたいと思っているところです。","voiceIndex":22,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"たまたまうちの控室に古い品川の戦後、戦前からの写真集が出てきまして、本当に貴重な資料だなと思ったのですけれども、ですから、そういう思いも込めて、そういう写真集をつくっていただいて、品川の歴史ということで、既にあるのは取捨選択していただいていいと思うのですけれども、大事に扱っていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"選定方法でちょっと教えていただきたいのですが、これは投票期間終了後、「シティプロモーション推進しながわ会議」において最終選定案を取りまとめた後ということなので、ここで最初に第１次でふるいをかけるということだと思うのですが、必ずしも投票数だけではないのかということなのかどうか。","respondent":"中元広報広聴課長","answer":"投票数も十分審議をいたしますけれども、その中でやはりちょっと心配をしているところは、組織票的な明らかに会社の広告的なものとかがどうしても入ってきてしまうのかなというところが。","voiceIndex":25,"id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。それは当然の配慮かなと思います。ただ、何でそういう数だけではないのかと伺ったのは、候補地以外に推薦したい風景がある場合は別途記載も可能とすることで、写真を添付したり理由を書いたりして投稿することが可能ということなのですが、そういう場合って選定が今度また難しいのではないかなと思いますが、その辺の選定についてはどのようになさるのでしょうか。","respondent":"中元広報広聴課長","answer":"ただ、やはりそれだけではなくて、これ以外にこういうところもあるよというご意見もあるのかなというところをぜひ寄せていただいて、もちろんそれもどの程度の数来るかも含めてですけれども、そこも含めて慎重に多くの方々の意見を検討の俎上に上げていきたいという思いです。","voiceIndex":27,"id":"exchange-011"},{"speaker":"吉田委員","kind":"提案","question":"限った、提案したものだけではないというのを選ぶというのは、趣旨としては大変結構かと思うのですが、やはりみんなが納得いくような最終選定というあたりで、当然そこに何票も集まるということはちょっと考えにくいので、その辺最終選定のときにみんなが納得できるような形をとっていただきたいなというのが、それは考えていらっしゃると思いますけれども。","respondent":"中元広報広聴課長","answer":"そういういうところで選定の会議、検討の会議の中ではさまざまシティプロモーション推進会議のほうには商店街連合会の会長であられますとかしながわ観光協会の方ですとか各方面の方、また区内の大学の方なども入っていただいている大きな会議があります。","voiceIndex":29,"id":"exchange-012"},{"speaker":"吉田委員","kind":"意見","question":"区の決定というのはどういうふうな形をとられるのか。","respondent":"中元広報広聴課長","answer":"この会議の結果等を受けましてまとめたもので広報広聴課で案をつくりまして、それで区長決定をとるという形です。","voiceIndex":31,"id":"exchange-013"},{"speaker":"つる副委員長","kind":"意見","question":"今の質疑を聞いていて、参考までに既存のものと、それから今新しいＡ４のものがありますけれども、カメラマンというのはどの方が。固有名詞を上げる必要はないのですが、それはプロの方にお願いしたとか、職員の方がやられたという感じで結構なのですが、どの方が撮られたものなのでしょう。","respondent":"中元広報広聴課長","answer":"すみません、選定当時のことは、私が確認をしていなくて申し訳ないのですが、今回のチラシ等につきましては、これはまだ現在区のカメラマンですが、今後１月１日号に向けましては委託の予算を補正でつけていただいておりまして、プロのカメラマンの方に撮っていただく予定です。","voiceIndex":33,"id":"exchange-014"},{"speaker":"つる副委員長","kind":"質問","question":"いろいろな考え方があるのかなと私の中でもちょっと思いながら、今後のシティプロモーション事業の推進というところでは、当然写真のクオリティーという部分ではそれなりのまさにシティをプロモーションしていく上での洗練された写真というのはやはり必要なのかなと思うのと、あと、一方で今回の記念の取組みの中では間に合わないかもしれませんが、今後写真もフィルムのものからデジタル化している中で。","respondent":"中元広報広聴課長","answer":"ご提案のようなこと、フィルムコンテスト、写真コンテストみたいなものも今後まずは選定した後でまた来年度に向けてどういう展開をしていくか、ご提案いただいてアイデアも含めながら、また文化観光課とも調整をとりながら検討をしてまいりたいと思ってあります。","voiceIndex":35,"id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問","question":"基本的なことを教えてください。私が理解していないのかもしれないのですが、今のしながわ百景の赤枠が１０個あるわけですよね。この２０プラスアルファ何か推薦があればあるかもしれないけれども、それでその１０選びますよという感覚なのか、この２０をそっくり入れてしまって１１０景なのかわからないけれども、そういうのもありなのか、どういう考え方でやるのかなというのだけちょっと。","respondent":"中元広報広聴課長","answer":"実は中にはちょっと辞退しますというところが実は１カ所あったりとか、それでこの１０カ所は落ちるのですが、今後の考え方の中で、例えば似たような角度から見ている風景があったりとかも一部なきにしもあらずなので、その辺のところをもしかしたら、こちらの案として。","voiceIndex":37,"id":"exchange-016"}]},{"id":"topic-03","title":"ものづくり創造センター等大規模改修工事","agenda":"ものづくり創造センター等大規模改修工事","exchanges":[{"speaker":"南委員","kind":"質問","question":"１１ページの下の１階の平面図の関係なのですが、ちょっとよくわからないのですけれども、オアシスルームとものづくりのほうの２階に通じる、あるいは倉庫、そういうところの平面図なのかなと思うのですが、オアシスルームの入口とものづくりのほうの入口というのは、ＡとＢとあるのですけれども、別々になっていると理解していいのですか。","respondent":"小林施設整備課長","answer":"ご質問の１点目の２階の創造センターと１階のオアシスの導線がどうなっているかという、これは１１ページの１階平面図をちょっとご覧いただきまして、今委員おっしゃった外壁改修の二重線があるのでちょっと見づらいのですけれども。","voiceIndex":46,"id":"exchange-017"}]},{"id":"topic-04","title":"西大井広場公園改修工事","agenda":"西大井広場公園改修工事","exchanges":[{"speaker":"南委員","kind":"質問","question":"ここの道路は本当に双方向通行の割に狭いので、３ｍの歩道ができるというのはいいかなとちょっと思っています。公園改修ですけれども、保育園をつくるのと歩道が設置されるということで改修になるので、ちょっとだけ、あまり踏み込むつもりはないのですけれども、保育園の出入口というのはこの歩道上からになるのでしょうか。","respondent":"立川経理課長","answer":"保育園の建設につきましてはまた別途工事というふうになるのですけれども、入口につきましては、所管のほうからは聞いてないところです。","voiceIndex":54,"id":"exchange-018"}]},{"id":"topic-05","title":"ふるさと納税（寄附金）におけるクレジットカード納付の導入","agenda":"ふるさと納税（寄附金）におけるクレジットカード納付の導入","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今、これ、なるべくゆうちょ銀行から取扱いが増えるように、拡充ができるようにというお話だったのだけれども、ちょっと実績、平成２７年１０月からでいつの段階だったか聞いたときは、６件で３０万円ぐらいしかないとは聞いたのだけれども、いつでもいいのだけれども、８月、７月でもいいのだけれども、実際にどれぐらいあったのか、ゆうちょでの今の実績を教えていただきたいのと、拡充をするといったって。","respondent":"黒田税務課長","answer":"ただ、総務省のほうで今問題になっていますのが返礼品競争が過熱しているというところがあって、４月１日付で国のほうから適切な対応を各自治体はとるようにという通知が出ている中で、ただ、このまま収束するというふうにも思いませんので。","voiceIndex":60,"id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"意見","question":"もちろん返礼品をどうのこうの品川がやるというのは私は反対で、今おっしゃったように返礼品合戦にならないように品川区は品川区で淡々とそれは返礼品はやっていくべきだと思うが、そうなると余計何かしょうがないのかなと思うのだけれども、そこら辺はしょうがないと思うしかないのかな。","respondent":"黒田税務課長","answer":"ただ、どうしても都市部のほうから流出するのは、人口が集積しているという面も非常に大きい部分と、やはりどうしても返礼品目当ての寄附というのが、今も書店等に行きますとふるさと納税ガイドみたいなのがありまして。","voiceIndex":62,"id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"意見","question":"一つだけ。打つ手は私もあまりないのかなと思いますが、品川区を愛している方はたくさんいらっしゃると思います。それで、どうしてこういうことを言うかというと、確かにこれは減税効果は非常にあるわけですよね。返礼品は別としても、所得のある方は減税効果があるからこれは非常に行われている。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、石田秀男委員がおっしゃっていたのですが、やはり所得の高い人が節税と返礼品をどうしても求めていく。これは純粋な税の配分にしてもやはり問題があると思うのです。私は逆に返礼品合戦に参入したほうが国にアピールできるのではないかと。やはりそういうような、逆をとらえた訴え方をして、これはやはり何らかの形で是正していかないとおかしくなると思うので、それだけちょっとお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-022"},{"speaker":"吉田委員","kind":"質問・要望","question":"それでちょっと伺いたいのが、このクレジットカードというのはいいと思うのですが、例えばその仕組みとして今後そのようなことが実現できるとして、このクレジットカードという手法を使ってもそれは可能なのかどうかだけちょっと教えていただきたいのですが、いかがでしょうか。","respondent":"黒田税務課長","answer":"この「ふるさとチョイス」というシステムは全国のいろいろな自治体が使っておりまして、今委員がご指摘いただいたように、特定の施策なりに寄附を募集している自治体もありますので、ホームページというところでいろいろな表示ができますので。","voiceIndex":66,"id":"exchange-023"},{"speaker":"吉田委員","kind":"意見","question":"いろいろな手段が考えられると思います。なかなかやはり返礼品というのは魅力的だし、節税というのもあると思いますけれども、やはり熊本で震災が起きた後、熊本へのふるさと納税みたいなのがすごく増えたということで、やはりその思いがある方、応援したいと思う方もたくさんいらっしゃるのだと思います。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-024"},{"speaker":"つる副委員長","kind":"質問・要望","question":"これがまさに打つ手の部分なのかなとちょっと思ったりするのですが、ここにかける経費と、想定で今回平成２８年度では６００万円というふるさと納税の予算立てをしているのですけれども、より一層見てもらうための工夫というのは、そうしたところに経費をかけて、最小経費の最大効果ではないけれども、どのぐらいの価格がとられるのかなというのを参考までに教えていただきたいと思うのです。","respondent":"黒田税務課長","answer":"時事通信社という通信社も同じようなサイトをやっている中で、今回協力いただきまして品川区特集ということでトップページに品川区のバナーを張っていただいたりもしたのですが、それで寄附が来たという実績が今のところないところもありますので。","voiceIndex":69,"id":"exchange-025"},{"speaker":"つる副委員長","kind":"質問・要望","question":"当然それなりの金額がかかると思います。なので、そうしたところの観点で、打てる手はしっかりと打っていただきたいと、これは要望ですけれども、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-026"}]},{"id":"topic-06","title":"債権の放棄","agenda":"債権の放棄","exchanges":[{"speaker":"吉田委員","kind":"確認","question":"すみません、確認なのですが、品川区私債権等の管理に関する条例の適用範囲なのだけれども、公債権の一部もここに入ってくるという意味なのでしょうか。公債権がここに入ってくる根拠というか、それはちゃんと書いてあるのでしょうか。その辺をちょっと。","respondent":"福島会計管理者","answer":"といいますのも、やはり非強制徴収公債権は区が自力では徴収することができませんので、裁判所に訴える等しなければいけないということで、私債権と同列に扱っているものです。","voiceIndex":76,"id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問","question":"こういうのは大変ご苦労いただいてやっていらっしゃると思うのであれなのですけれども、ちょっとお伺いしたいのは、大体平成２５年で平成２６年のほうも出てくるのですが、平成１９年とか平成２１年というのは、これはこれでやられているのだけれども、こういうのが出てくると、え、こんなころのもまだこれ以外にも一生懸命今取り立てていますよとか。","respondent":"福島会計管理者","answer":"もう少し詳しく説明しますと、１から２３までのところにつきましては、要は生活保護を受けている方で住所不定の方、そういうことで入所してました。いきなりいなくなってしまって残ってしまったという方です。","voiceIndex":78,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2054#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":30820,"voices":83}}]);
